/* ==================== DASHBOARD API ==================== */

/** Etapas visuales (flujo + cancelado). Solo presentación; no cambian estados en DB. */
const ETAPA_VISUAL = {
  PENDIENTE_APROB_PLANTA: "PENDIENTE_APROB_PLANTA",
  APROB_DIRECTOR_ZP: "APROB_DIRECTOR_ZP",
  CARRO_COMPRA: "CARRO_COMPRA",
  CUENTA_FONDOS: "CUENTA_FONDOS",
  CHEQUE_GENERADO: "CHEQUE_GENERADO",
  DEPOSITO_CIERRE: "DEPOSITO_CIERRE",
  COMPROBACIONES: "COMPROBACIONES",
  EVIDENCIAS: "EVIDENCIAS",
  CANCELADO: "CANCELADO",
};

/** Orden de columnas del Kanban: etapas de flujo + cancelados. */
const ETAPAS_VISUAL_ORDER = [
  ETAPA_VISUAL.PENDIENTE_APROB_PLANTA,
  ETAPA_VISUAL.APROB_DIRECTOR_ZP,
  ETAPA_VISUAL.CARRO_COMPRA,
  ETAPA_VISUAL.CUENTA_FONDOS,
  ETAPA_VISUAL.CHEQUE_GENERADO,
  ETAPA_VISUAL.DEPOSITO_CIERRE,
  ETAPA_VISUAL.COMPROBACIONES,
  ETAPA_VISUAL.EVIDENCIAS,
  ETAPA_VISUAL.CANCELADO,
];

/** Estatus técnico → etapa visual (una columna por etapa visual). */
function estatusToEtapaVisual(estatus) {
  const s = String(estatus || "").trim().toUpperCase();
  if (!s) return ETAPA_VISUAL.PENDIENTE_APROB_PLANTA;
  if (s === ESTADOS.CANCELADO) return ETAPA_VISUAL.CANCELADO;
  if (s === ESTADOS.CANCELACION_SOLICITADA) return ETAPA_VISUAL.APROB_DIRECTOR_ZP;
  if (s === ESTADOS.EVIDENCIAS) return ETAPA_VISUAL.EVIDENCIAS;
  if (s === ESTADOS.COMPROBACIONES) return ETAPA_VISUAL.COMPROBACIONES;
  if ([ESTADOS.PAGADO, ESTADOS.CERRADO].includes(s)) return ETAPA_VISUAL.DEPOSITO_CIERRE;
  if (ESTADOS_CHEQUE_GENERADO.includes(s)) return ETAPA_VISUAL.CHEQUE_GENERADO;
  if (s === ESTADOS.CUENTA_FONDOS) return ETAPA_VISUAL.CUENTA_FONDOS;
  if (ESTADOS_CARRO_COMPRA.includes(s)) return ETAPA_VISUAL.CARRO_COMPRA;
  if ([ESTADOS.PENDIENTE_APROB_ZP].includes(s) || /RECHAZADO_ZP/.test(s)) return ETAPA_VISUAL.APROB_DIRECTOR_ZP;
  return ETAPA_VISUAL.PENDIENTE_APROB_PLANTA;
}

/** Labels e íconos para WhatsApp y dashboard. */
const ETAPA_VISIBLE = {
  [ETAPA_VISUAL.PENDIENTE_APROB_PLANTA]: { label: "Pendiente aprobación planta", icon: "🕒" },
  [ETAPA_VISUAL.APROB_DIRECTOR_ZP]: { label: "Aprobación Director ZP", icon: "🧾" },
  [ETAPA_VISUAL.CARRO_COMPRA]: { label: "Carro de compra", icon: "🛒" },
  [ETAPA_VISUAL.CUENTA_FONDOS]: { label: "Cuenta de fondos", icon: "💰" },
  [ETAPA_VISUAL.CHEQUE_GENERADO]: { label: "Cheque Generado", icon: "📄" },
  [ETAPA_VISUAL.DEPOSITO_CIERRE]: { label: "Depósito y cierre", icon: "🏦" },
  [ETAPA_VISUAL.COMPROBACIONES]: { label: "Comprobaciones", icon: "✅" },
  [ETAPA_VISUAL.EVIDENCIAS]: { label: "Evidencias", icon: "📎" },
  [ETAPA_VISUAL.CANCELADO]: { label: "Cancelado", icon: "🔴" },
};

function getEtapaVisibleLabel(estatus) {
  const ev = estatusToEtapaVisual(estatus);
  return ETAPA_VISIBLE[ev] ? ETAPA_VISIBLE[ev].label : (estatus || "—");
}

/** Para filtros: etapa visual → lista de estatus técnicos. */
function etapaVisualToEstatusTecnicos(etapaVisual) {
  const ev = String(etapaVisual || "").trim().toUpperCase();
  if (ev === ETAPA_VISUAL.PENDIENTE_APROB_PLANTA) return [ESTADOS.GENERADO, ESTADOS.PENDIENTE_APROB_PLANTA, ESTADOS.APROB_PLANTA];
  if (ev === ETAPA_VISUAL.APROB_DIRECTOR_ZP) return [ESTADOS.PENDIENTE_APROB_ZP, ESTADOS.CANCELACION_SOLICITADA];
  if (ev === ETAPA_VISUAL.CARRO_COMPRA) return [...ESTADOS_CARRO_COMPRA];
  if (ev === ETAPA_VISUAL.CUENTA_FONDOS) return [ESTADOS.CUENTA_FONDOS];
  if (ev === ETAPA_VISUAL.CHEQUE_GENERADO) return [...ESTADOS_CHEQUE_GENERADO];
  if (ev === ETAPA_VISUAL.DEPOSITO_CIERRE) return [ESTADOS.PAGADO, ESTADOS.CERRADO];
  if (ev === ETAPA_VISUAL.COMPROBACIONES) return [ESTADOS.COMPROBACIONES];
  if (ev === ETAPA_VISUAL.EVIDENCIAS) return [ESTADOS.EVIDENCIAS];
  if (ev === ETAPA_VISUAL.CANCELADO) return [ESTADOS.CANCELADO];
  return [ev];
}

/** Estatus técnico canónico al soltar un folio en una etapa visual (drag & drop AD/ZP). */
function etapaVisualToEstatusDestino(etapaVisual) {
  const ev = String(etapaVisual || "").trim().toUpperCase();
  if (ev === ETAPA_VISUAL.PENDIENTE_APROB_PLANTA) return ESTADOS.PENDIENTE_APROB_PLANTA;
  if (ev === ETAPA_VISUAL.APROB_DIRECTOR_ZP) return ESTADOS.PENDIENTE_APROB_ZP;
  if (ev === ETAPA_VISUAL.CARRO_COMPRA) return ESTADOS.APROBADO_ZP;
  if (ev === ETAPA_VISUAL.CUENTA_FONDOS) return ESTADOS.CUENTA_FONDOS;
  if (ev === ETAPA_VISUAL.CHEQUE_GENERADO) return ESTADOS.CHEQUE_GENERADO;
  if (ev === ETAPA_VISUAL.DEPOSITO_CIERRE) return ESTADOS.PAGADO;
  if (ev === ETAPA_VISUAL.COMPROBACIONES) return ESTADOS.COMPROBACIONES;
  if (ev === ETAPA_VISUAL.EVIDENCIAS) return ESTADOS.EVIDENCIAS;
  if (ev === ETAPA_VISUAL.CANCELADO) return ESTADOS.CANCELADO;
  return null;
}

function getEtapaVisibleForWhatsApp(estatus) {
  const ev = estatusToEtapaVisual(estatus);
  const o = ETAPA_VISIBLE[ev];
  return o ? `${o.icon} ${o.label}` : (estatus || "—");
}

/** Orden de etapas técnicas (legacy/filtros); Kanban usa ETAPAS_VISUAL_ORDER. */
const ETAPAS_ORDER = [
  ESTADOS.GENERADO,
  ESTADOS.PENDIENTE_APROB_PLANTA,
  ESTADOS.APROB_PLANTA,
  ESTADOS.PENDIENTE_APROB_ZP,
  ESTADOS.APROBADO_ZP,
  ESTADOS.LISTO_PARA_PROGRAMACION,
  ESTADOS.SELECCIONADO_SEMANA,
  ESTADOS.SOLICITANDO_PAGO,
  ESTADOS.CUENTA_FONDOS,
  ESTADOS.CHEQUE_GENERADO,
  ESTADOS.PAGADO,
  ESTADOS.CERRADO,
  ESTADOS.COMPROBACIONES,
  ESTADOS.EVIDENCIAS,
  ESTADOS.CANCELACION_SOLICITADA,
  ESTADOS.CANCELADO,
];
const CATEGORIAS_FOLIO = ["GASTOS", "INVERSIONES", "DYO", "TALLER"];

function parseDashboardFilters(q) {
  const plantas = (q.planta_id || q.plantas || q.planta || "")
    .toString()
    .split(",")
    .map((s) => parseInt(s, 10))
    .filter((n) => Number.isFinite(n) && n > 0);
  const categorias = (q.categoria || q.categorias || "")
    .toString()
    .split(",")
    .map((s) => String(s).trim().toUpperCase())
    .filter(Boolean);
  const etapas = (q.etapa || q.etapas || "")
    .toString()
    .split(",")
    .map((s) => String(s).trim().toUpperCase())
    .filter(Boolean);
  const soloActivos = q.solo_activos === "true" || q.solo_activos === "1" || q.activos === "1";
  const miSemana = q.mi_semana === "true" || q.mi_semana === "1";
  let fechaDesde = q.fecha_desde || q.desde || null;
  let fechaHasta = q.fecha_hasta || q.hasta || null;
  let fechaAprobDesde = q.fecha_aprob_desde || null;
  let fechaAprobHasta = q.fecha_aprob_hasta || null;
  const mes = (q.mes && /^\d{4}-\d{2}$/.test(String(q.mes).trim())) ? String(q.mes).trim() : null;
  const mesesExtra = (q.meses_extra || q.meses || "")
    .toString()
    .split(",")
    .map((s) => String(s).trim())
    .filter((s) => /^\d{4}-\d{2}$/.test(s));
  // Ventana por defecto: mes_cargo actual + creados mes actual y mes pasado (on por defecto).
  const ventanaDefault =
    q.ventana === "0" || q.ventana === "false" || q.sin_ventana === "1" || q.sin_ventana === "true"
      ? false
      : true;
  if (fechaDesde && !/^\d{4}-\d{2}-\d{2}$/.test(fechaDesde)) fechaDesde = null;
  if (fechaHasta && !/^\d{4}-\d{2}-\d{2}$/.test(fechaHasta)) fechaHasta = null;
  if (fechaAprobDesde && !/^\d{4}-\d{2}-\d{2}$/.test(fechaAprobDesde)) fechaAprobDesde = null;
  if (fechaAprobHasta && !/^\d{4}-\d{2}-\d{2}$/.test(fechaAprobHasta)) fechaAprobHasta = null;
  return {
    plantas,
    categorias,
    etapas,
    soloActivos,
    miSemana,
    fechaDesde,
    fechaHasta,
    fechaAprobDesde,
    fechaAprobHasta,
    mes,
    mesesExtra,
    ventanaDefault,
  };
}

/** Meses YYYY-MM actuales en America/Mexico_City: [mesActual, mesAnterior]. */
function getMesActualYAnteriorMx() {
  const fmt = new Intl.DateTimeFormat("en-CA", {
    timeZone: "America/Mexico_City",
    year: "numeric",
    month: "2-digit",
  });
  const parts = fmt.formatToParts(new Date());
  const y = Number(parts.find((p) => p.type === "year")?.value);
  const m = Number(parts.find((p) => p.type === "month")?.value);
  const mesActual = `${y}-${String(m).padStart(2, "0")}`;
  let py = y;
  let pm = m - 1;
  if (pm < 1) {
    pm = 12;
    py -= 1;
  }
  const mesAnterior = `${py}-${String(pm).padStart(2, "0")}`;
  return { mesActual, mesAnterior };
}

function buildDashboardWhere(auth, filters) {
  const conditions = [];
  const params = [];
  let n = 1;
  // Normalizar role del token (p. ej. "AD", "ad", " AD ") para Asistente de Dirección; CF_CDMX = Contralor financiero CDMX (solo ver)
  const roleNorm = (auth.role != null && auth.role !== "" ? String(auth.role).replace(/\s/g, "").toUpperCase() : "") || "";
  const esZP = roleNorm === "ZP";
  const esAD = roleNorm === "AD";
  const esCFCDMX = roleNorm === "CF_CDMX";
  // Por defecto ZP/AD ven privados; otros roles no, salvo permiso acceso_ver_folios_solo_zp_ad.
  if (!authCanVerFoliosSoloZpAd(auth)) {
    conditions.push("(COALESCE(f.solo_zp_ad, false) = false)");
  }
  if (!esZP && !esAD && !esCFCDMX) {
    conditions.push("(f.creado_por_rol_clave IS NULL OR UPPER(TRIM(COALESCE(f.creado_por_rol_clave,''))) <> 'AD')");
  }
  if (roleNorm === "GG" || roleNorm === "GA") {
    if (auth.plantas_permitidas && auth.plantas_permitidas.length > 0) {
      conditions.push(`f.planta_id = ANY($${n}::INT[])`);
      params.push(auth.plantas_permitidas);
      n++;
    } else {
      conditions.push("f.planta_id = -1");
    }
  }
  if (filters.plantas && filters.plantas.length > 0) {
    const plantasExpandidas = [];
    for (const pid of filters.plantas) {
      plantasExpandidas.push(...getPlantaIdsEquivalentesForPendientes(pid));
    }
    const plantasUnicas = [...new Set(plantasExpandidas)].filter((id) => Number.isFinite(id) && id > 0);
    if (plantasUnicas.length > 0) {
      conditions.push(`f.planta_id = ANY($${n}::INT[])`);
      params.push(plantasUnicas);
      n++;
    }
  }
  if (filters.categorias && filters.categorias.length > 0) {
    conditions.push(`UPPER(TRIM(COALESCE(f.categoria,''))) = ANY($${n}::TEXT[])`);
    params.push(filters.categorias);
    n++;
  }
  if (filters.etapas && filters.etapas.length > 0) {
    const estatusList = [];
    for (const e of filters.etapas) {
      const ev = String(e).trim().toUpperCase();
      if (ETAPAS_VISUAL_ORDER.includes(ev)) {
        estatusList.push(...etapaVisualToEstatusTecnicos(ev));
      } else {
        estatusList.push(ev);
      }
    }
    const uniq = [...new Set(estatusList)];
    if (uniq.length > 0) {
      conditions.push(`UPPER(TRIM(COALESCE(f.estatus,''))) = ANY($${n}::TEXT[])`);
      params.push(uniq);
      n++;
    }
  }
  if (filters.soloActivos) {
    conditions.push(`UPPER(TRIM(COALESCE(f.estatus,''))) NOT IN ('CERRADO','CANCELADO')`);
  }
  if (filters.miSemana) {
    conditions.push(`UPPER(TRIM(COALESCE(f.estatus,''))) = 'SELECCIONADO_SEMANA'`);
  }
  // Filtro legacy: un solo mes_cargo exacto
  if (filters.mes) {
    conditions.push(`(f.mes_cargo = $${n}::TEXT)`);
    params.push(filters.mes);
    n++;
  }
  // Ventana por defecto (+ meses extra):
  // - mes_cargo = mes anterior OR >= mes actual (incluye futuros Ago/Sep/…) OR en extras
  // - OR creado en mes actual / anterior / extras
  if (filters.ventanaDefault !== false && !filters.mes) {
    const { mesActual, mesAnterior } = getMesActualYAnteriorMx();
    const extras = Array.isArray(filters.mesesExtra) ? filters.mesesExtra : [];
    const mesesCreado = [...new Set([mesActual, mesAnterior, ...extras])];
    conditions.push(
      `(
        (
          f.mes_cargo IS NOT NULL AND TRIM(f.mes_cargo) <> ''
          AND (
            f.mes_cargo = $${n}::TEXT
            OR f.mes_cargo >= $${n + 1}::TEXT
            OR (cardinality($${n + 2}::TEXT[]) > 0 AND f.mes_cargo = ANY($${n + 2}::TEXT[]))
          )
        )
        OR to_char((f.creado_en AT TIME ZONE 'America/Mexico_City'), 'YYYY-MM') = ANY($${n + 3}::TEXT[])
      )`
    );
    params.push(mesAnterior);
    params.push(mesActual);
    params.push(extras);
    params.push(mesesCreado);
    n += 4;
  } else if (filters.mesesExtra && filters.mesesExtra.length > 0 && !filters.mes) {
    // Sin ventana default pero con meses extra explícitos
    const extras = filters.mesesExtra;
    conditions.push(
      `(
        (f.mes_cargo IS NOT NULL AND TRIM(f.mes_cargo) <> '' AND f.mes_cargo = ANY($${n}::TEXT[]))
        OR to_char((f.creado_en AT TIME ZONE 'America/Mexico_City'), 'YYYY-MM') = ANY($${n}::TEXT[])
      )`
    );
    params.push(extras);
    n++;
  }
  // Fecha de creación
  if (filters.fechaDesde) {
    conditions.push(`((f.creado_en AT TIME ZONE 'America/Mexico_City')::DATE >= $${n}::DATE)`);
    params.push(filters.fechaDesde);
    n++;
  }
  if (filters.fechaHasta) {
    conditions.push(`((f.creado_en AT TIME ZONE 'America/Mexico_City')::DATE <= $${n}::DATE)`);
    params.push(filters.fechaHasta);
    n++;
  }
  // Fecha de aprobación (aprobado_en)
  if (filters.fechaAprobDesde) {
    conditions.push(`(f.aprobado_en IS NOT NULL AND (f.aprobado_en AT TIME ZONE 'America/Mexico_City')::DATE >= $${n}::DATE)`);
    params.push(filters.fechaAprobDesde);
    n++;
  }
  if (filters.fechaAprobHasta) {
    conditions.push(`(f.aprobado_en IS NOT NULL AND (f.aprobado_en AT TIME ZONE 'America/Mexico_City')::DATE <= $${n}::DATE)`);
    params.push(filters.fechaAprobHasta);
    n++;
  }
  const where = conditions.length ? " AND " + conditions.join(" AND ") : "";
  return { where, params };
}

function cardFromFolioRow(row) {
  const creado = row.creado_en ? new Date(row.creado_en) : null;
  const aging = creado ? Math.floor((Date.now() - creado.getTime()) / (24 * 60 * 60 * 1000)) : null;
  return {
    id: row.id,
    numero_folio: row.numero_folio,
    folio_codigo: row.folio_codigo,
    planta_id: row.planta_id,
    planta_nombre: row.planta_nombre || null,
    beneficiario: row.beneficiario || null,
    categoria: row.categoria || null,
    subcategoria: row.subcategoria || null,
    unidad: row.unidad || null,
    importe: row.importe != null ? Number(row.importe) : null,
    estatus: row.estatus || null,
    // Texto completo para búsqueda; la card recorta visualmente con line-clamp.
    descripcion: (row.descripcion_display || row.concepto || "").toString(),
    creado_en: row.creado_en,
    aging,
    tiene_cotizacion: !!row.tiene_cotizacion,
    solo_zp_ad: !!row.solo_zp_ad,
    por_recuperar: !!row.por_recuperar,
    prioridad: row.prioridad || null,
    solicitud_por_recuperar_pendiente: !!row.solicitud_por_recuperar_pendiente,
    mes_cargo: row.mes_cargo || null,
    proyecto_id: row.proyecto_id != null ? row.proyecto_id : null,
    proyecto_codigo: row.proyecto_codigo || null,
    proyecto_nombre: row.proyecto_nombre || null,
    prestamo_a_planta: row.prestamo_a_planta != null && String(row.prestamo_a_planta).trim() !== "" ? String(row.prestamo_a_planta).trim() : null,
    prestamo_siguiente_mes: !!row.prestamo_siguiente_mes,
    monto_comprobado: row.monto_comprobado != null ? Number(row.monto_comprobado) : 0,
    numero_cheque: row.numero_cheque != null && String(row.numero_cheque).trim() !== "" ? String(row.numero_cheque).trim() : null,
  };
}

app.get("/api/dashboard/kanban", dashboardAuthMiddleware, async (req, res) => {
  if (dashboardBlockGVForbidden(req, res)) return;
  const client = await pool.connect();
  try {
    const filters = parseDashboardFilters(req.query);
    const { where, params } = buildDashboardWhere(req.dashboardAuth, filters);
    const q = `
      SELECT f.id, f.numero_folio, f.folio_codigo, f.planta_id, f.categoria, f.subcategoria, f.unidad,
             f.importe, f.estatus, f.creado_en, f.prioridad, f.mes_cargo, f.beneficiario, f.proyecto_id,
             f.prestamo_a_planta, f.numero_cheque,
             COALESCE(f.solo_zp_ad, false) AS solo_zp_ad, COALESCE(f.por_recuperar, false) AS por_recuperar,
             COALESCE(f.solicitud_por_recuperar_pendiente, false) AS solicitud_por_recuperar_pendiente,
             COALESCE(f.prestamo_siguiente_mes, false) AS prestamo_siguiente_mes,
             COALESCE(f.descripcion, f.concepto) AS descripcion_display,
             p.nombre AS planta_nombre,
             pr.codigo AS proyecto_codigo, pr.nombre AS proyecto_nombre,
             (
               EXISTS (
                 SELECT 1
                 FROM public.folio_archivos fa
                 WHERE fa.folio_id = f.id
                   AND fa.tipo = 'COTIZACION'
                   AND fa.status NOT IN ('RECHAZADO', 'ELIMINADO', 'REEMPLAZADO')
               )
               OR f.cotizacion_s3key IS NOT NULL
               OR f.cotizacion_url IS NOT NULL
             ) AS tiene_cotizacion,
             (
               SELECT COALESCE(SUM(fa2.monto), 0)
               FROM public.folio_archivos fa2
               WHERE fa2.folio_id = f.id
                 AND UPPER(TRIM(fa2.tipo)) = 'FACTURA'
                 AND fa2.status NOT IN ('RECHAZADO', 'ELIMINADO', 'REEMPLAZADO')
             ) AS monto_comprobado
      FROM public.folios f
      LEFT JOIN public.plantas p ON p.id = f.planta_id
      LEFT JOIN public.proyectos pr ON pr.id = f.proyecto_id
      WHERE 1=1 ${where}
      ORDER BY f.creado_en ASC NULLS LAST
    `;
    const r = await client.query(q, params);
    // Auto-avance: Depósito con comprobado >= importe → Comprobaciones (antes de armar tablero)
    for (const row of r.rows || []) {
      const est = String(row.estatus || "").trim().toUpperCase();
      if (est !== ESTADOS.PAGADO && est !== ESTADOS.CERRADO) continue;
      const importe = row.importe != null ? Number(row.importe) : null;
      const comprobado = row.monto_comprobado != null ? Number(row.monto_comprobado) : 0;
      if (importe == null || !Number.isFinite(importe) || comprobado + 0.009 < importe) continue;
      try {
        const moved = await maybeAdvanceFolioToComprobaciones(client, row, "Dashboard");
        if (moved.moved) {
          row.estatus = ESTADOS.COMPROBACIONES;
        }
      } catch (e) {
        console.warn("[kanban] auto COMPROBACIONES", row.id, e && e.message);
      }
    }
    const rows = r.rows || [];
    const byEtapa = {};
    ETAPAS_VISUAL_ORDER.forEach((e) => { byEtapa[e] = []; });
    rows.forEach((row) => {
      const etapaVisual = estatusToEtapaVisual(row.estatus);
      if (!byEtapa[etapaVisual]) byEtapa[etapaVisual] = [];
      byEtapa[etapaVisual].push(row);
    });
    const plantasList = await getPlantas(client);
    const nombreByPlantaId = {};
    (plantasList || []).forEach((p) => { nombreByPlantaId[p.id] = p.nombre || p.clave || `Planta ${p.id}`; });
    const auth = req.dashboardAuth;
    const roleNorm = (auth.role != null && auth.role !== "" ? String(auth.role).replace(/\s/g, "").toUpperCase() : "") || "";
    const visiblePlantIds = (roleNorm === "GG" || roleNorm === "GA") && auth.plantas_permitidas && auth.plantas_permitidas.length > 0
      ? auth.plantas_permitidas
      : (plantasList || []).map((p) => p.id);
    const canonicalIdsParaCrear = [...new Set(visiblePlantIds.map((pid) => getCanonicalPlantaId(pid)).filter((cid) => cid != null && cid > 0))];
    const board = ETAPAS_VISUAL_ORDER.map((etapa) => {
      const folios = byEtapa[etapa] || [];
      const meta = ETAPA_VISIBLE[etapa] || { label: etapa, icon: "" };
      const count = folios.length;
      const totalMxn = folios.reduce((s, f) => s + (Number(f.importe) || 0), 0);
      const agings = folios.map((f) => {
        const d = f.creado_en ? new Date(f.creado_en) : null;
        return d ? Math.floor((Date.now() - d.getTime()) / (24 * 60 * 60 * 1000)) : 0;
      }).filter((a) => a >= 0);
      const avgAging = agings.length ? Math.round(agings.reduce((s, a) => s + a, 0) / agings.length) : null;
      const byPlanta = {};
      folios.forEach((f) => {
        const pid = f.planta_id != null ? f.planta_id : 0;
        const cid = pid ? getCanonicalPlantaId(pid) : 0;
        const pnom = (cid && nombreByPlantaId[cid]) ? nombreByPlantaId[cid] : (f.planta_nombre || "Sin planta");
        if (!byPlanta[cid]) byPlanta[cid] = { planta_id: cid, planta_nombre: pnom, folios: [] };
        byPlanta[cid].folios.push(f);
      });
      if (etapa === "PENDIENTE_APROB_PLANTA") {
        canonicalIdsParaCrear.forEach((cid) => {
          if (!byPlanta[cid]) {
            byPlanta[cid] = {
              planta_id: cid,
              planta_nombre: nombreByPlantaId[cid] || `Planta ${cid}`,
              folios: [],
            };
          }
        });
      }
      const plantas = Object.values(byPlanta).map((p) => {
        const fols = p.folios;
        const pCount = fols.length;
        const pTotal = fols.reduce((s, f) => s + (Number(f.importe) || 0), 0);
        const pAgings = fols.map((f) => {
          const d = f.creado_en ? new Date(f.creado_en) : null;
          return d ? Math.floor((Date.now() - d.getTime()) / (24 * 60 * 60 * 1000)) : 0;
        }).filter((a) => a >= 0);
        const pAvgAging = pAgings.length ? Math.round(pAgings.reduce((s, a) => s + a, 0) / pAgings.length) : null;
        const porCategoria = { GASTOS: [], INVERSIONES: [], DYO: [], TALLER: [] };
        function categoriaToKey(categoria) {
          const c = (categoria || "").toString().trim().toUpperCase() || "GASTOS";
          if (CATEGORIAS_FOLIO.includes(c)) return c;
          if (c.includes("TALLER")) return "TALLER";
          if (c === "DYO" || c.includes("DERECHOS") || c.includes("OBLIGACIONES")) return "DYO";
          if (c.includes("INVERSION")) return "INVERSIONES";
          return "GASTOS";
        }
        fols.forEach((f) => {
          const key = categoriaToKey(f.categoria);
          porCategoria[key].push(cardFromFolioRow(f));
        });
        return {
          planta_id: p.planta_id,
          planta_nombre: p.planta_nombre,
          stats: { count: pCount, total_mxn: pTotal || null, avg_aging: pAvgAging },
          porCategoria,
        };
      });
      return {
        etapa,
        etapa_label: meta.label,
        etapa_icon: meta.icon,
        stats: { count, total_mxn: totalMxn || null, avg_aging: avgAging },
        plantas,
      };
    });
    res.json({
      meta: { filters, role: req.dashboardAuth.role },
      etapas: ETAPAS_VISUAL_ORDER,
      categorias: CATEGORIAS_FOLIO,
      board,
    });
  } catch (e) {
    console.error("[Dashboard kanban]", e);
    res.status(500).json({ error: e.message });
  } finally {
    client.release();
  }
});

/** Clave para incluir folios solo_zp_ad en Clasificación de apoyos / Excel. */
const CLASIFICACION_PRIV_CLAVE = "Tomza-Priv";
/** Misma clave para el panel de administración de usuarios (IGF Forecast). */
const USUARIOS_ADMIN_CLAVE = CLASIFICACION_PRIV_CLAVE;
function clasificacionIncluyePrivados(req) {
  return String(req.query.priv_clave || "").trim() === CLASIFICACION_PRIV_CLAVE;
}

function assertUsuariosAdminClave(req) {
  const fromBody = req.body && req.body.clave != null ? String(req.body.clave) : "";
  const fromQuery = req.query && req.query.clave != null ? String(req.query.clave) : "";
  const fromHeader = req.headers["x-usuarios-admin-clave"] != null ? String(req.headers["x-usuarios-admin-clave"]) : "";
  return [fromBody, fromQuery, fromHeader].some((c) => String(c || "").trim() === USUARIOS_ADMIN_CLAVE);
}

/**
 * Solo overrides respecto al default del rol.
 * Embeber el mapa completo hincha el JWT (~1000+ chars) y WhatsApp deja de
 * hipervincular la URL entera → "Acceso no autorizado". Sin overrides el
 * backend/frontend usan los permisos del rol.
 */
function permisosForDashboardToken(role, usuarioRow) {
  const effective = usuarioPermisos.permisosEfectivos(role, usuarioRow && usuarioRow.permisos_json);
  const base = usuarioPermisos.permisosPorRol(role);
  const overrides = {};
  let any = false;
  for (const k of usuarioPermisos.PERMISO_CLAVES) {
    if (!!effective[k] !== !!base[k]) {
      overrides[k] = !!effective[k];
      any = true;
    }
  }
  return any ? overrides : undefined;
}

/** ¿Puede ver folios marcados Solo ZP/AD (privados)? */
function authCanVerFoliosSoloZpAd(auth) {
  return usuarioPermisos.authHasPermiso(auth, "acceso_ver_folios_solo_zp_ad");
}

/** ¿Puede marcar/desmarcar Solo ZP y AD (hacer privado)? */
function authCanMarcarSoloZpAd(auth) {
  return usuarioPermisos.authHasPermiso(auth, "acceso_marcar_solo_zp_ad");
}

function mapUsuarioAdminRow(row) {
  const rolClave = (row.rol_clave && String(row.rol_clave).toUpperCase()) || "";
  const permisos = usuarioPermisos.permisosEfectivos(rolClave, row.permisos_json);
  return {
    id: row.id,
    telefono: row.telefono || "",
    email: row.email || "",
    nombre: row.nombre || "",
    nombre_persona: row.nombre_persona || "",
    activo: row.activo !== false,
    planta_id: row.planta_id != null ? Number(row.planta_id) : null,
    planta_nombre: row.planta_nombre || (row.planta_id == null ? "Sin planta" : `Planta ${row.planta_id}`),
    rol_id: row.rol_id != null ? Number(row.rol_id) : null,
    rol_nombre: row.rol_nombre || "",
    rol_clave: rolClave,
    permisos_personalizados: row.permisos_json != null,
    permisos,
  };
}

/**
 * Excel Clasificación de apoyos — hoja COMPARATIVOS.
 * Query: mes_a=YYYY-MM (izq), mes_b=YYYY-MM (der). Incluye folios no cancelados con ese mes_cargo.
 * priv_clave=Tomza-Priv → incluye también folios Solo ZP/AD (privados).
 */
app.get("/api/dashboard/clasificacion-apoyos-excel", dashboardAuthMiddleware, async (req, res) => {
  if (dashboardBlockGVForbidden(req, res)) return;
  const mesA = String(req.query.mes_a || "").trim();
  const mesB = String(req.query.mes_b || "").trim();
  const plantaIdRaw = req.query.planta_id != null && String(req.query.planta_id).trim() !== ""
    ? Number(req.query.planta_id)
    : null;
  const plantaId = Number.isFinite(plantaIdRaw) ? plantaIdRaw : null;
  const includePrivados = clasificacionIncluyePrivados(req);
  if (!/^\d{4}-\d{2}$/.test(mesA) || !/^\d{4}-\d{2}$/.test(mesB)) {
    return res.status(400).json({ error: "mes_a y mes_b son obligatorios (YYYY-MM)" });
  }
  if (mesA === mesB) {
    return res.status(400).json({ error: "Los meses a comparar deben ser distintos" });
  }
  const plantasFiltro = clasificacionApoyosExcel.resolvePlantasComparativo(plantaId);
  const idsFiltro = [...new Set(plantasFiltro.flatMap((p) => p.ids || []))];
  const privSql = includePrivados ? "" : " AND COALESCE(f.solo_zp_ad, false) = false";
  const client = await pool.connect();
  try {
    const r = await client.query(
      `SELECT f.planta_id, f.categoria, f.subcategoria, f.unidad, f.importe, f.mes_cargo
       FROM public.folios f
       WHERE f.mes_cargo = ANY($1::text[])
         AND UPPER(TRIM(COALESCE(f.estatus,''))) <> 'CANCELADO'
         AND f.planta_id IS NOT NULL
         AND f.planta_id = ANY($2::int[])
         ${privSql}`,
      [[mesA, mesB], idsFiltro]
    );
    // Detalle GASTOS / INVERSIONES / TALLER por planta (E7 G → E7 I → E7 T …).
    const hojasPlantaAll = clasificacionApoyosExcel.PLANTAS_DETALLE_SHEETS || clasificacionApoyosExcel.PLANTAS_GASTOS_SHEETS || [];
    const hojasPlanta = plantaId != null
      ? hojasPlantaAll.filter((p) => (p.ids || []).includes(plantaId))
      : hojasPlantaAll;
    const hojasUsar = hojasPlanta.length ? hojasPlanta : hojasPlantaAll;
    const allPlantIds = [...new Set(hojasUsar.flatMap((p) => p.ids || []))];
    const idToClave = new Map();
    hojasUsar.forEach((p) => (p.ids || []).forEach((id) => idToClave.set(Number(id), p.clave)));
    const detalleGastosByPlanta = {};
    const detalleInversionesByPlanta = {};
    const detalleTallerByPlanta = {};
    hojasUsar.forEach((p) => {
      detalleGastosByPlanta[p.clave] = [];
      detalleInversionesByPlanta[p.clave] = [];
      detalleTallerByPlanta[p.clave] = [];
    });
    try {
      if (allPlantIds.length) {
        const mesSiguiente = (() => {
          const m = mesA.match(/^(\d{4})-(\d{2})$/);
          if (!m) return null;
          let y = parseInt(m[1], 10);
          let mo = parseInt(m[2], 10) + 1;
          if (mo > 12) {
            mo = 1;
            y += 1;
          }
          return `${y}-${String(mo).padStart(2, "0")}`;
        })();
        const d = await client.query(
          `SELECT f.id, f.planta_id, f.categoria, f.subcategoria, f.unidad, f.concepto, f.importe, f.mes_cargo, f.estatus,
                  f.detalle_lineas, f.numero_folio, f.numero_cheque, f.prestamo_a_planta,
                  COALESCE(f.prestamo_siguiente_mes, false) AS prestamo_siguiente_mes,
                  COALESCE(f.por_recuperar, false) AS por_recuperar,
                  (
                    SELECT MIN(h.creado_en)
                      FROM public.folio_historial h
                     WHERE (h.folio_id = f.id OR (f.numero_folio IS NOT NULL AND h.numero_folio = f.numero_folio))
                       AND UPPER(TRIM(COALESCE(h.estatus,''))) IN ('PAGADO','CERRADO')
                  ) AS fecha_envio
             FROM public.folios f
            WHERE f.planta_id = ANY($2::int[])
              AND UPPER(TRIM(COALESCE(f.estatus,''))) <> 'CANCELADO'
              AND (
                f.mes_cargo = $1
                OR (
                  $3::text IS NOT NULL
                  AND f.mes_cargo = $3
                  AND COALESCE(f.prestamo_siguiente_mes, false) = TRUE
                )
              )
              ${privSql}
              AND (
                UPPER(TRIM(COALESCE(f.categoria,''))) = 'GASTOS'
                OR UPPER(TRIM(COALESCE(f.categoria,''))) LIKE '%GASTO%'
                OR UPPER(TRIM(COALESCE(f.categoria,''))) = 'INVERSIONES'
                OR UPPER(TRIM(COALESCE(f.categoria,''))) LIKE '%INVERSION%'
                OR UPPER(TRIM(COALESCE(f.categoria,''))) = 'TALLER'
                OR UPPER(TRIM(COALESCE(f.categoria,''))) LIKE '%TALLER%'
              )
            ORDER BY f.planta_id, f.subcategoria NULLS LAST, f.id`,
          [mesA, allPlantIds, mesSiguiente]
        );
        for (const row of d.rows || []) {
          const clave = idToClave.get(Number(row.planta_id));
          if (!clave) continue;
          const cat = String(row.categoria || "").trim().toUpperCase();
          if (cat === "TALLER" || cat.includes("TALLER")) {
            detalleTallerByPlanta[clave].push(row);
          } else if (cat === "INVERSIONES" || cat.includes("INVERSION")) {
            detalleInversionesByPlanta[clave].push(row);
          } else {
            detalleGastosByPlanta[clave].push(row);
          }
        }
      }
    } catch (eDet) {
      console.warn("[clasificacion-apoyos-excel] detalle gastos/inversiones/taller por planta:", eDet.message);
    }

    let detalleMovimientos = [];
    try {
      if (allPlantIds.length) {
        const mesSiguienteMov = (() => {
          const m = mesA.match(/^(\d{4})-(\d{2})$/);
          if (!m) return null;
          let y = parseInt(m[1], 10);
          let mo = parseInt(m[2], 10) + 1;
          if (mo > 12) {
            mo = 1;
            y += 1;
          }
          return `${y}-${String(mo).padStart(2, "0")}`;
        })();
        const mov = await client.query(
          `WITH rechazos AS (
             SELECT COALESCE(h.folio_id, f.id) AS folio_id,
                    MIN(h.creado_en) AS fecha_rechazo
               FROM public.folio_historial h
               LEFT JOIN public.folios f
                 ON f.id = h.folio_id
                 OR (
                   h.folio_id IS NULL
                   AND f.numero_folio IS NOT NULL
                   AND TRIM(f.numero_folio) <> ''
                   AND f.numero_folio = h.numero_folio
                 )
              WHERE h.comentario ILIKE '%RECHAZO CDJZ%'
                AND h.comentario ILIKE ('%' || $1::text || '%')
                AND COALESCE(h.folio_id, f.id) IS NOT NULL
              GROUP BY COALESCE(h.folio_id, f.id)
           )
           SELECT f.id, f.planta_id, f.categoria, f.subcategoria, f.unidad, f.concepto, f.importe,
                  f.mes_cargo, f.estatus, f.detalle_lineas, f.numero_folio, f.folio_codigo, f.numero_cheque,
                  f.prestamo_a_planta,
                  COALESCE(f.prestamo_siguiente_mes, false) AS prestamo_siguiente_mes,
                  COALESCE(f.por_recuperar, false) AS por_recuperar,
                  r.fecha_rechazo,
                  (
                    SELECT MIN(h2.creado_en)
                      FROM public.folio_historial h2
                     WHERE (h2.folio_id = f.id
                            OR (f.numero_folio IS NOT NULL AND h2.numero_folio = f.numero_folio))
                       AND h2.creado_en > r.fecha_rechazo
                       AND $3::text IS NOT NULL
                       AND (
                         (h2.comentario ILIKE '%Mes de cargo%' AND h2.comentario ILIKE ('%' || $3::text || '%'))
                         OR (h2.comentario ILIKE '%siguiente mes%' AND h2.comentario ILIKE ('%' || $3::text || '%'))
                       )
                  ) AS fecha_reagendada,
                  (
                    SELECT MIN(h3.creado_en)
                      FROM public.folio_historial h3
                     WHERE (h3.folio_id = f.id
                            OR (f.numero_folio IS NOT NULL AND h3.numero_folio = f.numero_folio))
                       AND UPPER(TRIM(COALESCE(h3.estatus,''))) IN ('PAGADO','CERRADO')
                  ) AS fecha_envio
             FROM rechazos r
             JOIN public.folios f ON f.id = r.folio_id
            WHERE f.planta_id = ANY($2::int[])
              AND UPPER(TRIM(COALESCE(f.estatus,''))) <> 'CANCELADO'
              ${privSql}
            ORDER BY f.planta_id, f.categoria NULLS LAST, f.id`,
          [mesA, allPlantIds, mesSiguienteMov]
        );
        detalleMovimientos = mov.rows || [];
      }
    } catch (eMov) {
      console.warn("[clasificacion-apoyos-excel] hoja Movimientos:", eMov.message);
    }

    const wb = await clasificacionApoyosExcel.buildClasificacionApoyosWorkbook(r.rows, mesA, mesB, {
      detalleGastosByPlanta,
      detalleInversionesByPlanta,
      detalleTallerByPlanta,
      detalleMovimientos,
      plantaId,
    });
    const buf = Buffer.from(await wb.xlsx.writeBuffer());
    const safeA = clasificacionApoyosExcel.mesLabelEs(mesA).replace(/\s+/g, "_");
    const safeB = clasificacionApoyosExcel.mesLabelEs(mesB).replace(/\s+/g, "_");
    const plantaSuffix = plantasFiltro.length === 1
      ? `_${plantasFiltro[0].label.replace(/\s+/g, "_")}`
      : "";
    const filename = `Clasificacion_Apoyos_${safeA}_vs_${safeB}${plantaSuffix}.xlsx`;
    res.setHeader("Content-Type", "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet");
    res.setHeader("Content-Disposition", `attachment; filename="${filename}"`);
    return res.send(buf);
  } catch (e) {
    console.error("[clasificacion-apoyos-excel]", e);
    res.status(500).json({ error: e.message || "Error al generar Excel" });
  } finally {
    client.release();
  }
});

/**
 * Excel Taller por AT: Resumen (unidad × meses) + detalle por mes + duplicados.
 * Incluye todos los TALLER no cancelados (mismo criterio que Clasificación listado T).
 * El importe efectivo es f.importe o la suma de detalle_lineas; la subcategoría
 * (MAYOR / PASIVO / PREVENTIVO / OTROS) solo clasifica ese mismo monto.
 * Query: mes_desde, mes_hasta (YYYY-MM), planta_id opcional.
 * priv_clave=Tomza-Priv (opcional) → incluye folios Solo ZP/AD (privados). Vacío = sin privados.
 */
app.get("/api/dashboard/taller-at-excel", dashboardAuthMiddleware, async (req, res) => {
  if (dashboardBlockGVForbidden(req, res)) return;
  const includePrivados = clasificacionIncluyePrivados(req);
  let mesDesde = String(req.query.mes_desde || "").trim();
  let mesHasta = String(req.query.mes_hasta || "").trim();
  if (!/^\d{4}-\d{2}$/.test(mesDesde) || !/^\d{4}-\d{2}$/.test(mesHasta)) {
    return res.status(400).json({ error: "mes_desde y mes_hasta son obligatorios (YYYY-MM)" });
  }
  if (mesDesde > mesHasta) {
    const t = mesDesde;
    mesDesde = mesHasta;
    mesHasta = t;
  }
  const plantaIdRaw =
    req.query.planta_id != null && String(req.query.planta_id).trim() !== ""
      ? Number(req.query.planta_id)
      : null;
  const plantaId = Number.isFinite(plantaIdRaw) ? plantaIdRaw : null;

  const client = await pool.connect();
  try {
    const filters = parseDashboardFilters({});
    // Con clave correcta: incluir privados. Sin clave: forzar exclusión aunque el rol los vea.
    const authForQuery = {
      ...req.dashboardAuth,
      permisos: {
        ...(req.dashboardAuth && req.dashboardAuth.permisos ? req.dashboardAuth.permisos : {}),
        acceso_ver_folios_solo_zp_ad: includePrivados,
      },
    };
    const { where, params } = buildDashboardWhere(authForQuery, {
      ...filters,
      soloActivos: false,
      ventanaDefault: false,
    });
    let n = params.length;
    const extra = [];
    n += 1;
    extra.push(`f.mes_cargo >= $${n}::text`);
    params.push(mesDesde);
    n += 1;
    extra.push(`f.mes_cargo <= $${n}::text`);
    params.push(mesHasta);
    extra.push(`UPPER(TRIM(COALESCE(f.categoria,''))) LIKE '%TALLER%'`);
    extra.push(`UPPER(TRIM(COALESCE(f.estatus,''))) <> 'CANCELADO'`);
    if (plantaId != null) {
      const ids = getPlantaIdsEquivalentesForPendientes(plantaId);
      n += 1;
      extra.push(`f.planta_id = ANY($${n}::int[])`);
      params.push(ids.length ? ids : [plantaId]);
    }
    const q = `
      SELECT f.id,
             f.numero_folio,
             f.planta_id,
             p.nombre AS planta_nombre,
             f.unidad,
             f.subcategoria,
             COALESCE(NULLIF(TRIM(f.descripcion), ''), NULLIF(TRIM(f.concepto), ''), '') AS concepto,
             f.importe,
             f.detalle_lineas,
             f.mes_cargo,
             f.estatus
        FROM public.folios f
        LEFT JOIN public.plantas p ON p.id = f.planta_id
       WHERE 1=1 ${where}
         AND ${extra.join(" AND ")}
       ORDER BY COALESCE(p.nombre, ''), f.mes_cargo DESC, f.unidad NULLS LAST, f.id
    `;
    const r = await client.query(q, params);
    let plantaNombre = null;
    if (plantaId != null) {
      const pr = await client.query(`SELECT nombre FROM public.plantas WHERE id = $1`, [plantaId]);
      plantaNombre = pr.rows[0] && pr.rows[0].nombre ? String(pr.rows[0].nombre) : null;
    }
    const wb = await tallerAtExcel.buildTallerAtWorkbook(r.rows || [], {
      mesDesde,
      mesHasta,
      plantaNombre,
    });
    const buf = Buffer.from(await wb.xlsx.writeBuffer());
    const safeA = tallerAtExcel.formatMesLabel(mesDesde).replace(/\s+/g, "_");
    const safeB = tallerAtExcel.formatMesLabel(mesHasta).replace(/\s+/g, "_");
    const plantaSuffix = plantaNombre ? `_${plantaNombre.replace(/\s+/g, "_")}` : "";
    const filename = `Taller_AT_${safeA}_${safeB}${plantaSuffix}.xlsx`;
    res.setHeader("Content-Type", "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet");
    res.setHeader("Content-Disposition", `attachment; filename="${filename}"`);
    return res.send(buf);
  } catch (e) {
    console.error("[taller-at-excel]", e);
    res.status(500).json({ error: e.message || "Error al generar Excel de taller por AT" });
  } finally {
    client.release();
  }
});

/**
 * Excel GASTOS o INVERSIONES por rango de meses (misma dinámica que Taller por AT).
 * Query: categoria=GASTOS|INVERSIONES, mes_desde, mes_hasta (YYYY-MM), planta_id opcional.
 * priv_clave=Tomza-Priv (opcional) → incluye folios Solo ZP/AD (privados). Vacío = sin privados.
 */
app.get("/api/dashboard/categoria-rango-excel", dashboardAuthMiddleware, async (req, res) => {
  if (dashboardBlockGVForbidden(req, res)) return;
  const includePrivados = clasificacionIncluyePrivados(req);
  const catRaw = String(req.query.categoria || "").trim().toUpperCase();
  const categoria = catRaw === "INVERSIONES" ? "INVERSIONES" : catRaw === "GASTOS" ? "GASTOS" : null;
  if (!categoria) {
    return res.status(400).json({ error: "categoria debe ser GASTOS o INVERSIONES" });
  }
  let mesDesde = String(req.query.mes_desde || "").trim();
  let mesHasta = String(req.query.mes_hasta || "").trim();
  if (!/^\d{4}-\d{2}$/.test(mesDesde) || !/^\d{4}-\d{2}$/.test(mesHasta)) {
    return res.status(400).json({ error: "mes_desde y mes_hasta son obligatorios (YYYY-MM)" });
  }
  if (mesDesde > mesHasta) {
    const t = mesDesde;
    mesDesde = mesHasta;
    mesHasta = t;
  }
  const plantaIdRaw =
    req.query.planta_id != null && String(req.query.planta_id).trim() !== ""
      ? Number(req.query.planta_id)
      : null;
  const plantaId = Number.isFinite(plantaIdRaw) ? plantaIdRaw : null;

  const client = await pool.connect();
  try {
    const filters = parseDashboardFilters({});
    // Con clave correcta: incluir privados. Sin clave: forzar exclusión aunque el rol los vea.
    const authForQuery = {
      ...req.dashboardAuth,
      permisos: {
        ...(req.dashboardAuth && req.dashboardAuth.permisos ? req.dashboardAuth.permisos : {}),
        acceso_ver_folios_solo_zp_ad: includePrivados,
      },
    };
    const { where, params } = buildDashboardWhere(authForQuery, {
      ...filters,
      soloActivos: false,
      ventanaDefault: false,
    });
    let n = params.length;
    const extra = [];
    n += 1;
    extra.push(`f.mes_cargo >= $${n}::text`);
    params.push(mesDesde);
    n += 1;
    extra.push(`f.mes_cargo <= $${n}::text`);
    params.push(mesHasta);
    if (categoria === "INVERSIONES") {
      extra.push(`(
        UPPER(TRIM(COALESCE(f.categoria,''))) = 'INVERSIONES'
        OR UPPER(TRIM(COALESCE(f.categoria,''))) LIKE '%INVERSION%'
      )`);
    } else {
      extra.push(`(
        UPPER(TRIM(COALESCE(f.categoria,''))) = 'GASTOS'
        OR UPPER(TRIM(COALESCE(f.categoria,''))) LIKE '%GASTO%'
      )`);
      // Evitar que "GASTOS DE TALLER" u otras mezclas caigan aquí si ya están en Taller.
      extra.push(`UPPER(TRIM(COALESCE(f.categoria,''))) NOT LIKE '%TALLER%'`);
      extra.push(`UPPER(TRIM(COALESCE(f.categoria,''))) NOT LIKE '%INVERSION%'`);
    }
    extra.push(`UPPER(TRIM(COALESCE(f.estatus,''))) <> 'CANCELADO'`);
    if (plantaId != null) {
      const ids = getPlantaIdsEquivalentesForPendientes(plantaId);
      n += 1;
      extra.push(`f.planta_id = ANY($${n}::int[])`);
      params.push(ids.length ? ids : [plantaId]);
    }
    const q = `
      SELECT f.id,
             f.numero_folio,
             f.beneficiario,
             f.subcategoria,
             COALESCE(NULLIF(TRIM(f.descripcion), ''), NULLIF(TRIM(f.concepto), ''), '') AS concepto,
             f.importe,
             f.detalle_lineas,
             f.mes_cargo,
             f.estatus
        FROM public.folios f
       WHERE 1=1 ${where}
         AND ${extra.join(" AND ")}
       ORDER BY f.mes_cargo DESC, f.subcategoria NULLS LAST, f.id
    `;
    const r = await client.query(q, params);
    let plantaNombre = null;
    if (plantaId != null) {
      const pr = await client.query(`SELECT nombre FROM public.plantas WHERE id = $1`, [plantaId]);
      plantaNombre = pr.rows[0] && pr.rows[0].nombre ? String(pr.rows[0].nombre) : null;
    }
    const wb = await categoriaRangoExcel.buildCategoriaRangoWorkbook(categoria, r.rows || [], {
      mesDesde,
      mesHasta,
      plantaNombre,
    });
    const buf = Buffer.from(await wb.xlsx.writeBuffer());
    const safeA = categoriaRangoExcel.formatMesLabel(mesDesde).replace(/\s+/g, "_");
    const safeB = categoriaRangoExcel.formatMesLabel(mesHasta).replace(/\s+/g, "_");
    const plantaSuffix = plantaNombre ? `_${plantaNombre.replace(/\s+/g, "_")}` : "";
    const filename = `${categoria}_${safeA}_${safeB}${plantaSuffix}.xlsx`;
    res.setHeader("Content-Type", "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet");
    res.setHeader("Content-Disposition", `attachment; filename="${filename}"`);
    return res.send(buf);
  } catch (e) {
    console.error("[categoria-rango-excel]", e);
    res.status(500).json({ error: e.message || `Error al generar Excel de ${categoria}` });
  } finally {
    client.release();
  }
});

/**
 * COMPARAR/ACTUALIZAR — inspección previa (hojas + sugerencias de columnas/planta/categoría).
 * Body: { fileBase64 }
 */
app.post("/api/dashboard/clasificacion-comparar/inspeccionar", dashboardAuthMiddleware, async (req, res) => {
  if (dashboardBlockGVForbidden(req, res)) return;
  if (req.dashboardAuth.role === "GA") {
    return res.status(403).json({ error: "GA no puede usar COMPARAR/ACTUALIZAR." });
  }
  let fileBuffer = null;
  if (typeof req.body.fileBase64 === "string" && req.body.fileBase64.trim()) {
    try {
      const raw = req.body.fileBase64.includes(",")
        ? req.body.fileBase64.split(",").pop()
        : req.body.fileBase64;
      fileBuffer = Buffer.from(raw, "base64");
    } catch (e) {
      return res.status(400).json({ error: "fileBase64 inválido" });
    }
  }
  if (!fileBuffer || fileBuffer.length === 0) {
    return res.status(400).json({ error: "Envía fileBase64 del Excel" });
  }
  try {
    const info = clasificacionComparar.inspectClasificacionWorkbook(fileBuffer);
    return res.json({ ok: true, ...info });
  } catch (e) {
    console.error("[clasificacion-comparar inspeccionar]", e);
    res.status(500).json({ error: e.message || "Error al inspeccionar Excel" });
  }
});

/**
 * COMPARAR/ACTUALIZAR: analiza Excel vs folios del mes.
 * Body: { fileBase64, mes_cargo, sheetConfigs: [{ sheetName, enabled, planta_id, categoria, columns }] }
 */
app.post("/api/dashboard/clasificacion-comparar", dashboardAuthMiddleware, async (req, res) => {
  if (dashboardBlockGVForbidden(req, res)) return;
  if (req.dashboardAuth.role === "GA") {
    return res.status(403).json({ error: "GA no puede usar COMPARAR/ACTUALIZAR." });
  }
  const mesCargo = String(req.body.mes_cargo || "").trim();
  if (!/^\d{4}-\d{2}$/.test(mesCargo)) {
    return res.status(400).json({ error: "mes_cargo es obligatorio (YYYY-MM)" });
  }
  let fileBuffer = null;
  if (Buffer.isBuffer(req.body.file)) fileBuffer = req.body.file;
  else if (typeof req.body.fileBase64 === "string" && req.body.fileBase64.trim()) {
    try {
      const raw = req.body.fileBase64.includes(",")
        ? req.body.fileBase64.split(",").pop()
        : req.body.fileBase64;
      fileBuffer = Buffer.from(raw, "base64");
    } catch (e) {
      return res.status(400).json({ error: "fileBase64 inválido" });
    }
  }
  if (!fileBuffer || fileBuffer.length === 0) {
    return res.status(400).json({ error: "Envía fileBase64 del Excel" });
  }
  const sheetConfigs = Array.isArray(req.body.sheetConfigs) ? req.body.sheetConfigs : null;
  if (!sheetConfigs || !sheetConfigs.length) {
    return res.status(400).json({
      error: "Debes configurar cada hoja (planta, categoría y columnas). Usa /inspeccionar primero.",
    });
  }

  const client = await pool.connect();
  try {
    const parsed = clasificacionComparar.parseClasificacionExcelWithConfigs(fileBuffer, sheetConfigs);
    if (!parsed.sheets.length) {
      return res.status(400).json({
        error: "Ninguna hoja configurada pudo leerse. Revisa planta, categoría y mapeo de columnas.",
      });
    }

    const filters = parseDashboardFilters({});
    const { where, params } = buildDashboardWhere(req.dashboardAuth, {
      ...filters,
      soloActivos: false,
      ventanaDefault: false,
    });
    let n = params.length;
    const extra = [];
    n += 1;
    extra.push(`f.mes_cargo = $${n}::text`);
    params.push(mesCargo);
    extra.push(`UPPER(TRIM(COALESCE(f.estatus,''))) <> 'CANCELADO'`);
    extra.push(`(
      UPPER(TRIM(COALESCE(f.categoria,''))) LIKE '%GASTO%'
      OR UPPER(TRIM(COALESCE(f.categoria,''))) LIKE '%INVERSION%'
      OR UPPER(TRIM(COALESCE(f.categoria,''))) LIKE '%TALLER%'
    )`);

    // Si todas las hojas activas tienen la misma planta, filtrar dashboard a esa planta
    const activeCfgs = sheetConfigs.filter((c) => c.enabled !== false && c.planta_id != null);
    const uniquePlantas = [...new Set(activeCfgs.map((c) => Number(c.planta_id)).filter(Number.isFinite))];
    if (uniquePlantas.length === 1) {
      const ids = getPlantaIdsEquivalentesForPendientes(uniquePlantas[0]);
      n += 1;
      extra.push(`f.planta_id = ANY($${n}::int[])`);
      params.push(ids.length ? ids : uniquePlantas);
    }

    const q = `
      SELECT f.id, f.numero_folio, f.folio_codigo, f.planta_id, f.categoria, f.subcategoria, f.unidad,
             f.importe, f.estatus, f.mes_cargo, f.beneficiario,
             COALESCE(f.descripcion, f.concepto) AS concepto
        FROM public.folios f
       WHERE 1=1 ${where}
         AND ${extra.join(" AND ")}
    `;
    const r = await client.query(q, params);
    const dashRows = (r.rows || []).map((row) => clasificacionComparar.folioToCompareRow(row));
    const result = clasificacionComparar.compareExcelVsDashboard(
      parsed.rows,
      parsed.rechazos,
      dashRows
    );

    return res.json({
      ok: true,
      mes_cargo: mesCargo,
      sheets: parsed.sheets,
      excel_count: parsed.rows.length,
      excel_rechazos_count: (parsed.rechazos || []).length,
      dashboard_count: dashRows.length,
      matched_count: result.matched_count,
      missing_in_dashboard: result.missing_in_dashboard,
      missing_in_excel: result.missing_in_excel,
      posibles_duplicados: result.posibles_duplicados || [],
      rechazos_cdjz: result.rechazos_cdjz,
      warnings: parsed.warnings || [],
    });
  } catch (e) {
    console.error("[clasificacion-comparar]", e);
    res.status(500).json({ error: e.message || "Error al comparar" });
  } finally {
    client.release();
  }
});

/**
 * Agrega al dashboard un renglón que existía en Excel y no en dashboard
 * (crea folio + asigna mes_cargo).
 * Body: { mes_cargo, item: { planta_id, categoria, concepto, importe, unidad?, subcategoria? } }
 */
app.post("/api/dashboard/clasificacion-comparar/agregar", dashboardAuthMiddleware, async (req, res) => {
  if (dashboardBlockGVForbidden(req, res)) return;
  if (req.dashboardAuth.role === "GA") {
    return res.status(403).json({ error: "GA no puede agregar folios desde COMPARAR/ACTUALIZAR." });
  }
  if (!usuarioPermisos.authHasPermiso(req.dashboardAuth, "acceso_crear_folios")) {
    return res.status(403).json({ error: "Sin permiso para crear folios." });
  }
  const mesCargo = String(req.body.mes_cargo || "").trim();
  if (!/^\d{4}-\d{2}$/.test(mesCargo)) {
    return res.status(400).json({ error: "mes_cargo es obligatorio (YYYY-MM)" });
  }
  const item = req.body.item || {};
  const planta_id = item.planta_id != null ? parseInt(item.planta_id, 10) : null;
  if (!planta_id || !Number.isFinite(planta_id)) {
    return res.status(400).json({ error: "item.planta_id es obligatorio" });
  }
  const concepto = String(item.concepto || "").trim();
  const importe = Number(item.importe);
  if (concepto.length < 2) return res.status(400).json({ error: "concepto inválido" });
  if (!Number.isFinite(importe) || importe < 0) return res.status(400).json({ error: "importe inválido" });
  const catNorm = clasificacionComparar.normalizeCategoriaDb(item.categoria);
  if (!["GASTOS", "INVERSIONES", "TALLER"].includes(catNorm)) {
    return res.status(400).json({ error: "categoria debe ser GASTOS, INVERSIONES o TALLER" });
  }
  let subcategoria = item.subcategoria != null ? String(item.subcategoria).trim() : null;
  if (catNorm === "TALLER") {
    const tipos = (SUBCATEGORIAS.TALLER || []).map((s) => String(s).trim().toUpperCase());
    const subNorm = String(subcategoria || "")
      .trim()
      .toUpperCase()
      .normalize("NFD")
      .replace(/[\u0300-\u036f]/g, "");
    const ok = tipos.some((t) => t.normalize("NFD").replace(/[\u0300-\u036f]/g, "") === subNorm);
    if (!ok) subcategoria = "PREVENTIVO";
  }
  const unidadRes = resolveUnidadForSave(catNorm, item.unidad != null ? String(item.unidad).trim() : "");
  if (!unidadRes.ok) return res.status(400).json({ error: unidadRes.error });
  const unidad = unidadRes.unidad;
  const role = (req.dashboardAuth.role && String(req.dashboardAuth.role).toUpperCase()) || "";

  const client = await pool.connect();
  try {
    const plantaRow = await client.query("SELECT id, nombre FROM public.plantas WHERE id = $1", [planta_id]);
    if (!plantaRow.rows[0]) return res.status(400).json({ error: "planta_id no existe" });
    const planta_nombre = plantaRow.rows[0].nombre || null;
    const beneficiario =
      item.beneficiario != null && String(item.beneficiario).trim()
        ? String(item.beneficiario).trim()
        : null;
    const dd = {
      planta_id,
      planta_nombre,
      beneficiario,
      concepto,
      importe,
      lineas: [{ beneficiario, concepto, importe }],
      categoria_nombre: clasificacionComparar.categoriaNombreForInsert(catNorm),
      subcategoria_nombre: subcategoria || null,
      prioridad: "Media",
      unidad: unidad || null,
      actor_telefono: req.dashboardAuth.actor_id != null ? `Dashboard:${req.dashboardAuth.actor_id}` : "Dashboard",
      actor_rol: role,
      actor_clave: role,
      origen: "dashboard",
    };
    const row = await insertFolio(client, dd);
    await client.query(`UPDATE public.folios SET mes_cargo = $1 WHERE id = $2`, [mesCargo, row.id]);
    await insertHistorial(
      client,
      row.id,
      row.numero_folio,
      row.folio_codigo,
      null,
      `COMPARAR/ACTUALIZAR: folio creado desde Excel de referencia. Mes cargo ${mesCargo}.`,
      null,
      role
    ).catch(() => {});
    res.status(201).json({
      ok: true,
      id: row.id,
      numero_folio: row.numero_folio,
      folio_codigo: row.folio_codigo,
      mes_cargo: mesCargo,
    });
  } catch (e) {
    console.error("[clasificacion-comparar agregar]", e);
    res.status(500).json({ error: e.message || "Error al agregar" });
  } finally {
    client.release();
  }
});

/**
 * Quita mes de cargo (RECHAZO CDJZ / igualar con Excel) para un folio que no está en el Excel.
 * Permite cualquier estatus excepto cancelado (herramienta de conciliación).
 */
app.post("/api/dashboard/clasificacion-comparar/rechazar", dashboardAuthMiddleware, async (req, res) => {
  if (dashboardBlockGVForbidden(req, res)) return;
  if (req.dashboardAuth.role === "GA") {
    return res.status(403).json({ error: "GA no puede rechazar desde COMPARAR/ACTUALIZAR." });
  }
  const folioId = req.body.folio_id != null ? parseInt(req.body.folio_id, 10) : NaN;
  if (!Number.isFinite(folioId)) return res.status(400).json({ error: "folio_id inválido" });
  const client = await pool.connect();
  try {
    const folio = await getFolioById(client, folioId);
    if (!folio) return res.status(404).json({ error: "Folio no encontrado" });
    if (String(folio.estatus || "").toUpperCase() === "CANCELADO") {
      return res.status(400).json({ error: "No se puede operar un folio cancelado." });
    }
    if ((req.dashboardAuth.role === "GG" || req.dashboardAuth.role === "GA") && req.dashboardAuth.plantas_permitidas?.length > 0) {
      if (!folio.planta_id || !req.dashboardAuth.plantas_permitidas.includes(folio.planta_id)) {
        return res.status(403).json({ error: "Sin permiso para este folio" });
      }
    }
    const prevMes = folio.mes_cargo ? String(folio.mes_cargo).trim() : null;
    await client.query(`UPDATE public.folios SET mes_cargo = NULL WHERE id = $1`, [folioId]);
    const motivoCustom =
      typeof req.body.motivo === "string" && req.body.motivo.trim() ? req.body.motivo.trim() : null;
    const comentario = motivoCustom
      ? `RECHAZO CDJZ (COMPARAR/ACTUALIZAR). ${motivoCustom}${prevMes ? ` (mes cargo quitado: ${prevMes})` : ""}`
      : prevMes
        ? `RECHAZO CDJZ (COMPARAR/ACTUALIZAR). Se quitó el mes de cargo ${prevMes}: no aparece en Excel de referencia.`
        : "RECHAZO CDJZ (COMPARAR/ACTUALIZAR). Sin mes de cargo. No aparece en Excel de referencia.";
    await insertHistorial(
      client,
      folioId,
      folio.numero_folio,
      folio.folio_codigo,
      folio.estatus || "",
      comentario,
      null,
      req.dashboardAuth.role || null
    ).catch(() => {});
    res.json({ ok: true, folio_id: folioId, mes_cargo: null, rechazo_cdjz: true });
  } catch (e) {
    console.error("[clasificacion-comparar rechazar]", e);
    res.status(500).json({ error: e.message || "Error al rechazar" });
  } finally {
    client.release();
  }
});

/**
 * COMPARAR/ACTUALIZAR — «Sí, es el mismo»:
 * - Asegura mes_cargo = mes seleccionado.
 * - Si la etapa es anterior a Depósito y cierre → mueve a Carro de compra (APROBADO_ZP).
 * - Si ya está en Depósito y cierre o más adelante → solo mes_cargo, sin mover etapa.
 */
app.post("/api/dashboard/clasificacion-comparar/confirmar-mismo", dashboardAuthMiddleware, async (req, res) => {
  if (dashboardBlockGVForbidden(req, res)) return;
  if (req.dashboardAuth.role === "GA") {
    return res.status(403).json({ error: "GA no puede confirmar duplicados desde COMPARAR/ACTUALIZAR." });
  }
  const folioId = req.body.folio_id != null ? parseInt(req.body.folio_id, 10) : NaN;
  const mesCargo = String(req.body.mes_cargo || "").trim();
  if (!Number.isFinite(folioId)) return res.status(400).json({ error: "folio_id inválido" });
  if (!/^\d{4}-\d{2}$/.test(mesCargo)) {
    return res.status(400).json({ error: "mes_cargo es obligatorio (YYYY-MM)" });
  }
  const client = await pool.connect();
  try {
    const folio = await getFolioById(client, folioId);
    if (!folio) return res.status(404).json({ error: "Folio no encontrado" });
    const estatus = String(folio.estatus || "").trim().toUpperCase();
    if (estatus === ESTADOS.CANCELADO) {
      return res.status(400).json({ error: "No se puede operar un folio cancelado." });
    }
    if ((req.dashboardAuth.role === "GG" || req.dashboardAuth.role === "GA") && req.dashboardAuth.plantas_permitidas?.length > 0) {
      if (!folio.planta_id || !req.dashboardAuth.plantas_permitidas.includes(folio.planta_id)) {
        return res.status(403).json({ error: "Sin permiso para este folio" });
      }
    }

    const etapaActual = estatusToEtapaVisual(estatus);
    const idxEtapa = ETAPAS_VISUAL_ORDER.indexOf(etapaActual);
    const idxDep = ETAPAS_VISUAL_ORDER.indexOf(ETAPA_VISUAL.DEPOSITO_CIERRE);
    const antesDeDeposito = idxEtapa >= 0 && idxDep >= 0 && idxEtapa < idxDep;
    const yaEnCarro = etapaActual === ETAPA_VISUAL.CARRO_COMPRA;
    const moverACarro = antesDeDeposito && !yaEnCarro;
    const estatusDestino = moverACarro ? ESTADOS.APROBADO_ZP : estatus;
    const prevMes = folio.mes_cargo ? String(folio.mes_cargo).trim() : null;

    if (moverACarro) {
      await client.query(`UPDATE public.folios SET mes_cargo = $1, estatus = $2 WHERE id = $3`, [
        mesCargo,
        estatusDestino,
        folioId,
      ]);
    } else {
      await client.query(`UPDATE public.folios SET mes_cargo = $1 WHERE id = $2`, [mesCargo, folioId]);
    }

    const partes = [];
    if (prevMes !== mesCargo) {
      partes.push(
        prevMes
          ? `Mes de cargo ${prevMes} → ${mesCargo}`
          : `Mes de cargo asignado: ${mesCargo}`
      );
    } else {
      partes.push(`Mes de cargo confirmado: ${mesCargo}`);
    }
    if (moverACarro) {
      partes.push(`Movido a Carro de compra (antes: ${getEtapaVisibleLabel(estatus)}).`);
    } else if (antesDeDeposito && yaEnCarro) {
      partes.push("Ya estaba en Carro de compra; no se movió de etapa.");
    } else {
      partes.push(`Etapa conservada: ${getEtapaVisibleLabel(estatus)} (Depósito y cierre o posterior).`);
    }

    await insertHistorial(
      client,
      folioId,
      folio.numero_folio,
      folio.folio_codigo,
      estatusDestino,
      `COMPARAR/ACTUALIZAR: confirmado mismo folio. ${partes.join(" ")}`,
      null,
      req.dashboardAuth.role || null
    ).catch(() => {});

    res.json({
      ok: true,
      folio_id: folioId,
      numero_folio: folio.numero_folio,
      mes_cargo: mesCargo,
      estatus: estatusDestino,
      movido_a_carro: moverACarro,
      etapa: estatusToEtapaVisual(estatusDestino),
    });
  } catch (e) {
    console.error("[clasificacion-comparar confirmar-mismo]", e);
    res.status(500).json({ error: e.message || "Error al confirmar mismo folio" });
  } finally {
    client.release();
  }
});

/**
 * COMPARAR/ACTUALIZAR — «No, son distintos»:
 * Crea folio nuevo con datos del Excel, mes_cargo seleccionado y etapa Carro de compra.
 * No modifica el folio existente del soft-match.
 */
app.post("/api/dashboard/clasificacion-comparar/son-distintos", dashboardAuthMiddleware, async (req, res) => {
  if (dashboardBlockGVForbidden(req, res)) return;
  if (req.dashboardAuth.role === "GA") {
    return res.status(403).json({ error: "GA no puede crear folios desde COMPARAR/ACTUALIZAR." });
  }
  if (!usuarioPermisos.authHasPermiso(req.dashboardAuth, "acceso_crear_folios")) {
    return res.status(403).json({ error: "Sin permiso para crear folios." });
  }
  const mesCargo = String(req.body.mes_cargo || "").trim();
  if (!/^\d{4}-\d{2}$/.test(mesCargo)) {
    return res.status(400).json({ error: "mes_cargo es obligatorio (YYYY-MM)" });
  }
  const item = req.body.item || {};
  const planta_id = item.planta_id != null ? parseInt(item.planta_id, 10) : null;
  if (!planta_id || !Number.isFinite(planta_id)) {
    return res.status(400).json({ error: "item.planta_id es obligatorio" });
  }
  const concepto = String(item.concepto || "").trim();
  const importe = Number(item.importe);
  if (concepto.length < 2) return res.status(400).json({ error: "concepto inválido" });
  if (!Number.isFinite(importe) || importe < 0) return res.status(400).json({ error: "importe inválido" });
  const catNorm = clasificacionComparar.normalizeCategoriaDb(item.categoria);
  if (!["GASTOS", "INVERSIONES", "TALLER"].includes(catNorm)) {
    return res.status(400).json({ error: "categoria debe ser GASTOS, INVERSIONES o TALLER" });
  }
  let subcategoria = item.subcategoria != null ? String(item.subcategoria).trim() : null;
  if (catNorm === "TALLER") {
    const tipos = (SUBCATEGORIAS.TALLER || []).map((s) => String(s).trim().toUpperCase());
    const subNorm = String(subcategoria || "")
      .trim()
      .toUpperCase()
      .normalize("NFD")
      .replace(/[\u0300-\u036f]/g, "");
    const ok = tipos.some((t) => t.normalize("NFD").replace(/[\u0300-\u036f]/g, "") === subNorm);
    if (!ok) subcategoria = "PREVENTIVO";
  }
  const unidadRes = resolveUnidadForSave(catNorm, item.unidad != null ? String(item.unidad).trim() : "");
  if (!unidadRes.ok) return res.status(400).json({ error: unidadRes.error });
  const unidad = unidadRes.unidad;
  const role = (req.dashboardAuth.role && String(req.dashboardAuth.role).toUpperCase()) || "";

  const client = await pool.connect();
  try {
    if ((role === "GG" || role === "GA") && req.dashboardAuth.plantas_permitidas?.length > 0) {
      if (!req.dashboardAuth.plantas_permitidas.includes(planta_id)) {
        return res.status(403).json({ error: "Sin permiso para esta planta" });
      }
    }
    const plantaRow = await client.query("SELECT id, nombre FROM public.plantas WHERE id = $1", [planta_id]);
    if (!plantaRow.rows[0]) return res.status(400).json({ error: "planta_id no existe" });
    const planta_nombre = plantaRow.rows[0].nombre || null;
    const beneficiario =
      item.beneficiario != null && String(item.beneficiario).trim()
        ? String(item.beneficiario).trim()
        : null;
    const dd = {
      planta_id,
      planta_nombre,
      beneficiario,
      concepto,
      importe,
      lineas: [{ beneficiario, concepto, importe }],
      categoria_nombre: clasificacionComparar.categoriaNombreForInsert(catNorm),
      subcategoria_nombre: subcategoria || null,
      prioridad: "Media",
      unidad: unidad || null,
      banco: item.banco != null && String(item.banco).trim() ? String(item.banco).trim() : null,
      cuenta_bancaria:
        item.cuenta_bancaria != null && String(item.cuenta_bancaria).trim()
          ? String(item.cuenta_bancaria).trim()
          : null,
      actor_telefono: req.dashboardAuth.actor_id != null ? `Dashboard:${req.dashboardAuth.actor_id}` : "Dashboard",
      actor_rol: role,
      actor_clave: role,
      origen: "dashboard",
    };
    const row = await insertFolio(client, dd);
    await client.query(`UPDATE public.folios SET mes_cargo = $1, estatus = $2 WHERE id = $3`, [
      mesCargo,
      ESTADOS.APROBADO_ZP,
      row.id,
    ]);
    await insertHistorial(
      client,
      row.id,
      row.numero_folio,
      row.folio_codigo,
      ESTADOS.APROBADO_ZP,
      `COMPARAR/ACTUALIZAR: folio nuevo (son distintos). Mes cargo ${mesCargo}. Colocado en Carro de compra.`,
      null,
      role
    ).catch(() => {});
    res.status(201).json({
      ok: true,
      id: row.id,
      numero_folio: row.numero_folio,
      folio_codigo: row.folio_codigo,
      mes_cargo: mesCargo,
      estatus: ESTADOS.APROBADO_ZP,
    });
  } catch (e) {
    console.error("[clasificacion-comparar son-distintos]", e);
    res.status(500).json({ error: e.message || "Error al crear folio distinto" });
  } finally {
    client.release();
  }
});

/** Vista digital COMPARATIVOS (misma data que el Excel). */
app.get("/api/dashboard/clasificacion-apoyos", dashboardAuthMiddleware, async (req, res) => {
  if (dashboardBlockGVForbidden(req, res)) return;
  const mesA = String(req.query.mes_a || "").trim();
  const mesB = String(req.query.mes_b || "").trim();
  const plantaIdRaw = req.query.planta_id != null && String(req.query.planta_id).trim() !== ""
    ? Number(req.query.planta_id)
    : null;
  const plantaId = Number.isFinite(plantaIdRaw) ? plantaIdRaw : null;
  const includePrivados = clasificacionIncluyePrivados(req);
  if (!/^\d{4}-\d{2}$/.test(mesA) || !/^\d{4}-\d{2}$/.test(mesB)) {
    return res.status(400).json({ error: "mes_a y mes_b son obligatorios (YYYY-MM)" });
  }
  if (mesA === mesB) {
    return res.status(400).json({ error: "Los meses a comparar deben ser distintos" });
  }
  const plantasFiltro = clasificacionApoyosExcel.resolvePlantasComparativo(plantaId);
  const idsFiltro = [...new Set(plantasFiltro.flatMap((p) => p.ids || []))];
  const privSql = includePrivados ? "" : " AND COALESCE(f.solo_zp_ad, false) = false";
  const client = await pool.connect();
  try {
    const r = await client.query(
      `SELECT f.planta_id, f.categoria, f.importe, f.mes_cargo
       FROM public.folios f
       WHERE f.mes_cargo = ANY($1::text[])
         AND UPPER(TRIM(COALESCE(f.estatus,''))) <> 'CANCELADO'
         AND f.planta_id IS NOT NULL
         AND f.planta_id = ANY($2::int[])
         ${privSql}`,
      [[mesA, mesB], idsFiltro]
    );
    const matrix = clasificacionApoyosExcel.buildClasificacionMatrix(r.rows, mesA, mesB, { plantaId });
    return res.json({ ok: true, ...matrix });
  } catch (e) {
    console.error("[clasificacion-apoyos]", e);
    res.status(500).json({ error: e.message || "Error al cargar comparativo" });
  } finally {
    client.release();
  }
});

/**
 * Desglose de una celda: planta + categoría + mes.
 * Query: mes=YYYY-MM, planta=Puebla|..., categoria=GASTOS|INVERSIONES|TALLER|TOTAL
 */
app.get("/api/dashboard/clasificacion-apoyos/detalle", dashboardAuthMiddleware, async (req, res) => {
  if (dashboardBlockGVForbidden(req, res)) return;
  const mes = String(req.query.mes || "").trim();
  const plantaLabel = String(req.query.planta || "").trim();
  const categoriaRaw = String(req.query.categoria || "").trim().toUpperCase();
  if (!/^\d{4}-\d{2}$/.test(mes)) return res.status(400).json({ error: "mes debe ser YYYY-MM" });
  const plantaDef = clasificacionApoyosExcel.PLANTAS_COMPARATIVO.find(
    (p) => p.label.toLowerCase() === plantaLabel.toLowerCase()
  );
  if (!plantaDef) return res.status(400).json({ error: "planta no válida" });
  const catNorm =
    categoriaRaw === "TOTAL"
      ? "TOTAL"
      : clasificacionApoyosExcel.normalizeCat(categoriaRaw);
  if (!catNorm) return res.status(400).json({ error: "categoria debe ser GASTOS, INVERSIONES, TALLER o TOTAL" });

  const includePrivados = clasificacionIncluyePrivados(req);
  const privSql = includePrivados ? "" : " AND COALESCE(f.solo_zp_ad, false) = false";
  const client = await pool.connect();
  try {
    const r = await client.query(
      `SELECT f.id, f.numero_folio, f.folio_codigo, f.importe, f.estatus, f.mes_cargo,
              f.categoria, f.subcategoria, f.beneficiario,
              COALESCE(f.descripcion, f.concepto) AS concepto,
              p.nombre AS planta_nombre
       FROM public.folios f
       LEFT JOIN public.plantas p ON p.id = f.planta_id
       WHERE f.mes_cargo = $1
         AND f.planta_id = ANY($2::int[])
         AND UPPER(TRIM(COALESCE(f.estatus,''))) <> 'CANCELADO'
         ${privSql}
       ORDER BY f.numero_folio NULLS LAST, f.id`,
      [mes, plantaDef.ids]
    );
    const folios = (r.rows || [])
      .map((row) => {
        const cat = clasificacionApoyosExcel.normalizeCat(row.categoria);
        if (catNorm !== "TOTAL" && cat !== catNorm) return null;
        if (catNorm === "TOTAL" && !cat) return null;
        return {
          id: row.id,
          numero_folio: row.numero_folio || row.folio_codigo,
          folio_codigo: row.folio_codigo || row.numero_folio,
          importe: row.importe != null ? Number(row.importe) : null,
          estatus: row.estatus || null,
          mes_cargo: row.mes_cargo || null,
          categoria: row.categoria || null,
          categoria_norm: cat,
          subcategoria: row.subcategoria || null,
          beneficiario: row.beneficiario || null,
          concepto: row.concepto || null,
          planta_nombre: row.planta_nombre || null,
        };
      })
      .filter(Boolean);
    const total = folios.reduce((s, f) => s + (Number(f.importe) || 0), 0);
    return res.json({
      ok: true,
      mes,
      mes_label: clasificacionApoyosExcel.mesLabelEs(mes),
      planta: plantaDef.label,
      categoria: catNorm,
      count: folios.length,
      total: Math.round(total),
      folios,
    });
  } catch (e) {
    console.error("[clasificacion-apoyos detalle]", e);
    res.status(500).json({ error: e.message || "Error al cargar desglose" });
  } finally {
    client.release();
  }
});

app.get("/api/dashboard/plantas", dashboardAuthMiddleware, async (req, res) => {
  const client = await pool.connect();
  try {
    const plantas = await getPlantas(client);
    let list = (plantas || []).map((p) => ({ id: p.id, nombre: p.nombre || p.clave || `Planta ${p.id}` }));
    const roleNorm = String(req.dashboardAuth?.role || "").toUpperCase();
    const isGlobalPlantas = roleNorm === "ZP" || roleNorm === "AD" || roleNorm === "CF_CDMX";
    const allowed = new Set((req.dashboardAuth.plantas_permitidas || []).map((x) => Number(x)).filter(Number.isFinite));
    if (allowed.size > 0 && (isDashboardGV(req) || isSehOnlyAuth(req.dashboardAuth) || !isGlobalPlantas)) {
      list = list.filter((p) => allowed.has(Number(p.id)));
    }
    res.json({ plantas: list });
  } catch (e) {
    console.error("[Dashboard plantas]", e);
    res.status(500).json({ error: e.message });
  } finally {
    client.release();
  }
});

/** Categorías fijas del módulo SEH (Seguridad e Higiene). */
const SEH_CATEGORIAS = sehEquipos.SEH_CATEGORIAS;
const SEH_COMPONENTES = sehEquipos.SEH_COMPONENTES;
const sehIsSci = sehEquipos.sehIsSci;

function assertSehPlantaAccess(req, plantaId) {
  const auth = req.dashboardAuth || {};
  const role = String(auth.role || "").toUpperCase();
  if (role === "ZP" || role === "AD" || role === "CF_CDMX") return true;
  const allowed = (auth.plantas_permitidas || []).map((x) => Number(x)).filter(Number.isFinite);
  if (allowed.length === 0) return true;
  return allowed.includes(Number(plantaId));
}

function sehActorLabel(auth) {
  const a = auth || {};
  const nombre = String(a.actor_nombre || "").trim();
  const tel = String(a.actor_telefono || "").trim();
  if (nombre && tel) return `${nombre} (${tel})`;
  if (nombre) return nombre;
  if (tel) return tel;
  if (a.actor_id != null) return `Usuario #${a.actor_id}`;
  return String(a.role || "Dashboard");
}

async function fetchSehUltimaEdicion(client, plantaId) {
  const u = await client.query(
    `SELECT planta_id, updated_by, actor_id,
            to_char(updated_at AT TIME ZONE 'America/Mexico_City', 'YYYY-MM-DD HH24:MI') AS updated_at_local,
            updated_at
     FROM public.seh_ultima_edicion
     WHERE planta_id = $1`,
    [plantaId]
  );
  const row = u.rows[0];
  if (!row) return null;
  return {
    updated_at: row.updated_at,
    updated_at_local: row.updated_at_local || null,
    updated_by: row.updated_by || "",
    actor_id: row.actor_id != null ? Number(row.actor_id) : null,
  };
}

function mapSehItems(rows) {
  return (rows || []).map((row) => ({
    id: row.id,
    planta_id: row.planta_id,
    categoria: row.categoria,
    locacion: row.locacion || "",
    descripcion: row.descripcion || "",
    componente: row.componente || "",
    nombre: row.nombre || "",
    vence: row.vence || null,
    sort_order: row.sort_order,
    has_foto: Boolean(row.foto_file_name || row.foto_s3_key || row.has_foto),
    foto_file_name: row.foto_file_name || null,
  }));
}

function sehDecodeFotoBase64(raw) {
  if (typeof raw !== "string" || !raw.trim()) return null;
  try {
    const b64 = raw.includes(",") ? raw.split(",").pop() : raw;
    const buffer = Buffer.from(String(b64 || ""), "base64");
    if (!buffer.length) return null;
    return buffer;
  } catch (_) {
    return null;
  }
}

function sehBuildEquipoFotoS3Key(plantaId, equipoId, fileName) {
  const safe = String(fileName || "foto")
    .replace(/[^a-zA-Z0-9._-]+/g, "_")
    .slice(0, 80);
  const ext = safe.includes(".") ? safe.split(".").pop() : "jpg";
  return `seh-equipos/${plantaId}/${equipoId || "new"}/${Date.now()}-${Math.random().toString(36).slice(2, 8)}.${ext}`;
}

const SEH_SELECT_SQL = `SELECT id, planta_id, categoria,
       COALESCE(locacion, '') AS locacion,
       COALESCE(descripcion, '') AS descripcion,
       COALESCE(componente, '') AS componente,
       COALESCE(nombre, '') AS nombre,
       to_char(vence, 'YYYY-MM-DD') AS vence, sort_order,
       foto_file_name, foto_content_type, foto_file_size_bytes,
       foto_s3_key, foto_s3_url,
       (foto_file_name IS NOT NULL OR foto_s3_key IS NOT NULL OR foto_data IS NOT NULL) AS has_foto
 FROM public.seh_equipos
 WHERE planta_id = $1
 ORDER BY categoria, sort_order, id`;

const SEH_FOTO_MAX_BYTES = 3 * 1024 * 1024;

/** GET /api/seh?planta_id= — listado de equipos SEH de una planta. */
app.get("/api/seh", dashboardAuthMiddleware, async (req, res) => {
  const plantaId = parseInt(String(req.query.planta_id || ""), 10);
  if (!Number.isFinite(plantaId)) {
    return res.status(400).json({ error: "planta_id es obligatorio" });
  }
  if (!assertSehPlantaAccess(req, plantaId)) {
    return res.status(403).json({ error: "Sin permiso para esta planta" });
  }
  const client = await pool.connect();
  try {
    const r = await client.query(SEH_SELECT_SQL, [plantaId]);
    const ultima_edicion = await fetchSehUltimaEdicion(client, plantaId);
    res.json({
      planta_id: plantaId,
      categorias: SEH_CATEGORIAS,
      componentes: SEH_COMPONENTES,
      items: mapSehItems(r.rows),
      ultima_edicion,
    });
  } catch (e) {
    console.error("[SEH GET]", e);
    res.status(500).json({ error: e.message });
  } finally {
    client.release();
  }
});

/**
 * PUT /api/seh
 * Body: {
 *   planta_id,
 *   items: [{ id?, categoria, ..., vence, foto_base64?, foto_file_name?, foto_content_type? }],
 *   categorias?: string[]  // si se envía, solo toca esas categorías
 * }
 * Persiste texto/fecha aunque no haya foto. La foto es opcional (evidencia).
 */
app.put("/api/seh", dashboardAuthMiddleware, async (req, res) => {
  if (req.dashboardAuth.role === "GA") {
    return res.status(403).json({ error: "GA solo puede ver e imprimir en el dashboard." });
  }
  const plantaId = parseInt(String(req.body?.planta_id || ""), 10);
  if (!Number.isFinite(plantaId)) {
    return res.status(400).json({ error: "planta_id es obligatorio" });
  }
  if (!assertSehPlantaAccess(req, plantaId)) {
    return res.status(403).json({ error: "Sin permiso para esta planta" });
  }
  const scopeCats = Array.isArray(req.body?.categorias)
    ? [...new Set(
        req.body.categorias
          .map((c) => String(c || "").trim().toUpperCase())
          .filter((c) => SEH_CATEGORIAS.includes(c))
      )]
    : [];
  const hasScope = scopeCats.length > 0;
  const rawItems = Array.isArray(req.body?.items) ? req.body.items : [];
  const cleaned = [];
  for (const meta of sehEquipos.sehCleanPutItems(rawItems, scopeCats)) {
    const fotoBuffer = sehDecodeFotoBase64(meta.foto_base64);
    if (fotoBuffer && fotoBuffer.length > SEH_FOTO_MAX_BYTES) {
      return res.status(413).json({
        error: `La foto excede el máximo de ${Math.floor(SEH_FOTO_MAX_BYTES / 1024 / 1024)}MB`,
      });
    }
    cleaned.push({
      id: meta.id,
      categoria: meta.categoria,
      locacion: meta.locacion,
      descripcion: meta.descripcion,
      componente: meta.componente,
      nombre: meta.nombre,
      vence: meta.vence,
      sort_order: meta.sort_order,
      fotoBuffer,
      clearFoto: Boolean(meta.clear_foto),
      fotoFileName: meta.foto_file_name || (fotoBuffer ? "foto.jpg" : null),
      fotoContentType: meta.foto_content_type || (fotoBuffer ? "image/jpeg" : null),
    });
  }

  const client = await pool.connect();
  try {
    await client.query("BEGIN");
    const existingQ = hasScope
      ? await client.query(
          `SELECT id, categoria, to_char(vence, 'YYYY-MM-DD') AS vence,
                  foto_file_name, foto_s3_key, foto_s3_url, foto_content_type, foto_file_size_bytes, foto_data
           FROM public.seh_equipos
           WHERE planta_id = $1 AND categoria = ANY($2::text[])`,
          [plantaId, scopeCats]
        )
      : await client.query(
          `SELECT id, categoria, to_char(vence, 'YYYY-MM-DD') AS vence,
                  foto_file_name, foto_s3_key, foto_s3_url, foto_content_type, foto_file_size_bytes, foto_data
           FROM public.seh_equipos WHERE planta_id = $1`,
          [plantaId]
        );
    const existingById = new Map();
    for (const row of existingQ.rows || []) {
      existingById.set(Number(row.id), row);
    }

    const keepIds = [];
    const actorLabel = sehActorLabel(req.dashboardAuth);
    const actorId = req.dashboardAuth.actor_id != null ? Number(req.dashboardAuth.actor_id) : null;

    for (const it of cleaned) {
      const prev = it.id != null ? existingById.get(Number(it.id)) : null;
      let equipoId = prev ? Number(prev.id) : null;

      if (prev) {
        await client.query(
          `UPDATE public.seh_equipos SET
             categoria = $2, locacion = $3, descripcion = $4, componente = $5, nombre = $6,
             vence = $7::date, sort_order = $8, updated_at = NOW(), updated_by = $9
           WHERE id = $1 AND planta_id = $10`,
          [
            prev.id,
            it.categoria,
            it.locacion,
            it.descripcion,
            it.componente,
            it.nombre,
            it.vence,
            it.sort_order,
            actorLabel,
            plantaId,
          ]
        );
        keepIds.push(Number(prev.id));
      } else {
        const ins = await client.query(
          `INSERT INTO public.seh_equipos
             (planta_id, categoria, locacion, descripcion, componente, nombre, vence, sort_order, updated_at, updated_by)
           VALUES ($1, $2, $3, $4, $5, $6, $7::date, $8, NOW(), $9)
           RETURNING id`,
          [
            plantaId,
            it.categoria,
            it.locacion,
            it.descripcion,
            it.componente,
            it.nombre,
            it.vence,
            it.sort_order,
            actorLabel,
          ]
        );
        equipoId = Number(ins.rows[0].id);
        keepIds.push(equipoId);
      }

      if (it.fotoBuffer && equipoId != null) {
        let s3Key = null;
        let s3Url = null;
        let storeBuffer = it.fotoBuffer;
        if (s3Enabled && s3) {
          s3Key = sehBuildEquipoFotoS3Key(plantaId, equipoId, it.fotoFileName);
          try {
            const bucket = s3BucketName;
            const region = process.env.AWS_REGION;
            await s3.send(
              new PutObjectCommand({
                Bucket: bucket,
                Key: s3Key,
                Body: it.fotoBuffer,
                ContentType: it.fotoContentType || "image/jpeg",
              })
            );
            s3Url = buildS3PublicUrl(bucket, region, s3Key);
            storeBuffer = null;
          } catch (e) {
            console.error("[SEH equipo foto S3]", e);
            s3Key = null;
            s3Url = null;
            storeBuffer = it.fotoBuffer;
          }
        }
        await client.query(
          `UPDATE public.seh_equipos SET
             foto_file_name = $2,
             foto_content_type = $3,
             foto_file_size_bytes = $4,
             foto_s3_key = $5,
             foto_s3_url = $6,
             foto_data = $7,
             foto_updated_at = NOW()
           WHERE id = $1 AND planta_id = $8`,
          [
            equipoId,
            it.fotoFileName,
            it.fotoContentType,
            it.fotoBuffer.length,
            s3Key,
            s3Url,
            storeBuffer,
            plantaId,
          ]
        );
      } else if (it.clearFoto && equipoId != null) {
        const prevFoto = prev || existingById.get(Number(equipoId));
        const oldKey = prevFoto && prevFoto.foto_s3_key ? String(prevFoto.foto_s3_key) : null;
        if (oldKey && s3Enabled && s3) {
          try {
            await s3.send(
              new DeleteObjectCommand({
                Bucket: s3BucketName,
                Key: oldKey,
              })
            );
          } catch (e) {
            console.warn("[SEH equipo foto S3 delete]", e.message || e);
          }
        }
        await client.query(
          `UPDATE public.seh_equipos SET
             foto_file_name = NULL,
             foto_content_type = NULL,
             foto_file_size_bytes = NULL,
             foto_s3_key = NULL,
             foto_s3_url = NULL,
             foto_data = NULL,
             foto_updated_at = NOW()
           WHERE id = $1 AND planta_id = $2`,
          [equipoId, plantaId]
        );
      }
    }

    if (hasScope) {
      if (keepIds.length) {
        await client.query(
          `DELETE FROM public.seh_equipos
           WHERE planta_id = $1 AND categoria = ANY($2::text[]) AND NOT (id = ANY($3::int[]))`,
          [plantaId, scopeCats, keepIds]
        );
      } else {
        await client.query(`DELETE FROM public.seh_equipos WHERE planta_id = $1 AND categoria = ANY($2::text[])`, [
          plantaId,
          scopeCats,
        ]);
      }
    } else if (keepIds.length) {
      await client.query(`DELETE FROM public.seh_equipos WHERE planta_id = $1 AND NOT (id = ANY($2::int[]))`, [
        plantaId,
        keepIds,
      ]);
    } else {
      await client.query(`DELETE FROM public.seh_equipos WHERE planta_id = $1`, [plantaId]);
    }

    await client.query(
      `INSERT INTO public.seh_ultima_edicion (planta_id, updated_at, updated_by, actor_id)
       VALUES ($1, NOW(), $2, $3)
       ON CONFLICT (planta_id) DO UPDATE SET
         updated_at = EXCLUDED.updated_at,
         updated_by = EXCLUDED.updated_by,
         actor_id = EXCLUDED.actor_id`,
      [plantaId, actorLabel, Number.isFinite(actorId) ? actorId : null]
    );
    await client.query("COMMIT");
    const r = await client.query(SEH_SELECT_SQL, [plantaId]);
    const ultima_edicion = await fetchSehUltimaEdicion(client, plantaId);
    res.json({
      ok: true,
      planta_id: plantaId,
      categorias: SEH_CATEGORIAS,
      componentes: SEH_COMPONENTES,
      items: mapSehItems(r.rows),
      ultima_edicion,
    });
  } catch (e) {
    try {
      await client.query("ROLLBACK");
    } catch (_) {}
    console.error("[SEH PUT]", e);
    res.status(500).json({ error: e.message });
  } finally {
    client.release();
  }
});

/** GET /api/seh/foto?id= — descarga/visualiza foto del equipo. */
app.get("/api/seh/foto", dashboardAuthMiddleware, async (req, res) => {
  const id = parseInt(String(req.query.id || ""), 10);
  if (!Number.isFinite(id)) return res.status(400).json({ error: "id es obligatorio" });
  const client = await pool.connect();
  try {
    const r = await client.query(
      `SELECT id, planta_id, foto_file_name, foto_content_type, foto_s3_key, foto_s3_url, foto_data
       FROM public.seh_equipos WHERE id = $1`,
      [id]
    );
    const row = r.rows[0];
    if (!row) return res.status(404).json({ error: "Equipo no encontrado" });
    if (!assertSehPlantaAccess(req, Number(row.planta_id))) {
      return res.status(403).json({ error: "Sin permiso para esta planta" });
    }
    let buffer = row.foto_data || null;
    if ((!buffer || !buffer.length) && row.foto_s3_key && s3Enabled && s3) {
      try {
        buffer = await getBufferFromS3(row.foto_s3_key);
      } catch (e) {
        console.warn("[SEH foto S3]", e.message);
      }
    }
    if ((!buffer || !buffer.length) && row.foto_s3_url) {
      return res.redirect(row.foto_s3_url);
    }
    if (!buffer || !buffer.length) return res.status(404).json({ error: "Foto no disponible" });
    const safeName = String(row.foto_file_name || "foto.jpg").replace(/[\r\n"]/g, "_");
    res.setHeader("Content-Type", row.foto_content_type || "image/jpeg");
    res.setHeader("Content-Disposition", `inline; filename="${safeName}"`);
    res.setHeader("Content-Length", String(buffer.length));
    res.send(buffer);
  } catch (e) {
    console.error("[SEH foto GET]", e);
    res.status(500).json({ error: e.message });
  } finally {
    client.release();
  }
});

