/**
 * POST /api/seh/carpetas-legales/archivo
 * Body: { planta_id, doc_no, fileBase64, fileName, contentType? }
 */
app.post("/api/seh/carpetas-legales/archivo", dashboardAuthMiddleware, async (req, res) => {
  if (req.dashboardAuth.role === "GA") {
    return res.status(403).json({ error: "GA solo puede ver e imprimir en el dashboard." });
  }
  const plantaId = parseInt(String(req.body?.planta_id || ""), 10);
  const docNo = sehCarpetasLegales.normalizeDocNo(req.body?.doc_no);
  if (!Number.isFinite(plantaId)) return res.status(400).json({ error: "planta_id es obligatorio" });
  if (!docNo) return res.status(400).json({ error: "doc_no inválido" });
  if (!assertSehPlantaAccess(req, plantaId)) {
    return res.status(403).json({ error: "Sin permiso para esta planta" });
  }
  const fileBase64 = typeof req.body?.fileBase64 === "string" ? req.body.fileBase64 : "";
  const fileName =
    req.body?.fileName != null && String(req.body.fileName).trim() !== ""
      ? String(req.body.fileName).trim().slice(0, 200)
      : "documento.pdf";
  let contentType =
    (req.body?.contentType != null ? String(req.body.contentType).trim() : "") || "application/octet-stream";
  if (!fileBase64) return res.status(400).json({ error: "Envía fileBase64" });
  let buffer;
  try {
    buffer = Buffer.from(fileBase64, "base64");
  } catch (_) {
    return res.status(400).json({ error: "fileBase64 inválido" });
  }
  if (!buffer || buffer.length === 0) return res.status(400).json({ error: "Archivo vacío" });
  const MAX_BYTES = 80000 * 1024; // 80,000 KB
  if (buffer.length > MAX_BYTES) {
    return res.status(413).json({ error: `El archivo excede el máximo de ${Math.floor(MAX_BYTES / 1024)}KB` });
  }

  const client = await pool.connect();
  try {
    await sehCarpetasLegales.ensureSehCarpetasLegalesTables(client);
    let s3Key = null;
    let s3Url = null;
    let storeBuffer = buffer;
    if (s3Enabled) {
      s3Key = sehCarpetasLegales.buildArchivoS3Key(plantaId, docNo, fileName);
      try {
        const bucket = s3BucketName;
        const region = process.env.AWS_REGION;
        await s3.send(
          new PutObjectCommand({
            Bucket: bucket,
            Key: s3Key,
            Body: buffer,
            ContentType: contentType,
          })
        );
        s3Url = buildS3PublicUrl(bucket, region, s3Key);
        storeBuffer = null;
      } catch (e) {
        console.error("[SEH carpetas-legales S3]", e);
        s3Key = null;
        s3Url = null;
        storeBuffer = buffer;
      }
    }
    const row = await sehCarpetasLegales.saveArchivo(client, {
      plantaId,
      docNo,
      fileName,
      contentType,
      buffer: storeBuffer || buffer,
      s3Key,
      s3Url,
      actorLabel: sehActorLabel(req.dashboardAuth),
    });
    res.status(201).json({ ok: true, row });
  } catch (e) {
    console.error("[SEH carpetas-legales POST archivo]", e);
    res.status(500).json({ error: e.message });
  } finally {
    client.release();
  }
});

/** GET /api/seh/carpetas-legales/archivo?planta_id=&doc_no= — descarga el archivo. */
app.get("/api/seh/carpetas-legales/archivo", dashboardAuthMiddleware, async (req, res) => {
  const plantaId = parseInt(String(req.query.planta_id || ""), 10);
  const docNo = sehCarpetasLegales.normalizeDocNo(req.query.doc_no);
  if (!Number.isFinite(plantaId)) return res.status(400).json({ error: "planta_id es obligatorio" });
  if (!docNo) return res.status(400).json({ error: "doc_no inválido" });
  if (!assertSehPlantaAccess(req, plantaId)) {
    return res.status(403).json({ error: "Sin permiso para esta planta" });
  }
  const client = await pool.connect();
  try {
    await sehCarpetasLegales.ensureSehCarpetasLegalesTables(client);
    const row = await sehCarpetasLegales.getArchivoRow(client, plantaId, docNo);
    if (!row || !row.file_name) return res.status(404).json({ error: "No hay archivo para este documento" });

    let buffer = null;
    if (row.s3_key && s3Enabled) {
      try {
        buffer = await getBufferFromS3(row.s3_key);
      } catch (e) {
        console.warn("[SEH carpetas-legales download S3]", e.message);
      }
    }
    if (!buffer && row.data) {
      buffer = Buffer.isBuffer(row.data) ? row.data : Buffer.from(row.data);
    }
    if (!buffer || !buffer.length) return res.status(404).json({ error: "Archivo no disponible" });

    const safeName = String(row.file_name || "documento").replace(/[\r\n"]/g, "_");
    res.setHeader("Content-Type", row.content_type || "application/octet-stream");
    res.setHeader("Content-Disposition", `attachment; filename="${safeName}"`);
    res.setHeader("Content-Length", String(buffer.length));
    res.send(buffer);
  } catch (e) {
    console.error("[SEH carpetas-legales GET archivo]", e);
    res.status(500).json({ error: e.message });
  } finally {
    client.release();
  }
});

const SEH_AMBITO_CATEGORIAS = {
  planta: ["PLANTA", "SISTEMA CONTRA INCENDIO"],
  estacion: ["ESTACIONES"],
  autotanque: ["PIPAS"],
};

function sehOperacionRowFilled(row) {
  if (sehIsSci(row.categoria)) {
    return !!(String(row.nombre || "").trim() || row.vence);
  }
  return !!(
    String(row.locacion || "").trim() ||
    String(row.descripcion || "").trim() ||
    String(row.componente || "").trim() ||
    row.vence
  );
}

function sehOperacionRowCumple(row, todayYmd) {
  if (!sehOperacionRowFilled(row)) return false;
  const vence = row.vence ? String(row.vence).slice(0, 10) : "";
  if (!/^\d{4}-\d{2}-\d{2}$/.test(vence)) return false;
  return vence >= todayYmd;
}

function scoreSehOperacion(rows, categorias, todayYmd) {
  const cats = new Set((categorias || []).map((c) => String(c).toUpperCase()));
  let total = 0;
  let complying = 0;
  for (const row of rows || []) {
    if (!cats.has(String(row.categoria || "").toUpperCase())) continue;
    if (!sehOperacionRowFilled(row)) continue;
    total += 1;
    if (sehOperacionRowCumple(row, todayYmd)) complying += 1;
  }
  return { total, complying };
}

async function resolveSehPlantasForCumplimiento(client, req, plantaIdOpt) {
  if (plantaIdOpt != null && Number.isFinite(plantaIdOpt)) {
    if (!assertSehPlantaAccess(req, plantaIdOpt)) return null;
    return [plantaIdOpt];
  }
  const plantas = await getPlantas(client);
  let ids = (plantas || []).map((p) => Number(p.id)).filter(Number.isFinite);
  const role = String(req.dashboardAuth?.role || "").toUpperCase();
  const isGlobal = role === "ZP" || role === "AD" || role === "CF_CDMX";
  const allowed = (req.dashboardAuth.plantas_permitidas || []).map((x) => Number(x)).filter(Number.isFinite);
  if (allowed.length > 0 && (isSehOnlyAuth(req.dashboardAuth) || !isGlobal || isDashboardGV(req))) {
    const set = new Set(allowed);
    ids = ids.filter((id) => set.has(id));
  }
  return ids;
}

/** GET /api/seh/cumplimiento?planta_id= (opcional) */
app.get("/api/seh/cumplimiento", dashboardAuthMiddleware, async (req, res) => {
  const plantaIdOpt =
    req.query.planta_id != null && String(req.query.planta_id).trim() !== ""
      ? parseInt(String(req.query.planta_id), 10)
      : null;
  if (plantaIdOpt != null && !Number.isFinite(plantaIdOpt)) {
    return res.status(400).json({ error: "planta_id inválido" });
  }
  const client = await pool.connect();
  try {
    await sehCarpetasLegales.ensureSehCarpetasLegalesTables(client);
    const plantaIds = await resolveSehPlantasForCumplimiento(client, req, plantaIdOpt);
    if (plantaIds == null) {
      return res.status(403).json({ error: "Sin permiso para esta planta" });
    }
    const today = sehCarpetasLegales.todayYmdMexico();
    const amb = {
      planta: { total: 0, complying: 0 },
      estacion: { total: 0, complying: 0 },
      autotanque: { total: 0, complying: 0 },
    };
    for (const pid of plantaIds) {
      const eq = await client.query(
        `SELECT categoria, COALESCE(locacion,'') AS locacion, COALESCE(descripcion,'') AS descripcion,
                COALESCE(componente,'') AS componente, COALESCE(nombre,'') AS nombre,
                to_char(vence, 'YYYY-MM-DD') AS vence
         FROM public.seh_equipos WHERE planta_id = $1`,
        [pid]
      );
      const rows = eq.rows || [];
      for (const [key, cats] of Object.entries(SEH_AMBITO_CATEGORIAS)) {
        const s = scoreSehOperacion(rows, cats, today);
        amb[key].total += s.total;
        amb[key].complying += s.complying;
      }
      const carpetasRows = await sehCarpetasLegales.listByPlanta(client, pid);
      const reg = sehCarpetasLegales.scoreRegulacion(carpetasRows, today);
      amb.planta.total += reg.total;
      amb.planta.complying += reg.complying;
    }
    const build = (key) => {
      const t = amb[key].total;
      const c = amb[key].complying;
      return {
        ambito: key,
        complying: c,
        total: t,
        pct: t > 0 ? Math.round((100 * c) / t) : 0,
      };
    };
    res.json({
      planta_id: plantaIdOpt != null && Number.isFinite(plantaIdOpt) ? plantaIdOpt : null,
      plantas_count: plantaIds.length,
      regulacion_catalog_total: sehCarpetasLegales.CATALOG_TOTAL,
      ambitos: {
        planta: build("planta"),
        estacion: build("estacion"),
        autotanque: build("autotanque"),
      },
    });
  } catch (e) {
    console.error("[SEH cumplimiento]", e);
    res.status(500).json({ error: e.message });
  } finally {
    client.release();
  }
});

