async function ensureActionRegisterTables(client) {
  await client.query(`CREATE SCHEMA IF NOT EXISTS arr;`).catch(() => {});
  await client.query(`
    CREATE TABLE IF NOT EXISTS arr.action_register_revisions (
      id SERIAL PRIMARY KEY,
      planta_id INT NOT NULL REFERENCES public.plantas(id),
      revision_date DATE NOT NULL,
      created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
      created_by_usuario_id INT NULL REFERENCES public.usuarios(id),
      UNIQUE(planta_id, revision_date)
    );
  `).catch(() => {});
  await client.query(`
    CREATE TABLE IF NOT EXISTS arr.action_register_items (
      id SERIAL PRIMARY KEY,
      planta_id INT NOT NULL REFERENCES public.plantas(id),
      tema TEXT NOT NULL,
      parent_id INT NULL REFERENCES arr.action_register_items(id) ON DELETE CASCADE,
      title TEXT NOT NULL,
      responsable TEXT NOT NULL DEFAULT '',
      due_date DATE NULL,
      closed BOOLEAN NOT NULL DEFAULT false,
      created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
      updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
    );
  `).catch(() => {});
  // Responsable normalizado a usuario (para dropdown y notificaciones).
  await client
    .query(`ALTER TABLE arr.action_register_items ADD COLUMN IF NOT EXISTS responsable_usuario_id INT NULL REFERENCES public.usuarios(id);`)
    .catch(() => {});
  // Tracking de notificación (Twilio).
  await client.query(`ALTER TABLE arr.action_register_items ADD COLUMN IF NOT EXISTS twilio_sid_1 TEXT NULL;`).catch(() => {});
  await client.query(`ALTER TABLE arr.action_register_items ADD COLUMN IF NOT EXISTS notify_error TEXT NULL;`).catch(() => {});
  await client.query(`
    CREATE TABLE IF NOT EXISTS arr.action_register_entries (
      id SERIAL PRIMARY KEY,
      revision_id INT NOT NULL REFERENCES arr.action_register_revisions(id) ON DELETE CASCADE,
      item_id INT NOT NULL REFERENCES arr.action_register_items(id) ON DELETE CASCADE,
      position INT NOT NULL DEFAULT 0,
      UNIQUE(revision_id, item_id)
    );
  `).catch(() => {});
  await client.query(`
    CREATE TABLE IF NOT EXISTS arr.action_register_attachments (
      id SERIAL PRIMARY KEY,
      item_id INT NOT NULL REFERENCES arr.action_register_items(id) ON DELETE CASCADE,
      file_name TEXT NOT NULL DEFAULT '',
      content_type TEXT NOT NULL DEFAULT 'image/jpeg',
      file_size_bytes INT NOT NULL DEFAULT 0,
      s3_key TEXT NULL,
      s3_url TEXT NULL,
      data BYTEA NULL,
      uploaded_by_usuario_id INT NULL REFERENCES public.usuarios(id),
      created_at TIMESTAMPTZ NOT NULL DEFAULT now()
    );
  `).catch(() => {});
  await client.query(`
    CREATE TABLE IF NOT EXISTS arr.action_register_revision_notes (
      id SERIAL PRIMARY KEY,
      revision_id INT NOT NULL REFERENCES arr.action_register_revisions(id) ON DELETE CASCADE,
      body TEXT NOT NULL,
      author_name TEXT NOT NULL DEFAULT '',
      created_by_usuario_id INT NULL REFERENCES public.usuarios(id),
      created_at TIMESTAMPTZ NOT NULL DEFAULT now()
    );
  `).catch(() => {});
  // Fotos de evidencia para acciones DICF (Delta Ingreso Cliente Forecast).
  await client.query(`
    CREATE TABLE IF NOT EXISTS arr.dicf_acciones_attachments (
      id SERIAL PRIMARY KEY,
      dicf_accion_id INT NOT NULL REFERENCES arr.dicf_acciones(id) ON DELETE CASCADE,
      file_name TEXT NOT NULL DEFAULT '',
      content_type TEXT NOT NULL DEFAULT 'image/jpeg',
      file_size_bytes INT NOT NULL DEFAULT 0,
      s3_key TEXT NULL,
      s3_url TEXT NULL,
      data BYTEA NULL,
      uploaded_by_usuario_id INT NULL REFERENCES public.usuarios(id),
      created_at TIMESTAMPTZ NOT NULL DEFAULT now()
    );
  `).catch(() => {});
  // Fotos de evidencia para comentarios del día (notas por revisión).
  await client.query(`
    CREATE TABLE IF NOT EXISTS arr.action_register_revision_note_attachments (
      id SERIAL PRIMARY KEY,
      note_id INT NOT NULL REFERENCES arr.action_register_revision_notes(id) ON DELETE CASCADE,
      file_name TEXT NOT NULL DEFAULT '',
      content_type TEXT NOT NULL DEFAULT 'image/jpeg',
      file_size_bytes INT NOT NULL DEFAULT 0,
      s3_key TEXT NULL,
      s3_url TEXT NULL,
      data BYTEA NULL,
      uploaded_by_usuario_id INT NULL REFERENCES public.usuarios(id),
      created_at TIMESTAMPTZ NOT NULL DEFAULT now()
    );
  `).catch(() => {});
  await client.query(`CREATE INDEX IF NOT EXISTS idx_ar_revisions_planta_date ON arr.action_register_revisions(planta_id, revision_date);`).catch(() => {});
  await client.query(`CREATE INDEX IF NOT EXISTS idx_ar_items_planta_tema ON arr.action_register_items(planta_id, tema);`).catch(() => {});
  await client.query(`CREATE INDEX IF NOT EXISTS idx_ar_entries_revision_pos ON arr.action_register_entries(revision_id, position);`).catch(() => {});
  await client.query(`CREATE INDEX IF NOT EXISTS idx_ar_attachments_item ON arr.action_register_attachments(item_id);`).catch(() => {});
  await client.query(`CREATE INDEX IF NOT EXISTS idx_ar_notes_revision ON arr.action_register_revision_notes(revision_id, created_at);`).catch(() => {});
  await client.query(`CREATE INDEX IF NOT EXISTS idx_dicf_attachments_accion ON arr.dicf_acciones_attachments(dicf_accion_id);`).catch(() => {});
  await client.query(`CREATE INDEX IF NOT EXISTS idx_ar_note_attachments_note ON arr.action_register_revision_note_attachments(note_id);`).catch(() => {});
}

/** Sube una imagen al bucket S3 con su content-type correcto. Devuelve publicUrl. */
async function uploadImageToS3(buffer, key, contentType) {
  if (!s3Enabled) throw new Error("S3 no configurado");
  const bucket = s3BucketName;
  const region = process.env.AWS_REGION;
  await s3.send(new PutObjectCommand({
    Bucket: bucket,
    Key: key,
    Body: buffer,
    ContentType: contentType || "image/jpeg",
  }));
  return buildS3PublicUrl(bucket, region, key);
}

/** Devuelve el buffer binario de una foto del Action Register (desde S3 o bytea). */
async function getActionRegisterAttachmentBuffer(client, attachmentRow) {
  if (!attachmentRow) return null;
  if (attachmentRow.s3_key && s3Enabled) {
    try { return await getBufferFromS3(attachmentRow.s3_key); } catch (e) {}
  }
  if (attachmentRow.data) {
    return Buffer.isBuffer(attachmentRow.data) ? attachmentRow.data : Buffer.from(attachmentRow.data);
  }
  // Último intento: si no se trajo data en el SELECT original, leerla ahora.
  try {
    const r = await client.query(`SELECT data FROM arr.action_register_attachments WHERE id = $1`, [attachmentRow.id]);
    if (r.rows[0] && r.rows[0].data) return Buffer.from(r.rows[0].data);
  } catch (e) {}
  return null;
}

/** Devuelve el buffer binario de una foto de nota (comentario del día). */
async function getNoteAttachmentBuffer(client, attachmentRow) {
  if (!attachmentRow) return null;
  if (attachmentRow.s3_key && s3Enabled) {
    try { return await getBufferFromS3(attachmentRow.s3_key); } catch (e) {}
  }
  if (attachmentRow.data) {
    return Buffer.isBuffer(attachmentRow.data) ? attachmentRow.data : Buffer.from(attachmentRow.data);
  }
  try {
    const r = await client.query(`SELECT data FROM arr.action_register_revision_note_attachments WHERE id = $1`, [attachmentRow.id]);
    if (r.rows[0] && r.rows[0].data) return Buffer.from(r.rows[0].data);
  } catch (e) {}
  return null;
}

/** Devuelve el buffer binario de una foto de DICF (desde S3 o bytea). */
async function getDicfAttachmentBuffer(client, attachmentRow) {
  if (!attachmentRow) return null;
  if (attachmentRow.s3_key && s3Enabled) {
    try { return await getBufferFromS3(attachmentRow.s3_key); } catch (e) {}
  }
  if (attachmentRow.data) {
    return Buffer.isBuffer(attachmentRow.data) ? attachmentRow.data : Buffer.from(attachmentRow.data);
  }
  try {
    const r = await client.query(`SELECT data FROM arr.dicf_acciones_attachments WHERE id = $1`, [attachmentRow.id]);
    if (r.rows[0] && r.rows[0].data) return Buffer.from(r.rows[0].data);
  } catch (e) {}
  return null;
}

function assertDashboardPlantaAccessForActionRegister(req, plantaId) {
  // Action Register: ZP/AD/CF_CDMX acceso global por role (sin lista de plantas en el JWT).
  const roleNorm = dashboardAuthRoleNorm(req.dashboardAuth);
  if (roleNorm === "ZP" || roleNorm === "AD" || roleNorm === "CF_CDMX") return true;
  const allowed = new Set((req.dashboardAuth.plantas_permitidas || []).map((x) => Number(x)).filter(Number.isFinite));
  return allowed.has(Number(plantaId));
}

