async function buildDashboardSignedUrlForUsuario(client, usuarioRow, dashboardPath, options) {
  if (!usuarioRow || usuarioRow.id == null) return "";
  const opts = options && typeof options === "object" ? options : {};
  const rolClave = (usuarioRow.rol_clave && String(usuarioRow.rol_clave).toUpperCase()) || "";
  const rolNom = (usuarioRow.rol_nombre && String(usuarioRow.rol_nombre)) || "";
  const esZP = isDirectorZPForDashboard(rolClave, rolNom);
  const normalizarParaAD = (s) => (s || "").toLowerCase().normalize("NFD").replace(/\p{M}/gu, "").replace(/[\s\u00a0]+/g, " ").trim();
  const rolNormNombre = normalizarParaAD(rolNom);
  const nombreUsuarioNorm = normalizarParaAD(usuarioRow.nombre || usuarioRow.nombre_persona || "");
  const esAD =
    rolClave === "AD" ||
    (/asistente/.test(rolNormNombre) && /direccion/.test(rolNormNombre)) ||
    (/asistente/.test(nombreUsuarioNorm) && /direccion/.test(nombreUsuarioNorm));
  const esCFCDMX =
    rolClave === "CF_CDMX" ||
    (/contralor/.test(rolNormNombre) && /cdmx/.test(rolNormNombre)) ||
    (/contralor/.test(nombreUsuarioNorm) && /cdmx/.test(nombreUsuarioNorm));
  const esGA = rolClave === "GA";
  const esGV = rolClave === "GV";
  const role = esZP ? "ZP" : esAD ? "AD" : esCFCDMX ? "CF_CDMX" : esGA ? "GA" : esGV ? "GV" : "GG";
  // ZP/AD/CF_CDMX: no listar plantas en el JWT (evita URLs que WhatsApp parte).
  let plantasPermitidas = [];
  if (!(esZP || esAD || esCFCDMX) && usuarioRow.planta_id != null) {
    plantasPermitidas = dicfAccionesLib.getPlantaIdsEquivalentes(usuarioRow.planta_id);
  }
  const tokenPayload = {
    role,
    actor_id: usuarioRow.id,
    plantas_permitidas: plantasPermitidas,
    default_filters: {},
    permisos: permisosForDashboardToken(role, usuarioRow),
  };
  if (opts.scope) tokenPayload.scope = opts.scope;
  if (opts.scope === "seh" || opts.includeActorProfile) {
    tokenPayload.actor_nombre = usuarioRow.nombre || usuarioRow.nombre_persona || "";
    tokenPayload.actor_telefono = usuarioRow.telefono || "";
  }
  const token = createDashboardToken(tokenPayload);
  const baseUrl = (process.env.DASHBOARD_URL || process.env.FRONTEND_URL || "").trim().replace(/\/$/, "");
  if (!baseUrl) return "";
  const path = String(dashboardPath || "acciones").replace(/^\/+/, "");
  return `${baseUrl}/${path}?t=${encodeDashboardTokenForWhatsAppUrl(token)}`;
}

async function buildActionRegisterUrl(client, usuarioRow) {
  return buildDashboardSignedUrlForUsuario(client, usuarioRow, "acciones");
}

/** Enlace SEH con token de acceso exclusivo (solo /seh y APIs SEH). */
async function buildSehSignedUrlForUsuario(client, usuarioRow) {
  return buildDashboardSignedUrlForUsuario(client, usuarioRow, "seh", { scope: "seh" });
}

app.post("/api/action-register/items", dashboardAuthMiddleware, async (req, res) => {
  const body = req.body || {};
  const revision_id = body.revision_id != null ? parseInt(body.revision_id, 10) : null;
  const planta_id = body.planta_id != null ? parseInt(body.planta_id, 10) : null;
  const tema = body.tema != null ? String(body.tema).trim() : "";
  const parent_id = body.parent_id != null && body.parent_id !== "" ? parseInt(body.parent_id, 10) : null;
  const title = body.title != null ? String(body.title).trim() : "";
  const responsable_usuario_id =
    body.responsable_usuario_id != null && body.responsable_usuario_id !== ""
      ? parseInt(body.responsable_usuario_id, 10)
      : null;
  let responsable = body.responsable != null ? String(body.responsable).trim() : "";
  const due_date = body.due_date != null && String(body.due_date).trim() !== "" ? String(body.due_date).trim() : null;
  if (!revision_id || !Number.isFinite(revision_id)) return res.status(400).json({ error: "revision_id requerido" });
  if (!planta_id || !Number.isFinite(planta_id)) return res.status(400).json({ error: "planta_id requerido" });
  if (!tema || !isActionRegisterTema(tema)) return res.status(400).json({ error: "tema inválido" });
  if (!title || title.length < 2) return res.status(400).json({ error: "title es obligatorio (mín. 2 caracteres)" });
  if (!assertDashboardPlantaAccessForActionRegister(req, planta_id)) return res.status(403).json({ error: "Sin acceso a esta planta" });
  if (due_date && !/^\d{4}-\d{2}-\d{2}$/.test(due_date)) return res.status(400).json({ error: "due_date inválida (YYYY-MM-DD)" });
  const client = await pool.connect();
  try {
    await ensureActionRegisterTables(client);
    const rv = await client.query(`SELECT id, planta_id FROM arr.action_register_revisions WHERE id = $1`, [revision_id]);
    if (!rv.rows[0]) return res.status(404).json({ error: "revision no encontrada" });
    if (Number(rv.rows[0].planta_id) !== Number(planta_id)) return res.status(400).json({ error: "planta_id no coincide con la revision" });

    let responsableUser = null;
    if (responsable_usuario_id != null && Number.isFinite(responsable_usuario_id)) {
      const equivPlantas = dicfAccionesLib.getPlantaIdsEquivalentes(planta_id);
      const ru = await client.query(
        `SELECT u.id, u.planta_id, u.telefono, u.nombre, u.nombre_persona,
                COALESCE(NULLIF(TRIM(COALESCE(u.nombre_persona,'')), ''), u.nombre) AS nombre_mostrar,
                r.clave AS rol_clave, r.nombre AS rol_nombre
         FROM public.usuarios u
         LEFT JOIN public.roles r ON r.id = u.rol_id
         WHERE u.id = $1 AND (u.activo IS NULL OR u.activo = true)`,
        [responsable_usuario_id]
      );
      responsableUser = ru.rows[0] || null;
      if (!responsableUser) return res.status(400).json({ error: "Responsable no encontrado" });
      if (responsableUser.planta_id == null || !equivPlantas.includes(Number(responsableUser.planta_id))) {
        return res.status(400).json({ error: "El responsable no está asignado a esta planta" });
      }
      responsable = String(responsableUser.nombre_mostrar || "").trim();
    }

    if (parent_id && Number.isFinite(parent_id)) {
      const pr = await client.query(`SELECT id, planta_id, tema FROM arr.action_register_items WHERE id = $1`, [parent_id]);
      if (!pr.rows[0]) return res.status(400).json({ error: "parent_id no existe" });
      if (Number(pr.rows[0].planta_id) !== Number(planta_id)) return res.status(400).json({ error: "parent_id es de otra planta" });
      if (String(pr.rows[0].tema) !== tema) return res.status(400).json({ error: "parent_id es de otro tema" });
    }

    const pos = await client.query(
      `SELECT COALESCE(MAX(e.position), -1)::INT AS maxpos
       FROM arr.action_register_entries e
       JOIN arr.action_register_items i ON i.id = e.item_id
       WHERE e.revision_id = $1 AND i.tema = $2`,
      [revision_id, tema]
    );
    const position = (pos.rows[0] && parseInt(pos.rows[0].maxpos, 10)) >= 0 ? parseInt(pos.rows[0].maxpos, 10) + 1 : 0;

    const ins = await client.query(
      `INSERT INTO arr.action_register_items (planta_id, tema, parent_id, title, responsable, responsable_usuario_id, due_date)
       VALUES ($1, $2, $3, $4, $5, $6, $7::DATE)
       RETURNING id, planta_id, tema, parent_id, title, responsable, responsable_usuario_id, due_date, closed`,
      [planta_id, tema, parent_id || null, title, responsable || "", responsableUser ? responsableUser.id : null, due_date]
    );
    const item = ins.rows[0];
    await client.query(
      `INSERT INTO arr.action_register_entries (revision_id, item_id, position)
       VALUES ($1, $2, $3)
       ON CONFLICT (revision_id, item_id) DO NOTHING`,
      [revision_id, item.id, position]
    );
    let notif = null;
    if (responsableUser && responsableUser.telefono) {
      const link = await buildActionRegisterUrl(client, responsableUser);
      const msg =
        `📌 Nueva acción (Action Register)\n` +
        `Planta: ${planta_id}\n` +
        `Tema: ${tema}\n` +
        `Acción: ${title}\n` +
        (due_date ? `Compromiso: ${due_date}\n` : "") +
        (link ? `\n🔗 Abrir Action Register (válido 20 h):\n${link}\n` : "");
      const rSend = await sendWhatsApp(responsableUser.telefono, msg, { event: "action_register_new" });
      notif = rSend.ok ? { ok: true } : { ok: false, error: rSend.error };
      await client.query(
        `UPDATE arr.action_register_items SET twilio_sid_1 = $2, notify_error = $3, updated_at = now() WHERE id = $1`,
        [item.id, rSend.sid || null, rSend.ok ? null : String(rSend.error || "")]
      );
    }
    res.status(201).json({ item: { ...item, position }, notificacion: notif });
  } catch (e) {
    console.error("[ActionRegister POST items]", e);
    res.status(500).json({ error: e.message });
  } finally {
    client.release();
  }
});

app.post("/api/action-register/entries", dashboardAuthMiddleware, async (req, res) => {
  const body = req.body || {};
  const revision_id = body.revision_id != null ? parseInt(body.revision_id, 10) : null;
  const item_id = body.item_id != null ? parseInt(body.item_id, 10) : null;
  if (!revision_id || !Number.isFinite(revision_id)) return res.status(400).json({ error: "revision_id requerido" });
  if (!item_id || !Number.isFinite(item_id)) return res.status(400).json({ error: "item_id requerido" });
  const client = await pool.connect();
  try {
    await ensureActionRegisterTables(client);
    const rv = await client.query(`SELECT id, planta_id FROM arr.action_register_revisions WHERE id = $1`, [revision_id]);
    if (!rv.rows[0]) return res.status(404).json({ error: "revision no encontrada" });
    const it = await client.query(`SELECT id, planta_id, tema FROM arr.action_register_items WHERE id = $1`, [item_id]);
    if (!it.rows[0]) return res.status(404).json({ error: "item no encontrado" });
    if (Number(it.rows[0].planta_id) !== Number(rv.rows[0].planta_id)) return res.status(400).json({ error: "item no pertenece a la planta de la revisión" });
    if (!assertDashboardPlantaAccessForActionRegister(req, Number(rv.rows[0].planta_id))) return res.status(403).json({ error: "Sin acceso a esta planta" });
    const tema = String(it.rows[0].tema || "");

    const pos = await client.query(
      `SELECT COALESCE(MAX(e.position), -1)::INT AS maxpos
       FROM arr.action_register_entries e
       JOIN arr.action_register_items i ON i.id = e.item_id
       WHERE e.revision_id = $1 AND i.tema = $2`,
      [revision_id, tema]
    );
    const position = (pos.rows[0] && parseInt(pos.rows[0].maxpos, 10)) >= 0 ? parseInt(pos.rows[0].maxpos, 10) + 1 : 0;

    await client.query(
      `INSERT INTO arr.action_register_entries (revision_id, item_id, position)
       VALUES ($1, $2, $3)
       ON CONFLICT (revision_id, item_id) DO NOTHING`,
      [revision_id, item_id, position]
    );
    res.status(201).json({ ok: true, position });
  } catch (e) {
    console.error("[ActionRegister POST entries]", e);
    res.status(500).json({ error: e.message });
  } finally {
    client.release();
  }
});

app.patch("/api/action-register/items/:id", dashboardAuthMiddleware, async (req, res) => {
  const id = req.params.id != null ? parseInt(String(req.params.id), 10) : null;
  if (!id || !Number.isFinite(id)) return res.status(400).json({ error: "id inválido" });
  const body = req.body || {};
  const fields = {};
  if (body.title != null) fields.title = String(body.title).trim();
  if (body.responsable != null) fields.responsable = String(body.responsable).trim();
  if (body.responsable_usuario_id !== undefined) {
    fields.responsable_usuario_id =
      body.responsable_usuario_id == null || body.responsable_usuario_id === "" ? null : parseInt(body.responsable_usuario_id, 10);
  }
  if (body.due_date !== undefined) fields.due_date = body.due_date ? String(body.due_date).trim() : null;
  if (body.closed !== undefined) fields.closed = body.closed === true || body.closed === "true";

  const client = await pool.connect();
  try {
    await ensureActionRegisterTables(client);
    const it = await client.query(`SELECT id, planta_id FROM arr.action_register_items WHERE id = $1`, [id]);
    if (!it.rows[0]) return res.status(404).json({ error: "item no encontrado" });
    const planta_id = Number(it.rows[0].planta_id);
    if (!assertDashboardPlantaAccessForActionRegister(req, planta_id)) return res.status(403).json({ error: "Sin acceso a esta planta" });

    const sets = [];
    const params = [];
    let idx = 1;
    if (fields.title != null) {
      if (!fields.title || fields.title.length < 2) return res.status(400).json({ error: "title inválido" });
      sets.push(`title = $${idx++}`);
      params.push(fields.title);
    }
    if (fields.responsable != null) {
      sets.push(`responsable = $${idx++}`);
      params.push(fields.responsable);
    }
    if (fields.responsable_usuario_id !== undefined) {
      // Valida que el responsable pertenezca a la planta del item.
      if (fields.responsable_usuario_id == null) {
        sets.push(`responsable_usuario_id = NULL`);
      } else {
        if (!Number.isFinite(fields.responsable_usuario_id)) return res.status(400).json({ error: "responsable_usuario_id inválido" });
        const equivPlantas = dicfAccionesLib.getPlantaIdsEquivalentes(planta_id);
        const ru = await client.query(
          `SELECT u.id, u.planta_id,
                  COALESCE(NULLIF(TRIM(COALESCE(u.nombre_persona,'')), ''), u.nombre) AS nombre_mostrar
           FROM public.usuarios u
           WHERE u.id = $1 AND (u.activo IS NULL OR u.activo = true)`,
          [fields.responsable_usuario_id]
        );
        const responsableUser = ru.rows[0] || null;
        if (!responsableUser) return res.status(400).json({ error: "Responsable no encontrado" });
        if (responsableUser.planta_id == null || !equivPlantas.includes(Number(responsableUser.planta_id))) {
          return res.status(400).json({ error: "El responsable no está asignado a esta planta" });
        }
        sets.push(`responsable_usuario_id = $${idx++}`);
        params.push(responsableUser.id);
        // Si no mandaron string, normaliza el display al nombre de usuario.
        if (fields.responsable == null) {
          sets.push(`responsable = $${idx++}`);
          params.push(String(responsableUser.nombre_mostrar || "").trim());
        }
      }
    }
    if (fields.due_date !== undefined) {
      if (fields.due_date && !/^\d{4}-\d{2}-\d{2}$/.test(fields.due_date)) return res.status(400).json({ error: "due_date inválida (YYYY-MM-DD)" });
      sets.push(`due_date = $${idx++}::DATE`);
      params.push(fields.due_date);
    }
    if (fields.closed !== undefined) {
      sets.push(`closed = $${idx++}`);
      params.push(fields.closed);
    }
    if (!sets.length) return res.json({ ok: true });
    sets.push(`updated_at = now()`);
    params.push(id);
    const q = `UPDATE arr.action_register_items SET ${sets.join(", ")} WHERE id = $${idx} RETURNING id, planta_id, tema, parent_id, title, responsable, responsable_usuario_id, due_date, closed`;
    const up = await client.query(q, params);
    res.json({ item: up.rows[0] });
  } catch (e) {
    console.error("[ActionRegister PATCH item]", e);
    res.status(500).json({ error: e.message });
  } finally {
    client.release();
  }
});

/** Content-types aceptados para evidencia fotográfica del Action Register. */
const ACTION_REGISTER_IMAGE_MIME = new Set([
  "image/jpeg",
  "image/jpg",
  "image/pjpeg",
  "image/png",
  "image/webp",
  "image/gif",
]);

function actionRegisterMimeToExt(mime) {
  const m = String(mime || "").toLowerCase();
  if (m === "image/png") return "png";
  if (m === "image/webp") return "webp";
  if (m === "image/gif") return "gif";
  return "jpg";
}

/** Sube una foto (base64) como evidencia de una acción/subacción. */
app.post("/api/action-register/items/:id/attachments", dashboardAuthMiddleware, async (req, res) => {
  const itemId = parseInt(String(req.params.id), 10);
  if (!itemId || !Number.isFinite(itemId)) return res.status(400).json({ error: "id inválido" });
  const body = req.body || {};
  const fileBase64 = typeof body.fileBase64 === "string" ? body.fileBase64 : "";
  const fileName = body.fileName != null && String(body.fileName).trim() !== "" ? String(body.fileName).trim().slice(0, 200) : "foto.jpg";
  let contentType = (body.contentType != null ? String(body.contentType).trim().toLowerCase() : "image/jpeg") || "image/jpeg";
  if (!ACTION_REGISTER_IMAGE_MIME.has(contentType)) {
    const lowerName = fileName.toLowerCase();
    if (lowerName.endsWith(".png")) contentType = "image/png";
    else if (lowerName.endsWith(".webp")) contentType = "image/webp";
    else if (lowerName.endsWith(".gif")) contentType = "image/gif";
    else contentType = "image/jpeg";
  }
  if (!fileBase64) return res.status(400).json({ error: "Envía fileBase64 (imagen)" });
  let buffer;
  try { buffer = Buffer.from(fileBase64, "base64"); } catch (e) { return res.status(400).json({ error: "fileBase64 inválido" }); }
  if (!buffer || buffer.length === 0) return res.status(400).json({ error: "Archivo vacío" });
  const MAX_BYTES = 8 * 1024 * 1024; // 8MB
  if (buffer.length > MAX_BYTES) return res.status(413).json({ error: `La imagen excede el tamaño máximo de ${Math.floor(MAX_BYTES / 1024 / 1024)}MB` });

  const client = await pool.connect();
  try {
    await ensureActionRegisterTables(client);
    const it = await client.query(`SELECT id, planta_id FROM arr.action_register_items WHERE id = $1`, [itemId]);
    if (!it.rows[0]) return res.status(404).json({ error: "Acción no encontrada" });
    const plantaId = Number(it.rows[0].planta_id);
    if (!assertDashboardPlantaAccessForActionRegister(req, plantaId)) return res.status(403).json({ error: "Sin acceso a esta planta" });

    let s3Key = null;
    let s3Url = null;
    let bytea = null;
    if (s3Enabled) {
      const ext = actionRegisterMimeToExt(contentType);
      s3Key = `action-register/${plantaId}/${itemId}/${Date.now()}-${crypto.randomBytes(4).toString("hex")}.${ext}`;
      try {
        s3Url = await uploadImageToS3(buffer, s3Key, contentType);
      } catch (e) {
        console.error("[ActionRegister attachments S3]", e);
        s3Key = null;
        s3Url = null;
        bytea = buffer;
      }
    } else {
      bytea = buffer;
    }

    const ins = await client.query(
      `INSERT INTO arr.action_register_attachments (item_id, file_name, content_type, file_size_bytes, s3_key, s3_url, data, uploaded_by_usuario_id)
       VALUES ($1, $2, $3, $4, $5, $6, $7, $8)
       RETURNING id, item_id, file_name, content_type, file_size_bytes, s3_key, s3_url, created_at`,
      [itemId, fileName, contentType, buffer.length, s3Key, s3Url, bytea, req.dashboardAuth.actor_id || null]
    );
    const row = ins.rows[0];
    res.status(201).json({
      attachment: {
        id: row.id,
        item_id: row.item_id,
        file_name: row.file_name,
        content_type: row.content_type,
        file_size_bytes: row.file_size_bytes,
        created_at: row.created_at,
      },
    });
  } catch (e) {
    console.error("[ActionRegister POST attachment]", e);
    res.status(500).json({ error: e.message });
  } finally {
    client.release();
  }
});

