/**
 * Recalcula Util. Oper. y Resultado final.
 * Util. Oper. ($/kg): parte de Margen y resta cada costo respetando el signo visible en la tabla.
 * Resultado = Util. Oper. - Gtos/Apoyos Corp - Bancos Corp - Otros Programas - Inversiones.
 * (Inversiones en fila API se guardan como magnitud positiva de costo; en pantalla suelen verse negativas.)
 */
function recalcularUtilYResultado(row) {
  const n = (v) => (v != null && Number.isFinite(Number(v)) ? Number(v) : 0);
  const margen = n(row.margen_kg);
  const comDesc = n(row.com_desc_kg);
  const impuesto = n(row.impuesto_kg);
  const hgKg = n(row.hg_kg);
  const bancosPlanta = n(row.bancos_planta_kg);
  const provisionPlanta = n(row.provision_planta_kg);
  const presupuesto = n(row.presupuesto_kg);
  const foliosZP = n(row.folios_aprob_zp_kg);
  const foliosCarro = n(row.folios_carro_kg);
  const depositoCierreKg = n(row.deposito_cierre_kg);
  const ventaTon = n(row.venta_ton);
  const ventaKg = ventaTon * 1000;
  const gtosCorp = n(row.gtos_apoyos_corp_kg);
  const bancosCorp = n(row.bancos_corp_kg);
  const otrosProg = n(row.otros_programas_kg);
  const inversiones = n(row.inversiones_kg);

  const util_oper_kg =
    margen +
    comDesc +
    depositoCierreKg -
    presupuesto -
    foliosZP -
    foliosCarro -
    impuesto -
    hgKg -
    bancosPlanta -
    provisionPlanta;
  const util_oper_importe = ventaKg > 0 ? util_oper_kg * ventaKg : 0;
  const resultado_final_kg = util_oper_kg - gtosCorp - bancosCorp - otrosProg - inversiones;
  const resultado_final_importe = ventaKg > 0 ? resultado_final_kg * ventaKg : 0;
  return { util_oper_kg, util_oper_importe, resultado_final_kg, resultado_final_importe };
}

/** PATCH IGF Forecast: actualizar HG % (y opcionalmente HG $/kg) por empresa; recalcula Util. Oper. y Resultado. */
app.patch("/api/dashboard/igf-forecast", dashboardAuthMiddleware, async (req, res) => {
  if (dashboardBlockGAFinancialKpis(req, res)) return;
  if (dashboardBlockGVForbidden(req, res)) return;
  const year = req.body?.year != null ? parseInt(String(req.body.year), 10) : new Date().getFullYear();
  const month = req.body?.month != null ? parseInt(String(req.body.month), 10) : new Date().getMonth() + 1;
  const empresa = req.body?.empresa != null ? String(req.body.empresa).trim() : "";
  const hg_pct = req.body?.hg_pct != null && req.body.hg_pct !== "" ? Number(req.body.hg_pct) : null;
  const hg_kg = req.body?.hg_kg != null && req.body.hg_kg !== "" ? Number(req.body.hg_kg) : null;
  const uploadDayBody = (req.body?.upload_day != null ? String(req.body.upload_day).trim().slice(0, 10) : "") || "";
  const versionAsOfCorteBody = /^(1|true|yes)$/i.test(String(req.body?.version_as_of_corte ?? "").trim());
  if (!Number.isFinite(year) || !Number.isFinite(month) || month < 1 || month > 12 || !empresa) {
    return res.status(400).json({ error: "Faltan year, month o empresa" });
  }
  if (uploadDayBody && !/^\d{4}-\d{2}-\d{2}$/.test(uploadDayBody)) {
    return res.status(400).json({ error: "upload_day debe ser YYYY-MM-DD" });
  }
  if (uploadDayBody) {
    if (!isIgfUploadDayAllowedForMonth(year, month, uploadDayBody)) {
      return res.status(400).json({
        error: "upload_day debe ser >= el primer día del mes (mismo mes = abierto; fecha posterior = mes cerrado)",
      });
    }
  }
  if (versionAsOfCorteBody && !uploadDayBody) {
    return res.status(400).json({ error: "version_as_of_corte requiere upload_day" });
  }
  const client = await pool.connect();
  try {
    const uploadOpts = {};
    if (uploadDayBody && /^\d{4}-\d{2}-\d{2}$/.test(uploadDayBody)) uploadOpts.upload_day = uploadDayBody;
    if (versionAsOfCorteBody) uploadOpts.version_as_of_corte = true;
    /** Misma fila que ve el GET (venta forecast, presupuesto/folios en $/kg, HG ya normalizado). */
    const payload = await buildIgfForecastPayload(
      client,
      year,
      month,
      Object.keys(uploadOpts).length ? uploadOpts : undefined
    );
    const versionId = payload.version_id != null ? Number(payload.version_id) : null;
    if (versionId == null) return res.status(404).json({ error: "No hay versión IGF para ese mes" });

    const empNorm = normalizeAccents(empresa);
    const matchRow =
      (payload.rows || []).find((r) => (r.empresa || "").trim() === empresa) ||
      (payload.rows || []).find((r) => normalizeAccents((r.empresa || "").trim()) === empNorm);
    if (!matchRow) return res.status(404).json({ error: "Empresa no encontrada en forecast provincia" });

    let newHgPct = matchRow.hg_pct;
    let newHgKg = matchRow.hg_kg != null ? Number(matchRow.hg_kg) : 0;
    /** true solo si hg $/kg se derivó de hg % (no vino hg_kg explícito en el body). */
    let derivedHgKgFromPct = false;
    if (hg_pct != null && Number.isFinite(hg_pct)) {
      newHgPct = hg_pct >= 0 && hg_pct <= 1 ? hg_pct : hg_pct / 100;
      if (hg_kg == null || !Number.isFinite(hg_kg)) {
        derivedHgKgFromPct = true;
        const curHgPct = matchRow.hg_pct != null ? Number(matchRow.hg_pct) : null;
        const curHgKg = matchRow.hg_kg != null ? Number(matchRow.hg_kg) : 0;
        if (curHgPct != null && Number.isFinite(curHgPct) && curHgPct !== 0 && Number.isFinite(curHgKg)) {
          newHgKg = (curHgKg / curHgPct) * newHgPct;
        } else {
          newHgKg = curHgKg;
        }
      }
    }
    if (hg_kg != null && Number.isFinite(hg_kg)) {
      newHgKg = hg_kg;
      derivedHgKgFromPct = false;
    }

    if (derivedHgKgFromPct && Number.isFinite(newHgKg) && newHgKg > 0) {
      const provRes = await client.query("SELECT plant_code FROM arr.provincia_plants ORDER BY plant_code");
      const provinciaPlantCodesPatch = (provRes.rows || []).map((r) => (r.plant_code || "").trim()).filter(Boolean);
      const esProvinciaPatch = (emp) => {
        if (!emp || /^TOTALES?$/i.test(String(emp).trim())) return false;
        const en = normalizeAccents(emp);
        return provinciaPlantCodesPatch.some((p) => {
          const pNorm = normalizeAccents(p);
          return en === pNorm || en.includes(pNorm) || pNorm.includes(en);
        });
      };
      if (esProvinciaPatch(matchRow.empresa || empresa)) newHgKg = -Math.abs(newHgKg);
    }

    const merged = { ...matchRow, hg_pct: newHgPct, hg_kg: newHgKg };
    const { util_oper_kg, util_oper_importe, resultado_final_kg, resultado_final_importe } = recalcularUtilYResultado(merged);

    await client.query(
      `UPDATE igf.compromiso_lines SET
         hg_pct = $1, hg_kg = $2,
         util_oper_kg = $3, util_oper_importe = $4,
         resultado_final_kg = $5, resultado_final_importe = $6
       WHERE version_id = $7 AND empresa = $8`,
      [
        newHgPct,
        newHgKg,
        util_oper_kg,
        util_oper_importe,
        resultado_final_kg,
        resultado_final_importe,
        versionId,
        (matchRow.empresa || "").trim(),
      ]
    );
    res.json({ ok: true, empresa: (matchRow.empresa || "").trim(), year, month, util_oper_importe, resultado_final_importe });
  } catch (e) {
    console.error("[Dashboard IGF Forecast PATCH]", e);
    res.status(500).json({ error: e.message });
  } finally {
    client.release();
  }
});

app.get("/api/folios/:id/media", dashboardAuthMiddleware, dashboardBlockGVFoliosMiddleware, async (req, res) => {
  const folioId = parseInt(req.params.id, 10);
  if (!Number.isFinite(folioId)) return res.status(400).json({ error: "id inválido" });
  const client = await pool.connect();
  try {
    const folio = await getFolioById(client, folioId);
    if (!folio) return res.status(404).json({ error: "Folio no encontrado" });
    const esZPMedia = (req.dashboardAuth.role && String(req.dashboardAuth.role).toUpperCase()) === "ZP";
    const esADMedia = (req.dashboardAuth.role && String(req.dashboardAuth.role).toUpperCase()) === "AD";
    if (folio.solo_zp_ad && !authCanVerFoliosSoloZpAd(req.dashboardAuth)) return res.status(404).json({ error: "Folio no encontrado" });
    if ((req.dashboardAuth.role === "GG" || req.dashboardAuth.role === "GA") && req.dashboardAuth.plantas_permitidas && req.dashboardAuth.plantas_permitidas.length > 0) {
      if (!folio.planta_id || !req.dashboardAuth.plantas_permitidas.includes(folio.planta_id)) {
        return res.status(403).json({ error: "Sin permiso para este folio" });
      }
    }
    const items = await listFolioArchivosByFolioId(client, folioId, 50);
    res.json({
      folio_id: folioId,
      numero_folio: folio.numero_folio,
      items: (items || []).map((it) => ({
        ...it,
        monto: it.monto != null ? Number(it.monto) : null,
      })),
    });
  } catch (e) {
    console.error("[Dashboard media]", e);
    res.status(500).json({ error: e.message });
  } finally {
    client.release();
  }
});

