app.get("/api/folios/:id/documento-gastos", dashboardAuthMiddleware, dashboardBlockGVFoliosMiddleware, async (req, res) => {
  const folioId = parseInt(req.params.id, 10);
  if (!Number.isFinite(folioId)) return res.status(400).json({ error: "id inválido" });
  const format = (req.query.format || "html").toLowerCase();
  const includeCotizacion = String(req.query.include_cotizacion || "0") === "1";
  const client = await pool.connect();
  try {
    const r = await client.query(
      `SELECT f.id, f.planta_id, f.solo_zp_ad, f.numero_folio, f.folio_codigo, f.beneficiario, f.concepto, f.importe, f.detalle_lineas, f.creado_en, f.mes_cargo,
              p.nombre AS planta_nombre, p.clave AS planta_clave
       FROM public.folios f
       LEFT JOIN public.plantas p ON p.id = f.planta_id
       WHERE f.id = $1`,
      [folioId]
    );
    const folio = r.rows[0] || null;
    if (!folio) return res.status(404).json({ error: "Folio no encontrado" });
    const esZPDoc = (req.dashboardAuth.role && String(req.dashboardAuth.role).toUpperCase()) === "ZP";
    const esADDoc = (req.dashboardAuth.role && String(req.dashboardAuth.role).toUpperCase()) === "AD";
    if (folio.solo_zp_ad && !authCanVerFoliosSoloZpAd(req.dashboardAuth)) return res.status(404).json({ error: "Folio no encontrado" });
    if ((req.dashboardAuth.role === "GG" || req.dashboardAuth.role === "GA") && req.dashboardAuth.plantas_permitidas?.length > 0) {
      const folioPlantaId = folio.planta_id != null ? folio.planta_id : null;
      if (folioPlantaId == null || !req.dashboardAuth.plantas_permitidas.includes(folioPlantaId)) {
        return res.status(403).json({ error: "Sin permiso para este folio" });
      }
    }
    const archivos = await listFolioArchivosByFolioId(client, folioId, 20);
    const tieneCotizacion = archivos.some((a) => (a.tipo || "").toUpperCase() === "COTIZACION");
    if (!tieneCotizacion) return res.status(400).json({ error: "El folio no tiene cotización; no se puede imprimir." });
    const cotizacionRow = archivos.find((a) => (a.tipo || "").toUpperCase() === "COTIZACION");
    const fechasDelAl = formatFechasDelAl(folio.mes_cargo);
    const fechaSolicitud = folio.creado_en
      ? new Date(folio.creado_en).toLocaleDateString("es-MX", { day: "numeric", month: "long", year: "numeric" })
      : "—";
    const plantaDisplay = [folio.planta_clave, folio.planta_nombre].filter(Boolean).join(" - ") || "—";
    const lineasDoc = getFolioLineasFromRow(folio);
    const totalNum = lineasDoc.reduce((s, l) => s + (Number(l.importe) || 0), 0);
    const importeStr = totalNum.toLocaleString("es-MX", { minimumFractionDigits: 2, maximumFractionDigits: 2 });
    const esc = (s) => String(s || "").replace(/</g, "&lt;");
    const minRows = Math.max(3, lineasDoc.length);
    const rowsHtml = Array.from({ length: minRows }, (_, i) => {
      const L = lineasDoc[i];
      if (!L) return `<tr><td>${i + 1}</td><td></td><td></td><td></td></tr>`;
      const impL = Number(L.importe).toLocaleString("es-MX", { minimumFractionDigits: 2, maximumFractionDigits: 2 });
      return `<tr><td>${i + 1}</td><td>${esc(L.beneficiario)}</td><td>${esc(L.concepto)}</td><td>$ ${impL}</td></tr>`;
    }).join("\n            ");

    if (format === "html") {
      const html = `<!DOCTYPE html><html lang="es"><head><meta charset="utf-8"><title>Gastos Extraordinarios - ${folio.numero_folio}</title><style>
        body{font-family:system-ui,sans-serif;max-width:800px;margin:1rem auto;padding:1rem;font-size:12px;}
        h1{text-align:center;font-size:18px;margin:0 0 0.25rem 0;}
        .subtitle{text-align:center;font-size:14px;margin:0 0 1rem 0;}
        .meta{display:flex;justify-content:space-between;margin-bottom:1rem;}
        .plant-folio{text-align:right;font-weight:bold;}
        table{width:100%;border-collapse:collapse;margin:1rem 0;}
        th,td{border:1px solid #333;padding:6px 8px;text-align:left;}
        th{background:#eee;}
        .total{text-align:right;font-weight:bold;margin-top:0.5rem;}
        .firmas{display:grid;grid-template-columns:1fr 1fr 1fr;gap:1rem;margin-top:2rem;font-size:11px;}
        .firma-col p{margin:0.25rem 0;}
      </style></head><body>
        <h1>GASTOS EXTRAORDINARIOS</h1>
        <p class="subtitle">APOYOS</p>
        <div class="meta">
          <div>FECHAS DEL: ${fechasDelAl}<br>FECHA DE SOLICITUD: ${fechaSolicitud}</div>
          <div class="plant-folio">${plantaDisplay}<br>FOLIO - ${(folio.numero_folio || "").trim() || folioId}</div>
        </div>
        <table>
          <thead><tr><th>SOLICITUD</th><th>BENEFICIARIO</th><th>CONCEPTO</th><th>IMPORTE</th></tr></thead>
          <tbody>
            ${rowsHtml}
          </tbody>
        </table>
        <div class="total">TOTAL &nbsp; $ ${importeStr}</div>
        <div class="firmas">
          <div class="firma-col"><p>CF. DAMIAN DIAZ LOPEZ.</p><p>COORD. ADMON Y FINANZAS ZONA PROVINCIA</p><p>LIC. ALFREDO GONZÁLEZ R.</p><p>DIRECTOR DE ZONA</p><p>LIC. LEONEL REQUENES R.</p><p>TITULAR TESORERÍA</p></div>
          <div class="firma-col"><p>CP. ARMANDO GARZA HDEZ.</p><p>COORD. FINANZAS E INVERSIONES DE ZONA</p><p>ING. LUIS ROGELIO ZARAGOZA A</p><p>DIRECTOR ZONA PROVINCIA</p><p>C.P. FEDERICO ROBLES N.</p><p>DIRECTOR DE FINANZAS</p></div>
          <div class="firma-col"><p>OBSERVACIONES:</p><p style="border-bottom:1px solid #333;min-height:1.5em;"></p><p>FECHA DE PAGO:</p><p style="border-bottom:1px solid #333;"></p><p>CHEQUE:</p><p>$</p><p>CHEQUE:</p><p>$</p></div>
        </div>
      </body></html>`;
      res.setHeader("Content-Type", "text/html; charset=utf-8");
      return res.send(html);
    }

    if (format === "pdf") {
      const pdfDoc = await PDFDocument.create();
      const page = pdfDoc.addPage([612, 792]);
      const font = await pdfDoc.embedFont(StandardFonts.Helvetica);
      const fontBold = await pdfDoc.embedFont(StandardFonts.HelveticaBold);
      let y = 750;
      const line = (text, size = 10, bold = false) => {
        const f = bold ? fontBold : font;
        page.drawText(text, { x: 50, y, size, font: f });
        y -= size + 4;
      };
      line("GASTOS EXTRAORDINARIOS", 16, true);
      line("APOYOS", 12);
      y -= 8;
      line(`FECHAS DEL: ${fechasDelAl}`, 10);
      line(`FECHA DE SOLICITUD: ${fechaSolicitud}`, 10);
      page.drawText(`${plantaDisplay}  |  FOLIO - ${folio.numero_folio}`, { x: 350, y: y + 24, size: 10, font: fontBold });
      y -= 20;
      line("SOLICITUD   BENEFICIARIO   CONCEPTO   IMPORTE", 9, true);
      lineasDoc.forEach((L, i) => {
        const ben = String(L.beneficiario || "").substring(0, 28);
        const con = String(L.concepto || "").substring(0, 40);
        const impL = Number(L.importe || 0).toLocaleString("es-MX", { minimumFractionDigits: 2, maximumFractionDigits: 2 });
        line(`${i + 1}   ${ben}   ${con}   $ ${impL}`, 9);
      });
      y -= 12;
      line(`TOTAL   $ ${importeStr}`, 10, true);
      y -= 30;
      line("CF. DAMIAN DIAZ LOPEZ.  COORD. ADMON Y FINANZAS ZONA PROVINCIA", 8);
      line("LIC. ALFREDO GONZÁLEZ R.  DIRECTOR DE ZONA", 8);
      line("CP. ARMANDO GARZA HDEZ.  COORD. FINANZAS E INVERSIONES DE ZONA", 8);
      line("ING. LUIS ROGELIO ZARAGOZA A  DIRECTOR ZONA PROVINCIA", 8);
      line("C.P. FEDERICO ROBLES N.  DIRECTOR DE FINANZAS", 8);
      line("LIC. LEONEL REQUENES R.  TITULAR TESORERÍA", 8);

      if (includeCotizacion && cotizacionRow && cotizacionRow.s3_key && s3Enabled) {
        try {
          const cotizacionBuf = await getBufferFromS3(cotizacionRow.s3_key);
          const cotizacionPdf = await PDFDocument.load(cotizacionBuf);
          const paginas = await pdfDoc.copyPages(cotizacionPdf, cotizacionPdf.getPageIndices());
          paginas.forEach((p) => pdfDoc.addPage(p));
        } catch (e) {
          console.warn("[documento-gastos] No se pudo adjuntar cotización:", e.message);
        }
      }

      const pdfBytes = await pdfDoc.save();
      res.setHeader("Content-Type", "application/pdf");
      res.setHeader("Content-Disposition", `attachment; filename="Gastos-Extraordinarios-${(folio.numero_folio || folioId).replace(/\s/g, "-")}.pdf"`);
      return res.send(Buffer.from(pdfBytes));
    }

    return res.status(400).json({ error: "format debe ser html o pdf" });
  } catch (e) {
    console.error("[documento-gastos]", e);
    res.status(500).json({ error: e.message || "Error al generar documento" });
  } finally {
    client.release();
  }
});

/** Documento "Solo formato del folio": PDF generado con plantilla S3 (FOLIO_TEMPLATE_S3_KEY) rellenada con datos del folio. Para Imprimir/Descargar en dashboard. */
app.get("/api/folios/:id/documento-folio", dashboardAuthMiddleware, dashboardBlockGVFoliosMiddleware, async (req, res) => {
  const folioId = parseInt(req.params.id, 10);
  if (!Number.isFinite(folioId)) return res.status(400).json({ error: "id inválido" });
  const client = await pool.connect();
  try {
    const r = await client.query(
      `SELECT f.id, f.planta_id, f.solo_zp_ad, f.numero_folio, f.folio_codigo, f.beneficiario, f.concepto, f.importe, f.detalle_lineas, f.creado_en, f.mes_cargo,
              f.categoria, f.subcategoria,
              p.nombre AS planta_nombre, p.clave AS planta_clave,
              pr.codigo AS proyecto_codigo, pr.nombre AS proyecto_nombre
       FROM public.folios f
       LEFT JOIN public.plantas p ON p.id = f.planta_id
       LEFT JOIN public.proyectos pr ON pr.id = f.proyecto_id
       WHERE f.id = $1`,
      [folioId]
    );
    const folio = r.rows[0] || null;
    if (!folio) return res.status(404).json({ error: "Folio no encontrado" });
    const esZPDoc = (req.dashboardAuth.role && String(req.dashboardAuth.role).toUpperCase()) === "ZP";
    const esADDoc = (req.dashboardAuth.role && String(req.dashboardAuth.role).toUpperCase()) === "AD";
    if (folio.solo_zp_ad && !authCanVerFoliosSoloZpAd(req.dashboardAuth)) return res.status(404).json({ error: "Folio no encontrado" });
    if ((req.dashboardAuth.role === "GG" || req.dashboardAuth.role === "GA") && req.dashboardAuth.plantas_permitidas?.length > 0) {
      const folioPlantaId = folio.planta_id != null ? folio.planta_id : null;
      if (folioPlantaId == null || !req.dashboardAuth.plantas_permitidas.includes(folioPlantaId)) {
        return res.status(403).json({ error: "Sin permiso para este folio" });
      }
    }

    const numeroFolio = (folio.numero_folio || folio.folio_codigo || `F-${folioId}`).toString().trim();
    const lineasFolio = getFolioLineasFromRow(folio).slice(0, FOLIO_LINEAS_MAX);
    const beneficiario = (lineasFolio[0] && lineasFolio[0].beneficiario) || (folio.beneficiario || "").toString().trim() || "—";
    const concepto = (lineasFolio[0] && lineasFolio[0].concepto) || (folio.concepto || "").toString().trim() || "—";
    const totalNum = lineasFolio.reduce((s, l) => s + (Number(l.importe) || 0), 0);
    const importeNum = totalNum || (folio.importe != null ? Number(folio.importe) : 0);
    const importeStr = Number(importeNum).toLocaleString("es-MX", { minimumFractionDigits: 2, maximumFractionDigits: 2 });
    const PLANTA_CODIGO_A_NOMBRE = { E7: "PUEBLA", E8: "TEHUACAN", E9: "ACAPULCO", E10: "ACAPULCO", E12: "QUERETARO", E13: "SAN LUIS", E15: "MORELOS" };
    const PLANTA_NOMBRE_A_CODIGO = { PUEBLA: "E7", TEHUACAN: "E8", ACAPULCO: "E9", QUERETARO: "E12", SANLUIS: "E13", "SAN LUIS": "E13", MORELOS: "E15" };
    const claveNorm = String(folio.planta_clave || "").trim().toUpperCase();
    const nombreNorm = (s) => String(s || "").trim().toUpperCase().replace(/\s+/g, " ").normalize("NFD").replace(/[\u0300-\u036f]/g, "");
    let codigoPlanta = (claveNorm && PLANTA_CODIGO_A_NOMBRE[claveNorm]) ? claveNorm : null;
    if (!codigoPlanta) {
      const claveSinAcentos = nombreNorm(folio.planta_clave).replace(/\s/g, "");
      const nombreSinAcentos = nombreNorm(folio.planta_nombre).replace(/\s/g, "");
      codigoPlanta = PLANTA_NOMBRE_A_CODIGO[claveSinAcentos] || PLANTA_NOMBRE_A_CODIGO[nombreSinAcentos] || PLANTA_NOMBRE_A_CODIGO[claveNorm] || PLANTA_NOMBRE_A_CODIGO[nombreNorm(folio.planta_nombre)];
    }
    const nombreDisplay = codigoPlanta ? PLANTA_CODIGO_A_NOMBRE[codigoPlanta] : "";
    const plantaDisplay = (codigoPlanta && nombreDisplay) ? `${codigoPlanta}-${nombreDisplay}` : (claveNorm || String(folio.planta_nombre || "").trim().toUpperCase() || "—");
    const fechaSolicitud = folio.creado_en
      ? new Date(folio.creado_en).toLocaleDateString("es-MX", { day: "numeric", month: "long", year: "numeric" })
      : "—";
    const fechasDelAl = formatFechasDelAl(folio.mes_cargo);
    const mesCargoLabel = formatMesCargoLabel(folio.mes_cargo);
    const categoriaDisplay = (folio.categoria || "").toString().trim() || "—";
    const subcategoriaDisplay = (folio.subcategoria || "").toString().trim() || "—";
    const proyectoDisplay = [folio.proyecto_codigo, folio.proyecto_nombre].filter(Boolean).join(" - ") || "—";

    const s3TemplateKeyDefault = (process.env.FOLIO_TEMPLATE_S3_KEY || "").trim();
    const s3TemplateKeyAcapulco = (process.env.FOLIO_TEMPLATE_S3_KEY_ACAPULCO || "").trim();
    // Soporte para env var nombrada en tu UI: FOLIO_MOR_TEMPLATE_S3_KEY
    const s3TemplateKeyMorelos = (process.env.FOLIO_TEMPLATE_S3_KEY_MORELOS || process.env.FOLIO_MOR_TEMPLATE_S3_KEY || "").trim();
    // Soporte para env var nombrada en tu UI: FOLIO_PUE_TEMPLATE_S3_KEY
    const s3TemplateKeyPueblaRaw = (process.env.FOLIO_TEMPLATE_S3_KEY_PUEBLA || process.env.FOLIO_PUE_TEMPLATE_S3_KEY || "").trim();
    // Soporte para env var nombrada en tu UI: FOLIO_TEH_TEMPLATE_S3_KEY
    const s3TemplateKeyTehuacanRaw = (process.env.FOLIO_TEMPLATE_S3_KEY_TEHUACAN || process.env.FOLIO_TEH_TEMPLATE_S3_KEY || "").trim();
    // Soporte env UI: FOLIO_QUE_TEMPLATE_S3_KEY → Plantillas/formato-folio-Queretaro.pdf
    const s3TemplateKeyQueretaroRaw = (process.env.FOLIO_TEMPLATE_S3_KEY_QUERETARO || process.env.FOLIO_QUE_TEMPLATE_S3_KEY || "").trim();
    // Soporte env UI: FOLIO_SAN_TEMPLATE_S3_KEY → Plantillas/formato-folio-San.pdf (San Luis E13)
    const s3TemplateKeySanLuisRaw = (process.env.FOLIO_TEMPLATE_S3_KEY_SAN_LUIS || process.env.FOLIO_SAN_TEMPLATE_S3_KEY || "").trim();
    const normalizeTemplateKey = (key) => {
      const k = (key || "").trim();
      if (!k) return "";
      return /\.pdf$/i.test(k) ? k : `${k}.pdf`;
    };
    const s3TemplateKeyPuebla = normalizeTemplateKey(s3TemplateKeyPueblaRaw);
    const s3TemplateKeyTehuacan = normalizeTemplateKey(s3TemplateKeyTehuacanRaw);
    const s3TemplateKeyQueretaro = normalizeTemplateKey(s3TemplateKeyQueretaroRaw);
    const s3TemplateKeySanLuis = normalizeTemplateKey(s3TemplateKeySanLuisRaw);
    const isAcapulcoPlant = (codigoPlanta === "E9" || codigoPlanta === "E10");
    const isMorelosPlant = (codigoPlanta === "E15");
    const isPueblaPlant = (codigoPlanta === "E7");
    const isTehuacanPlant = (codigoPlanta === "E8");
    const isQueretaroPlant = (codigoPlanta === "E12");
    const isSanLuisPlant = (codigoPlanta === "E13");
    let s3TemplateKey = s3TemplateKeyDefault;

    if (isAcapulcoPlant) {
      if (s3TemplateKeyAcapulco) {
        s3TemplateKey = s3TemplateKeyAcapulco;
      } else {
        // Derivación automática si el default se llama "formato-folio.pdf"
        // y el Acapulco se llama "formato-folio-Acapulco.pdf".
        const derived = s3TemplateKeyDefault.replace(/formato-folio\.pdf$/i, "formato-folio-Acapulco.pdf");
        if (derived && derived !== s3TemplateKeyDefault) s3TemplateKey = derived;
      }
    } else if (isMorelosPlant) {
      if (s3TemplateKeyMorelos) {
        s3TemplateKey = s3TemplateKeyMorelos;
      } else {
        // Derivación automática si el default se llama "formato-folio.pdf"
        // y el Morelos se llama "formato-folio-Morelos.pdf".
        const derived = s3TemplateKeyDefault.replace(/formato-folio\.pdf$/i, "formato-folio-Morelos.pdf");
        if (derived && derived !== s3TemplateKeyDefault) s3TemplateKey = derived;
      }
    } else if (isPueblaPlant) {
      if (s3TemplateKeyPuebla) {
        s3TemplateKey = s3TemplateKeyPuebla;
      } else {
        // Derivación automática si el default se llama "formato-folio.pdf"
        // y el Puebla se llama "formato-folio-Puebla.pdf".
        const derived = s3TemplateKeyDefault.replace(/formato-folio\.pdf$/i, "formato-folio-Puebla.pdf");
        if (derived && derived !== s3TemplateKeyDefault) s3TemplateKey = derived;
      }
    } else if (isTehuacanPlant) {
      if (s3TemplateKeyTehuacan) {
        s3TemplateKey = s3TemplateKeyTehuacan;
      } else {
        // Derivación automática si el default se llama "formato-folio.pdf"
        // y el Tehuacan se llama "formato-folio-Tehuacan.pdf".
        const derived = s3TemplateKeyDefault.replace(/formato-folio\.pdf$/i, "formato-folio-Tehuacan.pdf");
        if (derived && derived !== s3TemplateKeyDefault) s3TemplateKey = derived;
      }
    } else if (isQueretaroPlant) {
      if (s3TemplateKeyQueretaro) {
        s3TemplateKey = s3TemplateKeyQueretaro;
      } else {
        const derived = s3TemplateKeyDefault.replace(/formato-folio\.pdf$/i, "formato-folio-Queretaro.pdf");
        if (derived && derived !== s3TemplateKeyDefault) s3TemplateKey = derived;
      }
    } else if (isSanLuisPlant) {
      if (s3TemplateKeySanLuis) {
        s3TemplateKey = s3TemplateKeySanLuis;
      } else {
        const derived = s3TemplateKeyDefault.replace(/formato-folio\.pdf$/i, "formato-folio-San.pdf");
        if (derived && derived !== s3TemplateKeyDefault) s3TemplateKey = derived;
      }
    }
    let pdfBytes = null;

    if (s3Enabled && s3TemplateKey) {
      try {
        let templateBuf = null;
        try {
          templateBuf = await getBufferFromS3(s3TemplateKey);
        } catch (e) {
          // Si para Acapulco derivamos una key diferente y falla (no existe),
          // regresamos al default para no romper la generación.
          if ((isAcapulcoPlant || isMorelosPlant || isPueblaPlant || isTehuacanPlant || isQueretaroPlant || isSanLuisPlant) && s3TemplateKey !== s3TemplateKeyDefault) {
            console.warn("[documento-folio] No se pudo cargar plantilla (override), intentando default:", {
              overrideKey: s3TemplateKey,
              defaultKey: s3TemplateKeyDefault,
              isAcapulcoPlant,
              isMorelosPlant,
              isPueblaPlant,
              isTehuacanPlant,
              isQueretaroPlant,
              isSanLuisPlant,
              message: e?.message,
            });
            templateBuf = await getBufferFromS3(s3TemplateKeyDefault);
          } else {
            throw e;
          }
        }
        const pdfDoc = await PDFDocument.load(templateBuf, { ignoreEncryption: true });
        const pages = pdfDoc.getPages();
        if (!pages || pages.length === 0) throw new Error("La plantilla no contiene páginas");
        const page = pages[0];
        const font = await pdfDoc.embedFont(StandardFonts.Helvetica);
        const fontBold = await pdfDoc.embedFont(StandardFonts.HelveticaBold);

        let usedForm = false;
        try {
          const form = pdfDoc.getForm();
          const fields = form.getFields ? form.getFields() : [];
          for (const field of fields) {
            const name = (field.getName && field.getName()) || "";
            const n = name.toLowerCase();
            let val = null;
            if (n.includes("folio") || n.includes("numero")) val = numeroFolio;
            else if (n.includes("beneficiario")) val = beneficiario;
            else if (n.includes("concepto")) val = concepto;
            else if (n.includes("importe")) val = importeStr;
            else if (n.includes("planta")) val = plantaDisplay;
            else if (n.includes("fecha")) val = fechaSolicitud;
            else if (n.includes("mes") && n.includes("cargo")) val = mesCargoLabel;
            else if (n.includes("categoria") && !n.includes("sub")) val = categoriaDisplay;
            else if (n.includes("subcategoria")) val = subcategoriaDisplay;
            else if (n.includes("proyecto")) val = proyectoDisplay;
            if (val != null && val !== "") {
              try {
                const tf = form.getTextField(name);
                if (tf) { tf.setText(String(val)); usedForm = true; }
              } catch (_) {}
            }
          }
          if (usedForm && form.flatten) form.flatten();
        } catch (_) {}

        if (!usedForm) {
          const conceptoXStart = 295;
          const conceptoXEnd = 550;
          const conceptoMaxWidthPoints = conceptoXEnd - conceptoXStart;
          const POS = {
            folio: { x: 600, y: 580, size: 12 },
            // Limitar beneficiario al rango X:147..X:280 para evitar traslape con concepto.
            beneficiario: { x: 145, y: 456.5, size: 8 },
            concepto: { x: conceptoXStart, y: 456.5, size: 8 },
            importe: { x: 610, y: 456.5, size: 9 },
            planta: { x: 100, y: 580, size: 16 },
            fecha: { x: 381, y: 580, size: 9 },
            categoria: { x: 50, y: 540, size: 15 },
            mes_cargo: { x: 381, y: 540, size: 15 },
            subcategoria: { x: 50, y: 520, size: 10 },
            proyecto: { x: 600, y: 540, size: 9 },
          };
          const draw = (text, x, y, size = 9, bold = false, maxLen = 120) => {
            const safe = String(text ?? "").trim().substring(0, maxLen);
            if (!safe) return;
            page.drawText(safe, { x, y, size, font: bold ? fontBold : font });
          };
          const wrapConcepto = (text, size) => {
            const maxChars = Math.max(15, Math.floor(conceptoMaxWidthPoints / (size * 0.5)));
            const words = String(text || "").trim().split(/\s+/).filter(Boolean);
            if (words.length === 0) return [""];
            const lines = [];
            let current = "";
            for (const w of words) {
              const next = current ? current + " " + w : w;
              if (next.length <= maxChars) current = next;
              else {
                if (current) lines.push(current);
                current = w.length <= maxChars ? w : w.substring(0, maxChars);
              }
            }
            if (current) lines.push(current);
            return lines.length ? lines : [""];
          };

          const wrapBeneficiario = (text, size) => {
            const maxWidthPoints = 280 - POS.beneficiario.x;
            const maxChars = Math.max(10, Math.floor(maxWidthPoints / (size * 0.5)));
            const words = String(text || "").trim().split(/\s+/).filter(Boolean);
            if (words.length === 0) return [""];
            const lines = [];
            let current = "";
            for (const w of words) {
              const next = current ? current + " " + w : w;
              if (next.length <= maxChars) current = next;
              else {
                if (current) lines.push(current);
                current = w.length <= maxChars ? w : w.substring(0, maxChars);
              }
            }
            if (current) lines.push(current);
            return lines.length ? lines : [""];
          };

          draw(`FOLIO - ${numeroFolio}`, POS.folio.x, POS.folio.y, POS.folio.size, true);
          const ROW_H = 21.5;
          const multi = lineasFolio.length > 1;
          lineasFolio.forEach((L, idx) => {
            const yRow = POS.beneficiario.y - idx * ROW_H;
            const benTxt = String(L.beneficiario || "").trim() || "—";
            const conTxt = String(L.concepto || "").trim() || "—";
            const impTxt = Number(L.importe || 0).toLocaleString("es-MX", { minimumFractionDigits: 2, maximumFractionDigits: 2 });
            if (multi) {
              draw(benTxt, POS.beneficiario.x, yRow, POS.beneficiario.size, false, 40);
              draw(conTxt, POS.concepto.x, yRow, POS.concepto.size, false, 55);
              draw(`$ ${impTxt}`, POS.importe.x, yRow, POS.importe.size);
            } else {
              const beneficiarioLines = wrapBeneficiario(benTxt, POS.beneficiario.size);
              beneficiarioLines.forEach((line, i) => {
                draw(line, POS.beneficiario.x, yRow - i * POS.beneficiario.size * 1.2, POS.beneficiario.size, false, 500);
              });
              const conceptoLines = wrapConcepto(conTxt, POS.concepto.size);
              let conceptoY = yRow;
              conceptoLines.forEach((line) => {
                draw(line, POS.concepto.x, conceptoY, POS.concepto.size, false, 500);
                conceptoY -= POS.concepto.size * 1.2;
              });
              draw(`$ ${impTxt}`, POS.importe.x, yRow, POS.importe.size);
            }
          });
          // TOTAL (caja inferior del formato): suma de importes
          const totalY = POS.importe.y - FOLIO_LINEAS_MAX * ROW_H - 6;
          draw(`$ ${importeStr}`, POS.importe.x, totalY, POS.importe.size, true);
          draw(plantaDisplay, POS.planta.x, POS.planta.y, POS.planta.size);
          draw(fechaSolicitud, POS.fecha.x, POS.fecha.y, POS.fecha.size);
          draw(categoriaDisplay, POS.categoria.x, POS.categoria.y, POS.categoria.size);
          draw(mesCargoLabel, POS.mes_cargo.x, POS.mes_cargo.y, POS.mes_cargo.size);
          draw(subcategoriaDisplay, POS.subcategoria.x, POS.subcategoria.y, POS.subcategoria.size);
          draw(proyectoDisplay, POS.proyecto.x, POS.proyecto.y, POS.proyecto.size);
        }

        pdfBytes = await pdfDoc.save();
      } catch (e) {
        console.warn("[documento-folio] Plantilla S3:", e.message);
      }
    }

    if (!pdfBytes) {
      const pdfDoc = await PDFDocument.create();
      const page = pdfDoc.addPage([612, 792]);
      const font = await pdfDoc.embedFont(StandardFonts.Helvetica);
      const fontBold = await pdfDoc.embedFont(StandardFonts.HelveticaBold);
      let y = 750;
      const line = (text, size = 10, bold = false) => {
        page.drawText(String(text ?? "").substring(0, 100), { x: 50, y, size, font: bold ? fontBold : font });
        y -= size + 4;
      };
      line("GASTOS EXTRAORDINARIOS - FORMATO FOLIO", 14, true);
      line(`FOLIO - ${numeroFolio}`, 12);
      line(`Planta: ${plantaDisplay}`, 10);
      line(`Fechas del: ${fechasDelAl}  |  Fecha solicitud: ${fechaSolicitud}`, 9);
      y -= 8;
      lineasFolio.forEach((L, i) => {
        const impL = Number(L.importe || 0).toLocaleString("es-MX", { minimumFractionDigits: 2, maximumFractionDigits: 2 });
        line(`${i + 1}. ${(L.beneficiario || "—").substring(0, 40)}`, 10);
        line(`   ${(L.concepto || "—").substring(0, 80)}  $ ${impL}`, 9);
      });
      line(`TOTAL: $ ${importeStr}`, 10, true);
      line(`Categoría: ${categoriaDisplay}  |  Subcategoría: ${subcategoriaDisplay}  |  Proyecto: ${proyectoDisplay}`, 9);
      pdfBytes = await pdfDoc.save();
    }

    res.setHeader("Content-Type", "application/pdf");
    res.setHeader("Content-Disposition", `attachment; filename="Formato-Folio-${(folio.numero_folio || folioId).toString().replace(/\s/g, "-")}.pdf"`);
    return res.send(Buffer.from(pdfBytes));
  } catch (e) {
    console.error("[documento-folio]", e);
    res.status(500).json({ error: e.message || "Error al generar documento" });
  } finally {
    client.release();
  }
});

/** Documento completo: Póliza (con datos) + Folio (gastos) + Cotización en un solo PDF. Requiere folio con cotización. */
app.get("/api/folios/:id/documento-completo", dashboardAuthMiddleware, dashboardBlockGVFoliosMiddleware, async (req, res) => {
  const folioId = parseInt(req.params.id, 10);
  if (!Number.isFinite(folioId)) return res.status(400).json({ error: "id inválido" });
  const format = (req.query.format || "pdf").toLowerCase();
  if (format !== "pdf") return res.status(400).json({ error: "Solo format=pdf" });
  const client = await pool.connect();
  try {
    const r = await client.query(
      `SELECT f.id, f.planta_id, f.solo_zp_ad, f.numero_folio, f.folio_codigo, f.beneficiario, f.concepto, f.importe, f.detalle_lineas, f.creado_en, f.mes_cargo, f.banco, f.cuenta_bancaria,
              p.nombre AS planta_nombre, p.clave AS planta_clave
       FROM public.folios f
       LEFT JOIN public.plantas p ON p.id = f.planta_id
       WHERE f.id = $1`,
      [folioId]
    );
    const folio = r.rows[0] || null;
    if (!folio) return res.status(404).json({ error: "Folio no encontrado" });
    const esZPDoc = (req.dashboardAuth.role && String(req.dashboardAuth.role).toUpperCase()) === "ZP";
    const esADDoc = (req.dashboardAuth.role && String(req.dashboardAuth.role).toUpperCase()) === "AD";
    if (folio.solo_zp_ad && !authCanVerFoliosSoloZpAd(req.dashboardAuth)) return res.status(404).json({ error: "Folio no encontrado" });
    if ((req.dashboardAuth.role === "GG" || req.dashboardAuth.role === "GA") && req.dashboardAuth.plantas_permitidas?.length > 0) {
      const folioPlantaId = folio.planta_id != null ? folio.planta_id : null;
      if (folioPlantaId == null || !req.dashboardAuth.plantas_permitidas.includes(folioPlantaId)) {
        return res.status(403).json({ error: "Sin permiso para este folio" });
      }
    }
    const archivos = await listFolioArchivosByFolioId(client, folioId, 20);
    const tieneCotizacion = archivos.some((a) => (a.tipo || "").toUpperCase() === "COTIZACION");
    if (!tieneCotizacion) return res.status(400).json({ error: "El folio no tiene cotización; no se puede generar el documento completo." });
    const cotizacionRow = archivos.find((a) => (a.tipo || "").toUpperCase() === "COTIZACION");
    const fechasDelAl = formatFechasDelAl(folio.mes_cargo);
    const fechaSolicitud = folio.creado_en
      ? new Date(folio.creado_en).toLocaleDateString("es-MX", { day: "numeric", month: "long", year: "numeric" })
      : "—";
    const plantaDisplay = [folio.planta_clave, folio.planta_nombre].filter(Boolean).join(" - ") || "—";
    const lineasDoc = getFolioLineasFromRow(folio);
    const totalNum = lineasDoc.reduce((s, l) => s + (Number(l.importe) || 0), 0);
    const importeStr = totalNum.toLocaleString("es-MX", { minimumFractionDigits: 2, maximumFractionDigits: 2 });

    // 1) Generar PDF Póliza (cuenta y numero_cheque opcionales por query, para impresión desde Director ZP)
    const cuentaPoliza = (req.query.cuenta != null && String(req.query.cuenta).trim() !== "") ? String(req.query.cuenta).trim() : null;
    const numeroChequePoliza = (req.query.numero_cheque != null && String(req.query.numero_cheque).trim() !== "") ? String(req.query.numero_cheque).trim() : null;
    const polizaBytes = await generatePolizaPdfBytes(folio, { cuenta: cuentaPoliza, numero_cheque: numeroChequePoliza });

    // 2) Generar PDF Gastos + cotización
    const pdfGastos = await PDFDocument.create();
    const pageG = pdfGastos.addPage([612, 792]);
    const fontG = await pdfGastos.embedFont(StandardFonts.Helvetica);
    const fontBoldG = await pdfGastos.embedFont(StandardFonts.HelveticaBold);
    let yG = 750;
    const lineG = (text, size = 10, bold = false) => { pageG.drawText(text, { x: 50, y: yG, size, font: bold ? fontBoldG : fontG }); yG -= size + 4; };
    lineG("GASTOS EXTRAORDINARIOS", 16, true); lineG("APOYOS", 12); yG -= 8;
    lineG(`FECHAS DEL: ${fechasDelAl}`, 10); lineG(`FECHA DE SOLICITUD: ${fechaSolicitud}`, 10);
    pageG.drawText(`${plantaDisplay}  |  FOLIO - ${folio.numero_folio}`, { x: 350, y: yG + 24, size: 10, font: fontBoldG }); yG -= 20;
    lineG("SOLICITUD   BENEFICIARIO   CONCEPTO   IMPORTE", 9, true);
    lineasDoc.forEach((L, i) => {
      const ben = String(L.beneficiario || "").substring(0, 28);
      const con = String(L.concepto || "").substring(0, 40);
      const impL = Number(L.importe || 0).toLocaleString("es-MX", { minimumFractionDigits: 2, maximumFractionDigits: 2 });
      lineG(`${i + 1}   ${ben}   ${con}   $ ${impL}`, 9);
    });
    yG -= 12;
    lineG(`TOTAL   $ ${importeStr}`, 10, true); yG -= 30;
    lineG("CF. DAMIAN DIAZ LOPEZ.  COORD. ADMON Y FINANZAS ZONA PROVINCIA", 8);
    lineG("LIC. ALFREDO GONZÁLEZ R.  DIRECTOR DE ZONA", 8);
    lineG("CP. ARMANDO GARZA HDEZ.  COORD. FINANZAS E INVERSIONES DE ZONA", 8);
    lineG("ING. LUIS ROGELIO ZARAGOZA A  DIRECTOR ZONA PROVINCIA", 8);
    lineG("C.P. FEDERICO ROBLES N.  DIRECTOR DE FINANZAS", 8);
    lineG("LIC. LEONEL REQUENES R.  TITULAR TESORERÍA", 8);
    if (cotizacionRow && cotizacionRow.s3_key && s3Enabled) {
      try {
        const cotizacionBuf = await getBufferFromS3(cotizacionRow.s3_key);
        const cotizacionPdf = await PDFDocument.load(cotizacionBuf);
        const paginas = await pdfGastos.copyPages(cotizacionPdf, cotizacionPdf.getPageIndices());
        paginas.forEach((p) => pdfGastos.addPage(p));
      } catch (e) {
        console.warn("[documento-completo] No se pudo adjuntar cotización:", e.message);
      }
    }
    const gastosBytes = await pdfGastos.save();

    // 3) Unir: primero póliza, luego gastos + cotización
    const mergedDoc = await PDFDocument.create();
    const polizaDoc = await PDFDocument.load(polizaBytes);
    const paginasPoliza = await mergedDoc.copyPages(polizaDoc, polizaDoc.getPageIndices());
    paginasPoliza.forEach((p) => mergedDoc.addPage(p));
    const gastosDoc = await PDFDocument.load(gastosBytes);
    const paginasGastos = await mergedDoc.copyPages(gastosDoc, gastosDoc.getPageIndices());
    paginasGastos.forEach((p) => mergedDoc.addPage(p));
    const finalBytes = await mergedDoc.save();

    res.setHeader("Content-Type", "application/pdf");
    res.setHeader("Content-Disposition", `attachment; filename="Documento-Completo-${(folio.numero_folio || folioId).replace(/\s/g, "-")}.pdf"`);
    return res.send(Buffer.from(finalBytes));
  } catch (e) {
    console.error("[documento-completo]", e);
    res.status(500).json({ error: e.message || "Error al generar documento completo" });
  } finally {
    client.release();
  }
});

/** Actualizar mes_cargo del folio (Aprobación Director ZP o carrito de compra). */
app.patch("/api/folios/:id", dashboardAuthMiddleware, dashboardBlockGVFoliosMiddleware, async (req, res) => {
  if (req.dashboardAuth.role === "GA") return res.status(403).json({ error: "GA solo puede ver e imprimir en el dashboard." });
  const folioId = parseInt(req.params.id, 10);
  if (!Number.isFinite(folioId)) return res.status(400).json({ error: "id inválido" });
  const mesCargo = (req.body.mes_cargo != null && req.body.mes_cargo !== "") ? String(req.body.mes_cargo).trim() : null;
  if (mesCargo !== null && !/^\d{4}-\d{2}$/.test(mesCargo)) return res.status(400).json({ error: "mes_cargo debe ser YYYY-MM" });
  const client = await pool.connect();
  try {
    const folio = await getFolioById(client, folioId);
    if (!folio) return res.status(404).json({ error: "Folio no encontrado" });
    const est = String(folio.estatus || "").toUpperCase();
    const enCarritoOCheque = ESTADOS_HASTA_CHEQUE.includes(est);
    const enAprobacionZp = est === ESTADOS.PENDIENTE_APROB_ZP;
    if (!enCarritoOCheque && !enAprobacionZp) {
      return res.status(400).json({ error: "Solo se puede editar el mes de cargo en Aprobación Director ZP, Carro, Cuenta de fondos o Cheque Generado." });
    }
    await client.query(`UPDATE public.folios SET mes_cargo = $1 WHERE id = $2`, [mesCargo, folioId]);
    const prevMes = folio.mes_cargo ? String(folio.mes_cargo).trim() : null;
    if (mesCargo !== prevMes) {
      const comentario = mesCargo
        ? `Mes de cargo ${prevMes ? `cambiado de ${prevMes} a` : "asignado:"} ${mesCargo}.`
        : `Mes de cargo eliminado${prevMes ? ` (antes: ${prevMes})` : ""}.`;
      await insertHistorial(
        client,
        folioId,
        folio.numero_folio,
        folio.folio_codigo,
        folio.estatus || "",
        comentario,
        null,
        req.dashboardAuth.role || null
      ).catch(() => {});
    }
    res.json({ ok: true, mes_cargo: mesCargo });
  } catch (e) {
    console.error("[Dashboard PATCH folio]", e);
    res.status(500).json({ error: e.message });
  } finally {
    client.release();
  }
});

