/** Avanzar folio: Carro → Cuenta de fondos → Cheque Generado. */
app.post("/api/folios/:id/avanzar-etapa", dashboardAuthMiddleware, dashboardBlockGVFoliosMiddleware, async (req, res) => {
  if (req.dashboardAuth.role === "CF_CDMX") return res.status(403).json({ error: "Contralor financiero CDMX solo puede ver el dashboard, no autorizar." });
  if (req.dashboardAuth.role === "GA") return res.status(403).json({ error: "GA solo puede ver e imprimir en el dashboard, no autorizar." });
  const folioId = parseInt(req.params.id, 10);
  if (!Number.isFinite(folioId)) return res.status(400).json({ error: "id inválido" });
  const destino = String(req.body.destino || "").trim().toUpperCase();
  if (![ESTADOS.CUENTA_FONDOS, ESTADOS.CHEQUE_GENERADO].includes(destino)) {
    return res.status(400).json({ error: "destino debe ser CUENTA_FONDOS o CHEQUE_GENERADO" });
  }
  const client = await pool.connect();
  try {
    const folio = await getFolioById(client, folioId);
    if (!folio) return res.status(404).json({ error: "Folio no encontrado" });
    if ((req.dashboardAuth.role === "GG" || req.dashboardAuth.role === "GA" || req.dashboardAuth.role === "AD") && req.dashboardAuth.plantas_permitidas?.length > 0) {
      if (!folio.planta_id || !req.dashboardAuth.plantas_permitidas.includes(folio.planta_id)) {
        return res.status(403).json({ error: "Sin permiso para modificar folios de esta planta" });
      }
    }
    const estatus = (folio.estatus || "").trim().toUpperCase();
    const rol = req.dashboardAuth.role || "Dashboard";
    if (destino === ESTADOS.CUENTA_FONDOS) {
      if (!ESTADOS_CARRO_COMPRA.includes(estatus)) {
        return res.status(400).json({ error: "Solo se puede pasar a Cuenta de fondos desde Carro de compra." });
      }
    } else if (destino === ESTADOS.CHEQUE_GENERADO) {
      if (estatus !== ESTADOS.CUENTA_FONDOS) {
        return res.status(400).json({ error: "Solo se puede pasar a Cheque Generado desde Cuenta de fondos." });
      }
    }
    const labelDestino = getEtapaVisibleLabel(destino);
    await updateFolioEstatus(client, folioId, destino, { estatus_anterior: estatus });
    await insertHistorial(
      client,
      folioId,
      folio.numero_folio,
      folio.folio_codigo,
      destino,
      `Avanzado a ${labelDestino} desde dashboard.`,
      null,
      rol
    );
    return res.json({ ok: true, estatus: destino });
  } catch (e) {
    console.error("[Dashboard folio avanzar-etapa]", e);
    res.status(500).json({ error: e.message });
  } finally {
    client.release();
  }
});

/**
 * Mover folio a cualquier etapa visual (drag & drop). Solo AD y Director ZP.
 * Sin validar documentos/condiciones: fuerza el estatus canónico de la columna destino.
 */
app.post("/api/folios/:id/mover-etapa", dashboardAuthMiddleware, dashboardBlockGVFoliosMiddleware, async (req, res) => {
  const role = (req.dashboardAuth.role && String(req.dashboardAuth.role).toUpperCase()) || "";
  const rolNombre = (req.dashboardAuth.rol_nombre && String(req.dashboardAuth.rol_nombre)) || "";
  const esAD = role === "AD";
  const esZP = role === "ZP" || isDirectorZPForDashboard(role, rolNombre);
  const puedeMover =
    req.dashboardAuth.permisos && typeof req.dashboardAuth.permisos === "object"
      ? usuarioPermisos.authHasPermiso(req.dashboardAuth, "acceso_mover_folio_arrastre")
      : esAD || esZP;
  if (!puedeMover) {
    return res.status(403).json({ error: "Solo Asistente de dirección o Director ZP pueden arrastrar folios entre etapas." });
  }
  const folioId = parseInt(req.params.id, 10);
  if (!Number.isFinite(folioId)) return res.status(400).json({ error: "id inválido" });
  const etapa = String(req.body.etapa || "").trim().toUpperCase();
  if (!ETAPAS_VISUAL_ORDER.includes(etapa)) {
    return res.status(400).json({ error: "etapa no válida" });
  }
  const nuevoEstatus = etapaVisualToEstatusDestino(etapa);
  if (!nuevoEstatus) return res.status(400).json({ error: "No se pudo mapear la etapa destino" });

  const client = await pool.connect();
  try {
    const folio = await getFolioById(client, folioId);
    if (!folio) return res.status(404).json({ error: "Folio no encontrado" });
    if (esAD && req.dashboardAuth.plantas_permitidas?.length > 0) {
      if (!folio.planta_id || !req.dashboardAuth.plantas_permitidas.includes(folio.planta_id)) {
        return res.status(403).json({ error: "Sin permiso para modificar folios de esta planta" });
      }
    }
    const estatus = (folio.estatus || "").trim().toUpperCase();
    const etapaActual = estatusToEtapaVisual(estatus);
    if (etapaActual === etapa && estatus === nuevoEstatus) {
      return res.json({ ok: true, estatus, etapa, unchanged: true });
    }
    const labelDestino = (ETAPA_VISIBLE[etapa] && ETAPA_VISIBLE[etapa].label) || etapa;
    await updateFolioEstatus(client, folioId, nuevoEstatus, { estatus_anterior: estatus });
    await insertHistorial(
      client,
      folioId,
      folio.numero_folio,
      folio.folio_codigo,
      nuevoEstatus,
      `Movido manualmente a «${labelDestino}» (arrastre dashboard). Sin validar condiciones.`,
      null,
      role || "Dashboard"
    );
    return res.json({ ok: true, estatus: nuevoEstatus, etapa });
  } catch (e) {
    console.error("[Dashboard folio mover-etapa]", e);
    res.status(500).json({ error: e.message });
  } finally {
    client.release();
  }
});

/** Asistente de dirección: subir póliza (comprobante) en Cheque Generado; pasa a Depósito y cierre. */
app.post("/api/folios/:id/poliza", dashboardAuthMiddleware, dashboardBlockGVFoliosMiddleware, async (req, res) => {
  const folioId = parseInt(req.params.id, 10);
  if (!Number.isFinite(folioId)) return res.status(400).json({ error: "id inválido" });
  const role = (req.dashboardAuth.role && String(req.dashboardAuth.role).toUpperCase()) || "";
  if (role !== "AD") return res.status(403).json({ error: "Solo Asistente de dirección puede subir la póliza desde el dashboard." });
  let fileBuffer = null;
  if (typeof req.body.fileBase64 === "string") {
    try { fileBuffer = Buffer.from(req.body.fileBase64, "base64"); } catch (e) { return res.status(400).json({ error: "fileBase64 inválido" }); }
  }
  if (!fileBuffer || fileBuffer.length === 0) return res.status(400).json({ error: "Envía fileBase64 (PDF)" });
  const client = await pool.connect();
  try {
    const folio = await getFolioById(client, folioId);
    if (!folio) return res.status(404).json({ error: "Folio no encontrado" });
    let mesCargo = (req.body.mes_cargo || "").toString().trim();
    if (!/^\d{4}-\d{2}$/.test(mesCargo)) mesCargo = folio.mes_cargo || null;
    if (!mesCargo || !/^\d{4}-\d{2}$/.test(mesCargo)) {
      const now = new Date();
      mesCargo = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, "0")}`;
    }
    const est = String(folio.estatus || "").toUpperCase();
    const etapaVisual = estatusToEtapaVisual(est);
    if (etapaVisual !== ETAPA_VISUAL.CHEQUE_GENERADO) {
      return res.status(400).json({ error: "Solo se puede subir la póliza cuando el folio está en Cheque Generado." });
    }
    if (!s3Enabled) return res.status(503).json({ error: "Almacenamiento no configurado" });
    const s3Key = `polizas/${folio.numero_folio}/${Date.now()}.pdf`;
    const publicUrl = await uploadPdfToS3(fileBuffer, s3Key);
    const fileName = (req.body.fileName && String(req.body.fileName).trim()) || "poliza.pdf";
    const hash = crypto.createHash("sha256").update(fileBuffer).digest("hex");
    // Evitar error por reintentos: solo considerar duplicado si ya existe una PÓLIZA con el mismo hash (así cotización y póliza siguen siendo dos ligas)
    const existing = await findFolioArchivoByHash(client, folioId, hash, "POLIZA");
    if (existing && existing.id) {
      // Si ya estaba en carrito, de todas formas avanzar a PAGADO (idempotente)
      if (![ESTADOS.PAGADO, ESTADOS.CERRADO, ESTADOS.COMPROBACIONES, ESTADOS.EVIDENCIAS].includes(est)) {
        await client.query(
          `UPDATE public.folios SET estatus = $1, mes_cargo = $2 WHERE id = $3`,
          [ESTADOS.PAGADO, mesCargo, folioId]
        );
        await insertHistorial(
          client,
          folioId,
          folio.numero_folio,
          folio.folio_codigo,
          ESTADOS.PAGADO,
          `Póliza ya registrada (reintento desde dashboard). Pago cargado al mes ${mesCargo}.`,
          null,
          "Asistente de dirección"
        );
      }
      return res.json({ ok: true, duplicate: true, archivo_id: existing.id, estatus: ESTADOS.PAGADO, mes_cargo: mesCargo });
    }
    await insertFolioArchivo(client, {
      folio_id: folioId,
      numero_folio: folio.numero_folio,
      tipo: "POLIZA",
      s3_key: s3Key,
      url: publicUrl,
      file_name: fileName,
      file_size_bytes: fileBuffer.length,
      sha256: hash,
      subido_por: req.dashboardAuth.actor_id != null ? `Dashboard:${req.dashboardAuth.actor_id}` : "Dashboard",
    });
    await client.query(
      `UPDATE public.folios SET estatus = $1, mes_cargo = $2 WHERE id = $3`,
      [ESTADOS.PAGADO, mesCargo, folioId]
    );
    await insertHistorial(client, folioId, folio.numero_folio, folio.folio_codigo, ESTADOS.PAGADO, `Póliza adjunta desde dashboard. Pago cargado al mes ${mesCargo}.`, null, "Asistente de dirección");
    if (!folio.solo_zp_ad) {
      try {
        await notifyPlantByFolio(pool, folio.numero_folio, "POLIZA", { roles: ["GG", "GA"], mes_cargo: mesCargo });
      } catch (notifErr) {
        console.warn("[Dashboard folio poliza] Notificación GG/GA:", notifErr.message);
      }
    }
    return res.json({ ok: true, estatus: ESTADOS.PAGADO, mes_cargo: mesCargo });
  } catch (e) {
    console.error("[Dashboard folio poliza]", e);
    res.status(500).json({ error: e.message || "Error al guardar la póliza" });
  } finally {
    client.release();
  }
});

/**
 * Genera el PDF de Póliza Cheque (plantilla S3/local si está disponible, si no fallback manual).
 * @param {Object} folio - { id, numero_folio, folio_codigo, beneficiario, concepto, importe, mes_cargo, planta_nombre, planta_clave, banco, cuenta_bancaria }
 * @param {Object} [opts] - { cuenta, numero_cheque } opcionales (para impresión desde Director ZP).
 * @returns {Promise<Buffer>}
 */
async function generatePolizaPdfBytes(folio, opts) {
  const folioId = folio.id;
  const numeroFolio = (folio.numero_folio || folio.folio_codigo || `F-${folioId}`).toString().trim();
  const cuentaPoliza = (opts && opts.cuenta != null && String(opts.cuenta).trim() !== "") ? String(opts.cuenta).trim() : "—";
  const numeroChequePoliza = (opts && opts.numero_cheque != null && String(opts.numero_cheque).trim() !== "") ? String(opts.numero_cheque).trim() : "—";
    const importeNum = folio.importe != null ? Number(folio.importe) : 0;
    const importeStr = Number(importeNum).toLocaleString("es-MX", {
      minimumFractionDigits: 2,
      maximumFractionDigits: 2,
    });
    const importeLetra = numeroALetra(importeNum);
    const beneficiario = (folio.beneficiario || "").trim() || "—";
    const concepto = (folio.concepto || "").trim() || "—";
    const plantaDisplay = (folio.planta_clave || folio.planta_nombre || "").toString().trim() || "—";
    const bancoYCuentaTexto = [String(folio.banco || "").trim(), String(folio.cuenta_bancaria || "").trim()].filter(Boolean).length > 0
      ? [String(folio.banco || "").trim(), String(folio.cuenta_bancaria || "").trim()].filter(Boolean).join("  ")
      : "Banco y cuenta bancaria";
    const ahora = new Date();
    const fechaTexto = ahora.toLocaleDateString("es-MX", {
      day: "numeric",
      month: "long",
      year: "numeric",
    });

    const mesCargo = (folio.mes_cargo || "").toString().trim();
    const mesesAbr = ["Ene", "Feb", "Mar", "Abr", "May", "Jun", "Jul", "Ago", "Sep", "Oct", "Nov", "Dic"];
    let recursoTexto = "—";
    if (/^\d{4}-\d{2}$/.test(mesCargo)) {
      const [yr, mo] = mesCargo.split("-").map(Number);
      recursoTexto = `${mesesAbr[mo - 1] || ""} ${yr}`;
    }

    const wrapText = (text, size, maxWidthPoints) => {
      const maxChars = Math.max(20, Math.floor(maxWidthPoints / (size * 0.5)));
      const words = String(text || "").trim().split(/\s+/).filter(Boolean);
      if (words.length === 0) return [""];
      const lines = [];
      let current = "";
      for (const w of words) {
        const next = current ? current + " " + w : w;
        if (next.length <= maxChars) current = next;
        else {
          if (current) lines.push(current);
          current = w.length <= maxChars ? w : w.substring(0, maxChars);
        }
      }
      if (current) lines.push(current);
      return lines.length ? lines : [""];
    };

    let pdfBytes = null;
    let templateBuf = null;
    let templateSource = null;
    let templateError = null;
    let usedTemplate = false;

    const s3TemplateKey = (process.env.POLIZA_TEMPLATE_S3_KEY || "").trim();

    // ============================================================
    // 1) Intentar SIEMPRE plantilla S3 primero
    // ============================================================
    if (s3Enabled && s3TemplateKey) {
      try {
        console.log("[poliza/documento] Intentando descargar plantilla desde S3:", s3TemplateKey);
        templateBuf = await getBufferFromS3(s3TemplateKey);
        templateSource = "S3:" + s3TemplateKey;
        console.log("[poliza/documento] Plantilla S3 descargada OK. Bytes:", templateBuf?.length || 0);
      } catch (e) {
        templateError = e;
        console.warn("[poliza/documento] ERROR descargando plantilla desde S3:", {
          key: s3TemplateKey,
          name: e?.name,
          code: e?.code || e?.Code,
          message: e?.message,
        });
      }
    } else {
      console.warn("[poliza/documento] Plantilla S3 no intentada. Razón:", {
        s3Enabled,
        hasTemplateKey: !!s3TemplateKey,
      });
    }

    // ============================================================
    // 2) Si S3 falla, intentar plantilla local
    // ============================================================
    if (!templateBuf) {
      const templatePath = process.env.POLIZA_TEMPLATE_PATH || path.join(__dirname, "templates", "formato-poliza.pdf");
      try {
        console.log("[poliza/documento] Intentando plantilla local:", templatePath);
        templateBuf = await fsPromises.readFile(templatePath);
        templateSource = "local:" + templatePath;
        console.log("[poliza/documento] Plantilla local cargada OK. Bytes:", templateBuf?.length || 0);
      } catch (e) {
        console.warn("[poliza/documento] ERROR plantilla local:", {
          path: templatePath,
          code: e?.code,
          message: e?.message,
        });
      }
    }

    // ============================================================
    // 3) Si hay plantilla, intentar usarla como base
    // ============================================================
    if (templateBuf) {
      try {
        console.log("[poliza/documento] Intentando abrir plantilla con pdf-lib:", templateSource);

        // ignoreEncryption ayuda en algunos PDFs problemáticos
        const pdfDoc = await PDFDocument.load(templateBuf, { ignoreEncryption: true });

        const pages = pdfDoc.getPages();
        if (!pages || pages.length === 0) {
          throw new Error("La plantilla PDF no contiene páginas");
        }

        const page = pages[0];
        const font = await pdfDoc.embedFont(StandardFonts.Helvetica);
        const fontBold = await pdfDoc.embedFont(StandardFonts.HelveticaBold);

        // ========================================================
        // Coordenadas AJUSTABLES según tu plantilla real
        // ========================================================
        const POS = {
          folio: { x: 412.5, y: 610.9, size: 10 },
          beneficiarioTop: { x: 50, y: 682, size: 9 },
          administrador: { x: 381.5, y: 395, size: 8 },
          recurso: { x: 381.5, y: 375, size: 9 },
          importeLetra1: { x: 50, y: 651, size: 9 },
          fecha1: { x: 381.5, y: 717, size: 9 },
          beneficiarioImporte: { x: 50, y: 490, size: 9 },
          importe2Top: { x: 430, y: 682, size: 9 },
          importeLetra2: { x: 35, y: 86.6, size: 7 },
          concepto: { x: 130, y: 568, size: 7 },
          planta: { x: 100, y: 717, size: 12 },
          fecha2: { x: 246.8, y: 134.5, size: 8 },
          beneficiario2: { x: 35, y: 112.58, size: 8 },
          importe2: { x: 392.5, y: 114.78, size: 8 },
          cuenta: { x: 130, y: 602, size: 10 },
          numeroCheque: { x: 325, y: 602, size: 10 },
        };

        const draw = (text, x, y, size = 9, bold = false, maxLen = 140) => {
          const safe = String(text ?? "").trim();
          if (!safe) return;
          page.drawText(safe.substring(0, maxLen), {
            x,
            y,
            size,
            font: bold ? fontBold : font,
          });
        };
        // Efecto Helvetica Condensed: espaciado estrecho (avance 0.42). pdf-lib StandardFonts no incluye Condensed. “O” más redonda/ancha)
        const drawCondensed = (text, x, y, size = 9, maxLen = 140) => {
          const safe = String(text ?? "").trim().substring(0, maxLen);
          if (!safe) return;
          let xPos = x;
          for (const char of safe) {
            page.drawText(char, { x: xPos, y, size, font });
            xPos += size * 0.42;
          }
        };

        draw(`FOLIO - ${numeroFolio}`, POS.folio.x, POS.folio.y, POS.folio.size, true);
        draw(beneficiario, POS.beneficiarioTop.x, POS.beneficiarioTop.y, POS.beneficiarioTop.size);
        draw("ADMINISTRADOR", POS.administrador.x, POS.administrador.y, POS.administrador.size);
        draw(recursoTexto, POS.recurso.x, POS.recurso.y, POS.recurso.size);
        draw(importeLetra, POS.importeLetra1.x, POS.importeLetra1.y, POS.importeLetra1.size);
        draw(fechaTexto, POS.fecha1.x, POS.fecha1.y, POS.fecha1.size);
        draw(bancoYCuentaTexto, POS.beneficiarioImporte.x, POS.beneficiarioImporte.y, POS.beneficiarioImporte.size);
        draw(importeLetra, POS.importeLetra2.x, POS.importeLetra2.y, POS.importeLetra2.size);
        const conceptoLines = wrapText(concepto, POS.concepto.size, 400);
        let conceptoY = POS.concepto.y;
        conceptoLines.forEach((line) => {
          draw(line, POS.concepto.x, conceptoY, POS.concepto.size);
          conceptoY -= POS.concepto.size * 1.2;
        });
        draw(plantaDisplay, POS.planta.x, POS.planta.y, POS.planta.size);
        draw(fechaTexto, POS.fecha2.x, POS.fecha2.y, POS.fecha2.size);
        draw(beneficiario, POS.beneficiario2.x, POS.beneficiario2.y, POS.beneficiario2.size);
        draw(importeStr, POS.importe2Top.x, POS.importe2Top.y, POS.importe2Top.size);
        draw(importeStr, POS.importe2.x, POS.importe2.y, POS.importe2.size);
        draw(cuentaPoliza, POS.cuenta.x, POS.cuenta.y, POS.cuenta.size);
        draw(numeroChequePoliza, POS.numeroCheque.x, POS.numeroCheque.y, POS.numeroCheque.size);

        pdfBytes = await pdfDoc.save();
        usedTemplate = true;

        console.log("[poliza/documento] PDF generado usando plantilla:", {
          templateSource,
          outputBytes: pdfBytes?.length || 0,
          folioId,
          numeroFolio,
        });
      } catch (e) {
        templateError = e;
        usedTemplate = false;
        pdfBytes = null;

        const preview = templateBuf && templateBuf.length >= 5
          ? templateBuf.slice(0, 20).toString("latin1").replace(/[^\x20-\x7E]/g, ".")
          : "(sin buffer)";
        console.warn("[poliza/documento] ERROR al cargar o rellenar plantilla. Se usará fallback manual.", {
          templateSource,
          name: e?.name,
          message: e?.message,
          primerosBytes: preview,
          stackTop: e?.stack ? String(e.stack).split("\n").slice(0, 3).join(" | ") : null,
        });
      }
    }

    // ============================================================
    // 4) Fallback SOLO si la plantilla falló de verdad
    // ============================================================
    if (!pdfBytes) {
      console.log("[poliza/documento] FALLBACK manual activado", {
        folioId,
        numeroFolio,
        hadTemplateBuffer: !!templateBuf,
        templateSource,
        templateError: templateError
          ? {
              name: templateError?.name,
              code: templateError?.code || templateError?.Code,
              message: templateError?.message,
            }
          : null,
      });

      const pdfDoc = await PDFDocument.create();
      const page = pdfDoc.addPage([612, 792]);
      const font = await pdfDoc.embedFont(StandardFonts.Helvetica);
      const fontBold = await pdfDoc.embedFont(StandardFonts.HelveticaBold);

      const marginLeft = 50;
      const marginRight = 562;
      const width = marginRight - marginLeft;
      let y = 760;
      const th = 1;

      const drawLine = (x1, y1, x2, y2) => {
        page.drawLine({ start: { x: x1, y: y1 }, end: { x: x2, y: y2 }, thickness: th });
      };

      const txt = (str, x, yPos, size = 10, bold = false) => {
        const f = bold ? fontBold : font;
        page.drawText(String(str).substring(0, 120), { x, y: yPos, size, font: f });
      };

      txt("POLIZA CHEQUE", marginLeft, y, 16, true);
      txt(`FOLIO - ${numeroFolio}`, 400, y, 10, true);
      y -= 24;
      txt("CTA:", marginLeft, y, 10);
      txt(cuentaPoliza, marginLeft + 40, y, 9);
      y -= 20;

      const tabW = width / 3;
      const x1 = marginLeft;
      const x2 = marginLeft + tabW;
      const x3 = marginLeft + tabW * 2;

      drawLine(x1, y, marginRight, y);
      txt("PARCIAL", x1 + 4, y - 12, 9, true);
      txt("DEBE", x2 + 4, y - 12, 9, true);
      txt("HABER", x3 + 4, y - 12, 9, true);
      drawLine(x1, y - 14, marginRight, y - 14);
      drawLine(x1, y, x1, y - 14);
      drawLine(x2, y, x2, y - 14);
      drawLine(x3, y, x3, y - 14);
      drawLine(marginRight, y, marginRight, y - 14);

      y -= 28;
      drawLine(x1, y, marginRight, y);
      drawLine(x1, y + 14, x1, y);
      drawLine(x2, y + 14, x2, y);
      drawLine(x3, y + 14, x3, y);
      drawLine(marginRight, y + 14, marginRight, y);

      txt("HECHO POR:", x1 + 4, y - 12, 8);
      txt("AUTORIZADO:", x2 + 4, y - 12, 8);
      txt("*RESPONSABLE A COMPROBAR EL GASTO:", x3 + 4, y - 12, 8);

      y -= 18;
      drawLine(x1, y, marginRight, y);
      txt("NOMBRE", x1 + 4, y - 10, 8);
      txt("ADMINISTRADOR", x2 + 4, y - 10, 8);
      txt(beneficiario, x1 + 4, y - 22, 9);

      y -= 26;
      drawLine(x1, y, marginRight, y);
      txt("RECURSO:", x1 + 4, y - 10, 8);
      txt(recursoTexto, x2 + 4, y - 10, 9);

      y -= 22;
      txt("Recibí cheque original (Nombre completo, fecha y firma)", marginLeft, y, 8);

      y -= 18;
      const importeLetraLines =
        importeLetra.length > 70 ? [importeLetra.substring(0, 70), importeLetra.substring(70)] : [importeLetra];
      importeLetraLines.forEach((line) => {
        txt(line, marginLeft, y, 9);
        y -= 14;
      });

      y -= 8;
      txt("SUMAS IGUALES", marginLeft, y, 9);
      txt("REVISADO", marginLeft + 180, y, 9);
      txt("MESA DE", marginLeft + 320, y, 9);
      txt("CONTROL.", marginLeft + 320, y - 12, 9);

      y -= 28;
      txt(fechaTexto, marginLeft, y, 9);
      txt(bancoYCuentaTexto, marginLeft, y - 14, 9);

      y -= 28;
      txt(importeLetra, marginLeft, y, 8);

      y -= 22;
      txt("NO. CHEQUE:", marginLeft, y, 8);
      txt(numeroChequePoliza, marginLeft + 75, y, 8);

      y -= 18;
      txt("CONCEPTO:", marginLeft, y, 8);
      const conceptoLines = wrapText(concepto, 9, 380);
      conceptoLines.forEach((line) => { txt(line, marginLeft + 65, y, 9); y -= 10; });

      y -= 22;
      txt("NOMBRE", marginLeft, y, 8);
      txt("COPIA DEL CHEQUE", marginLeft + 200, y, 8);

      y -= 22;
      txt(plantaDisplay, marginLeft, y, 9);
      txt(fechaTexto, marginLeft + 120, y, 9);
      txt(beneficiario, marginLeft, y - 14, 9);
      txt(importeStr, marginLeft + 380, y - 14, 9);

      y -= 28;
      txt("RECIBI CHEQUE", marginLeft, y, 9);

      pdfBytes = await pdfDoc.save();

      console.log("[poliza/documento] PDF generado con fallback manual", {
        outputBytes: pdfBytes?.length || 0,
        folioId,
        numeroFolio,
      });
    }

    if (!pdfBytes) throw new Error("No se pudo generar el PDF de póliza");
    return Buffer.from(pdfBytes);
}

/** Documento Póliza Cheque (formato oficial). Genera PDF con datos del folio. */
app.get("/api/folios/:id/poliza/documento", dashboardAuthMiddleware, dashboardBlockGVFoliosMiddleware, async (req, res) => {
  console.log("[poliza/documento] ENDPOINT GOLPEADO", {
    folioId: req.params.id,
    format: req.query.format,
    hasAuthHeader: !!req.headers.authorization,
  });
  const folioId = parseInt(req.params.id, 10);
  if (!Number.isFinite(folioId)) return res.status(400).json({ error: "id inválido" });
  const format = (req.query.format || "pdf").toLowerCase();
  if (format !== "pdf") return res.status(400).json({ error: "Solo format=pdf" });
  const client = await pool.connect();
  try {
    const r = await client.query(
      `SELECT f.id, f.planta_id, f.solo_zp_ad, f.numero_folio, f.folio_codigo, f.beneficiario, f.concepto, f.importe, f.creado_en, f.mes_cargo, f.banco, f.cuenta_bancaria,
              p.nombre AS planta_nombre, p.clave AS planta_clave
       FROM public.folios f
       LEFT JOIN public.plantas p ON p.id = f.planta_id
       WHERE f.id = $1`,
      [folioId]
    );
    const folio = r.rows[0] || null;
    if (!folio) return res.status(404).json({ error: "Folio no encontrado" });
    const esZPDoc = (req.dashboardAuth.role && String(req.dashboardAuth.role).toUpperCase()) === "ZP";
    const esADDoc = (req.dashboardAuth.role && String(req.dashboardAuth.role).toUpperCase()) === "AD";
    if (folio.solo_zp_ad && !authCanVerFoliosSoloZpAd(req.dashboardAuth)) return res.status(404).json({ error: "Folio no encontrado" });
    if ((req.dashboardAuth.role === "GG" || req.dashboardAuth.role === "GA") && req.dashboardAuth.plantas_permitidas?.length > 0) {
      const folioPlantaId = folio.planta_id != null ? folio.planta_id : null;
      if (folioPlantaId == null || !req.dashboardAuth.plantas_permitidas.includes(folioPlantaId)) {
        return res.status(403).json({ error: "Sin permiso para este folio" });
      }
    }
    const pdfBytes = await generatePolizaPdfBytes(folio);
    res.setHeader("Content-Type", "application/pdf");
    res.setHeader(
      "Content-Disposition",
      `attachment; filename="Poliza-Cheque-${String(folio.numero_folio || folioId).replace(/\s/g, "-")}.pdf"`
    );
    return res.send(pdfBytes);
  } catch (e) {
    console.error("[poliza/documento] ERROR GENERAL:", e);
    return res.status(500).json({ error: e.message || "Error al generar documento de póliza" });
  } finally {
    client.release();
  }
});

/** Subir cotización PDF desde el dashboard (selector de archivo). Cualquier rol con acceso al folio puede subir; se marca como APROBADA y se actualiza folio. */
app.post("/api/folios/:id/cotizacion", dashboardAuthMiddleware, dashboardBlockGVFoliosMiddleware, async (req, res) => {
  const folioId = parseInt(req.params.id, 10);
  if (!Number.isFinite(folioId)) return res.status(400).json({ error: "id inválido" });
  let fileBuffer = null;
  if (typeof req.body.fileBase64 === "string") {
    try { fileBuffer = Buffer.from(req.body.fileBase64, "base64"); } catch (e) { return res.status(400).json({ error: "fileBase64 inválido" }); }
  }
  if (!fileBuffer || fileBuffer.length === 0) return res.status(400).json({ error: "Envía fileBase64 (PDF)" });
  const client = await pool.connect();
  try {
    const folio = await getFolioById(client, folioId);
    if (!folio) return res.status(404).json({ error: "Folio no encontrado" });
    if ((req.dashboardAuth.role === "GG" || req.dashboardAuth.role === "GA") && req.dashboardAuth.plantas_permitidas?.length > 0) {
      if (!folio.planta_id || !req.dashboardAuth.plantas_permitidas.includes(folio.planta_id)) {
        return res.status(403).json({ error: "Sin permiso para este folio" });
      }
    }
    if (!s3Enabled) return res.status(503).json({ error: "Almacenamiento no configurado" });
    const s3Key = `cotizaciones/${folio.numero_folio}/${Date.now()}.pdf`;
    const publicUrl = await uploadPdfToS3(fileBuffer, s3Key);
    const fileName = (req.body.fileName && String(req.body.fileName).trim()) || "cotizacion.pdf";
    const hash = crypto.createHash("sha256").update(fileBuffer).digest("hex");
    const existing = await findFolioArchivoByHash(client, folioId, hash, "COTIZACION");
    if (existing && existing.id) {
      await aprobarFolioArchivoCDMX(client, existing.id, req.dashboardAuth.actor_id != null ? `Dashboard:${req.dashboardAuth.actor_id}` : "Dashboard");
      return res.json({ ok: true, duplicate: true });
    }
    const row = await insertFolioArchivo(client, {
      folio_id: folioId,
      numero_folio: folio.numero_folio,
      tipo: "COTIZACION",
      s3_key: s3Key,
      url: publicUrl,
      file_name: fileName,
      file_size_bytes: fileBuffer.length,
      sha256: hash,
      subido_por: req.dashboardAuth.actor_id != null ? `Dashboard:${req.dashboardAuth.actor_id}` : "Dashboard",
    });
    await aprobarFolioArchivoCDMX(client, row.id, req.dashboardAuth.actor_id != null ? `Dashboard:${req.dashboardAuth.actor_id}` : "Dashboard");
    return res.json({ ok: true });
  } catch (e) {
    console.error("[Dashboard folio cotizacion]", e);
    res.status(500).json({ error: e.message || "Error al guardar la cotización" });
  } finally {
    client.release();
  }
});

