/**
 * Lista de clientes (con kg, descuento y estatus vs. mes anterior) para la planta y mes pedidos.
 * Reutiliza la misma lógica que la hoja "Clientes desc mes" del Excel ARR Forecast.
 * Para meses ya concluidos sólo devuelve `kg_real`; para el mes en curso devuelve también `kg_proyectado`.
 */
app.get("/api/dashboard/arr-clientes-mes", dashboardAuthMiddleware, async (req, res) => {
  if (dashboardBlockGAFinancialKpis(req, res)) return;
  if (dashboardBlockGVForbidden(req, res)) return;
  const year = req.query.year != null ? parseInt(String(req.query.year), 10) : NaN;
  const month = req.query.month != null ? parseInt(String(req.query.month), 10) : NaN;
  const empresa = (req.query.empresa || "").toString().trim();
  if (!Number.isFinite(year) || !Number.isFinite(month) || month < 1 || month > 12) {
    return res.status(400).json({ error: "year y month (1-12) son obligatorios" });
  }
  if (!empresa) {
    return res.status(400).json({ error: "Falta empresa" });
  }
  const client = await pool.connect();
  try {
    const provRes = await client.query("SELECT plant_code FROM arr.provincia_plants ORDER BY plant_code");
    const provinciaPlantCodes = (provRes.rows || []).map((r) => (r.plant_code || "").trim()).filter(Boolean);
    const empNorm = normalizeAccents(empresa);
    const matches = provinciaPlantCodes.filter((p) => {
      const pNorm = normalizeAccents(p);
      return empNorm === pNorm || empNorm.includes(pNorm) || pNorm.includes(empNorm);
    });
    const plantCode = matches.length
      ? matches.reduce((a, b) => (a.length >= b.length ? a : b))
      : null;
    if (!plantCode) {
      return res.status(404).json({ error: `No se encontró planta provincia para empresa "${empresa}"` });
    }
    const now = new Date();
    const curYear = now.getFullYear();
    const curMonth = now.getMonth() + 1;
    const historico = year < curYear || (year === curYear && month < curMonth);
    const targetKgRaw =
      req.query.target_kg != null ? parseFloat(String(req.query.target_kg).replace(/,/g, "")) : NaN;
    const targetKgOverride =
      !historico && Number.isFinite(targetKgRaw) && targetKgRaw > 0 ? targetKgRaw : null;
    const resp = await dashboardArrForecast.computeClientesDescuentoMes(
      client,
      year,
      month,
      plantCode,
      { historico, targetKgOverride }
    );
    const rowsBase = (resp.rows || []).map((r) => ({
      planta: r.planta,
      cliente: r.cliente,
      categoria: r.categoria,
      subcategoria: r.subcategoria,
      kg_real: Number.isFinite(r.kg) ? Math.round(r.kg * 100) / 100 : 0,
      kg_proyectado: historico
        ? null
        : Number.isFinite(r.kgProy)
          ? Math.round(r.kgProy * 100) / 100
          : 0,
      descuento_mxn: Number.isFinite(r.monto) ? Math.round(r.monto * 100) / 100 : 0,
      descuento_kg: r.descKg != null && Number.isFinite(r.descKg) ? Math.round(r.descKg * 1e6) / 1e6 : null,
      estatus: r.estatus || "",
    }));
    let rows = rowsBase;
    try {
      const plantaIdRaw = await dicfAccionesLib.resolvePlantaId(client, empresa);
      const canonPlantaId = Number.isFinite(plantaIdRaw) ? dicfAccionesLib.getCanonicalPlantaId(plantaIdRaw) : null;
      const plantaIdsEquiv =
        Number.isFinite(canonPlantaId) && canonPlantaId != null
          ? dicfAccionesLib.getPlantaIdsEquivalentes(canonPlantaId)
          : [];
      const accionesAbiertasByKey = new Map();
      const accionesAbiertasByNombre = new Map();
      if (plantaIdsEquiv.length) {
        const arKey = await client.query(
          `SELECT cliente_key, COUNT(*)::int AS c
             FROM arr.dicf_acciones
            WHERE planta_id = ANY($1::int[])
              AND (cerrado_at IS NULL)
              AND (estado IS NULL OR estado <> 'hecho')
            GROUP BY cliente_key`,
          [plantaIdsEquiv]
        );
        for (const row of arKey.rows || []) {
          if (row.cliente_key) accionesAbiertasByKey.set(String(row.cliente_key), Number(row.c) || 0);
        }
        const arNom = await client.query(
          `SELECT cliente_nombre, COUNT(*)::int AS c
             FROM arr.dicf_acciones
            WHERE planta_id = ANY($1::int[])
              AND (cerrado_at IS NULL)
              AND (estado IS NULL OR estado <> 'hecho')
            GROUP BY cliente_nombre`,
          [plantaIdsEquiv]
        );
        for (const row of arNom.rows || []) {
          const k = dicfAccionesLib.normalizeKeyPart(row.cliente_nombre);
          accionesAbiertasByNombre.set(k, (accionesAbiertasByNombre.get(k) || 0) + (Number(row.c) || 0));
        }
      }
      rows = rowsBase.map((c) => {
        const canal = (c.categoria != null && String(c.categoria).trim()) || "";
        const subcanal = (c.subcategoria != null && String(c.subcategoria).trim()) || "";
        const cli = (c.cliente != null && String(c.cliente).trim()) || "";
        const est = String(c.estatus || "").trim();
        const gruposTry = new Set([est].filter((x) => x && x.length));
        let n = 0;
        if (canonPlantaId != null && Number.isFinite(canonPlantaId)) {
          for (const g of gruposTry) {
            const ck = dicfAccionesLib.buildClienteKey(canonPlantaId, g, canal, subcanal, cli);
            n = Math.max(n, accionesAbiertasByKey.get(ck) || 0);
          }
        }
        if (!n) {
          const nk = dicfAccionesLib.normalizeKeyPart(cli);
          n = accionesAbiertasByNombre.get(nk) || 0;
        }
        return { ...c, acciones_abiertas: n };
      });
    } catch (_accErr) {
      rows = rowsBase.map((c) => ({ ...c, acciones_abiertas: 0 }));
    }
    res.json({
      ok: true,
      year,
      month,
      empresa,
      planta: plantCode,
      historico,
      rows,
    });
  } catch (e) {
    console.error("[Dashboard arr-clientes-mes]", e);
    res.status(500).json({ error: e.message });
  } finally {
    client.release();
  }
});

