app.get("/api/arr/dashboard-excel", dashboardAuthMiddleware, async (req, res) => {
  if (dashboardBlockGAFinancialKpis(req, res)) return;
  if (dashboardBlockGVForbidden(req, res)) return;
  const plantCode = (req.query.plant_code || "").trim() || null;
  const year = parseInt(req.query.year, 10);
  const month = parseInt(req.query.month, 10);
  if (!Number.isFinite(year) || !Number.isFinite(month) || month < 1 || month > 12) {
    return res.status(400).json({ error: "Faltan year y month válidos en query" });
  }
  const proyeccionHasta = (req.query.proyeccion_hasta || "").toString().trim().slice(0, 10) || null;
  // Si el frontend no manda upload_day, usar el mismo corte (proyeccion_hasta)
  // para que el IGF Forecast dentro del Excel sea consistente con la fecha seleccionada.
  const uploadDay =
    ((req.query.upload_day || "").toString().trim().slice(0, 10)) ||
    proyeccionHasta ||
    null;
  const versionAsOfCorteExcel = /^(1|true|yes)$/i.test(String(req.query.version_as_of_corte || "").trim());
  let proyeccionCatSub = null;
  if (req.query.proyeccion_mes != null && req.query.proyeccion_anio != null) {
    const proyeccionMes = parseInt(String(req.query.proyeccion_mes), 10);
    const proyeccionAnio = parseInt(String(req.query.proyeccion_anio), 10);
    if (!Number.isFinite(proyeccionMes) || !Number.isFinite(proyeccionAnio) || proyeccionMes < 1 || proyeccionMes > 12) {
      return res.status(400).json({ error: "proyeccion_mes (1-12) y proyeccion_anio deben ser válidos" });
    }
    proyeccionCatSub = {
      targetYear: proyeccionAnio,
      targetMonth: proyeccionMes,
      fechaHasta: proyeccionHasta,
      plantCodeFilter: plantCode,
      // También aplicar regla de tres para que coincida con el total oficial del mes objetivo (si existe en forecast_mensual).
      scaleToForecastTotal: true,
    };
  }
  const proyeccionCatSubForecast = {
    targetYear: year,
    targetMonth: month,
    fechaHasta: proyeccionHasta,
    plantCodeFilter: plantCode,
    sheetName: "Proy cat-sub Forecast",
    // Acumulado + factor por planta + proyección por regla de tres para cerrar con IGF.
    scaleToForecastTotal: true,
    useMtdRuleOfThree: false,
    useMtdAcumulado: true,
  };
  const client = await pool.connect();
  try {
    const excelIgfOpts = {};
    if (uploadDay) excelIgfOpts.upload_day = uploadDay;
    if (versionAsOfCorteExcel) excelIgfOpts.version_as_of_corte = true;
    const igfForecast = await buildIgfForecastPayload(
      client,
      year,
      month,
      Object.keys(excelIgfOpts).length ? excelIgfOpts : undefined
    );
    // Mapear "empresa" IGF → plant_code provincia (nombres no siempre coinciden exacto: "GTM Puebla" vs "Puebla").
    const forecastKgByPlant = {};
    const igfRows = (igfForecast?.rows || [])
      .map((r) => {
        const emp = (r?.empresa || "").trim();
        const ton = r?.venta_ton != null && Number.isFinite(Number(r.venta_ton)) ? Number(r.venta_ton) : null;
        return emp && ton != null ? { emp, empNorm: normalizeAccents(emp), kg: ton * 1000 } : null;
      })
      .filter(Boolean);
    // 1) Inicial: coincidencia exacta por empresa
    for (const row of igfRows) {
      forecastKgByPlant[row.emp] = row.kg;
    }
    // 2) Para cada plant_code provincia, buscar mejor match en IGF (contains bidireccional sobre nombre normalizado).
    const provPlantsR = await client.query(`SELECT plant_code FROM arr.provincia_plants ORDER BY plant_code`);
    const provPlants = (provPlantsR.rows || []).map((x) => (x.plant_code || "").trim()).filter(Boolean);
    for (const p of provPlants) {
      const pNorm = normalizeAccents(p);
      if (forecastKgByPlant[p] != null) continue; // ya existe exacto
      let best = null;
      for (const row of igfRows) {
        if (!row.empNorm) continue;
        if (row.empNorm.includes(pNorm) || pNorm.includes(row.empNorm)) {
          // Preferir el match más "cercano": nombre más corto (más específico) o mayor kg si empata.
          if (
            !best ||
            row.empNorm.length < best.empNorm.length ||
            (row.empNorm.length === best.empNorm.length && row.kg > best.kg)
          ) {
            best = row;
          }
        }
      }
      if (best) forecastKgByPlant[p] = best.kg;
    }
    proyeccionCatSubForecast.forecastKgByPlant = forecastKgByPlant;
    const buf = await dashboardArrForecast.generarDashboardArrForecast(client, year, month, plantCode, {
      igfForecast,
      proyeccionCatSub,
      proyeccionCatSubForecast,
      // Fecha de corte seleccionada en el dashboard: a partir de aquí no debe aparecer venta/desc (cero).
      // Si no viene, se usa la fecha del servidor como fallback.
      fechaCorte: uploadDay || proyeccionHasta || null,
    });
    try {
      const fechaCorteStr = (uploadDay || proyeccionHasta || "").toString().trim().slice(0, 10);
      const ctxMini = await dashboardArrForecast.buildPronosticoVentaDescMaps(client, year, month, fechaCorteStr);
      const proySnap = await dashboardArrForecast.computePronosticoProyByPlant(client, year, month, { fechaCorte: fechaCorteStr });
      await dashboardArrForecast.savePronosticoMiniSnapshot(client, year, month, ctxMini.corteYmdStr, proySnap);
    } catch (snapErr) {
      console.error("[ARR dashboard-excel] pronostico_mini_snapshot", snapErr);
    }
    const filename = `Dashboard_ARR_Forecast_${year}_${month}.xlsx`;
    res.setHeader("Content-Type", "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet");
    res.setHeader("Content-Disposition", `attachment; filename="${filename}"`);
    res.send(buf);
  } catch (e) {
    console.error("[ARR dashboard-excel]", e);
    res.status(500).json({ error: e.message });
  } finally {
    client.release();
  }
});

