/** Normaliza nombre de empresa para agrupar variantes (acentos, guiones, espacios). */
function normalizarEmpresaKey(s) {
  if (typeof s !== "string") return "";
  const t = s
    .trim()
    .toLowerCase()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .replace(/[-–—]/g, " ")
    .replace(/\s+/g, " ")
    .trim()
    .replace(/\s+p\.?\s*$/, "");
  return t;
}

/** Lista de empresas (plantas) que aparecen en IGF versiones (última versión del mes más reciente). Para "Préstamos a planta". Sin duplicados por escritura (acentos/guiones). */
app.get("/api/dashboard/igf-empresas", dashboardAuthMiddleware, async (req, res) => {
  if (dashboardBlockGAFinancialKpis(req, res)) return;
  if (dashboardBlockGVForbidden(req, res)) return;
  const client = await pool.connect();
  try {
    const r = await client.query(
      `SELECT DISTINCT c.empresa FROM igf.compromiso_lines c
       JOIN igf.versions v ON v.id = c.version_id
       WHERE v.plant_code = 'GLOBAL'
       ORDER BY c.empresa`
    );
    const raw = (r.rows || []).map((row) => (row.empresa || "").trim()).filter((e) => e && !/^TOTALES?$/i.test(e));
    const byKey = new Map();
    for (const name of raw) {
      const key = normalizarEmpresaKey(name);
      if (!key) continue;
      if (!byKey.has(key)) byKey.set(key, name);
    }
    const empresas = [...byKey.values()].sort((a, b) => a.localeCompare(b));
    res.json({ empresas });
  } catch (e) {
    console.error("[Dashboard igf-empresas]", e);
    res.status(500).json({ error: e.message });
  } finally {
    client.release();
  }
});

/** Genera token y URL para descarga Excel "Cómo cambió" (mismo flujo que WhatsApp). */
app.post("/api/dashboard/igf-como-cambio-token", dashboardAuthMiddleware, async (req, res) => {
  if (dashboardBlockGAFinancialKpis(req, res)) return;
  if (dashboardBlockGVForbidden(req, res)) return;
  const { planta, yearA, monthA, versionA, yearB, monthB, versionB } = req.body || {};
  const p = (v) => (v != null && v !== "" ? parseInt(v, 10) : null);
  const yA = p(yearA); const mA = p(monthA); const vA = p(versionA);
  const yB = p(yearB); const mB = p(monthB); const vB = p(versionB);
  if (!planta || typeof planta !== "string" || !planta.trim()) {
    return res.status(400).json({ error: "Falta planta" });
  }
  if (!Number.isFinite(yA) || !Number.isFinite(mA) || !Number.isFinite(vA) || !Number.isFinite(yB) || !Number.isFinite(mB) || !Number.isFinite(vB)) {
    return res.status(400).json({ error: "Faltan year/month/version para A o B" });
  }
  const excelToken = createIgfComoCambioToken({
    planta: planta.trim(),
    yearA: yA, monthA: mA, versionA: vA,
    yearB: yB, monthB: mB, versionB: vB,
  });
  const botBase = (process.env.BASE_URL || process.env.PUBLIC_URL || "").trim() || `${req.protocol}://${req.get("host") || "localhost"}`;
  const url = `${botBase.replace(/\/$/, "")}/api/igf/como-cambio-excel?t=${encodeURIComponent(excelToken)}`;
  res.json({ url });
});

