/** Alias nombre dropdown/IGF -> nombre en public.plantas (para Delta Ingreso Forecast y listas). */
const ALIAS_PLANTA_NOMBRE = {
  "gt puebla": "Puebla",
  "gt - puebla": "Puebla",
  "gtm queretaro": "Querétaro",
  "gtm querétaro": "Querétaro",
  "gtm - querétaro": "Querétaro",
  "gtm san luis": "San Luis",
  "gtm san luis p.": "San Luis",
  "gtm - san luis p.": "San Luis",
  "tehuacan": "Tehuacán",
  "tehuacán": "Tehuacán",
};

/** Obtiene un plant_code de arr que corresponde al nombre de planta. No exige datos en ventas; todas las plantas en provincia_plants pueden usar Delta Forecast. */
async function getPlantCodeArrFromPlantaNombre(client, plantaNombre) {
  const raw = plantaNombre.trim();
  const alias = ALIAS_PLANTA_NOMBRE[raw.toLowerCase()] || raw;
  const r = await client.query(
    `WITH prov_map AS (
       SELECT DISTINCT p.nombre AS prov_name, ap.plant_code AS arr_plant_code
         FROM public.plantas p
         JOIN arr.provincia_plants ap ON UPPER(TRIM(ap.plant_code)) = UPPER(TRIM(p.nombre)) OR (p.clave IS NOT NULL AND TRIM(p.clave) <> '' AND UPPER(TRIM(ap.plant_code)) = UPPER(TRIM(p.clave)))
        WHERE UPPER(TRIM(COALESCE(p.nombre, ''))) != 'CORPORATIVO' AND UPPER(TRIM(COALESCE(p.clave, ''))) != 'CORPORATIVO'
     )
     SELECT pm.arr_plant_code AS plant_code FROM prov_map pm
     WHERE pm.prov_name = $1 OR UPPER(TRIM(pm.prov_name)) = UPPER(TRIM($1))
     LIMIT 1`,
    [alias]
  );
  if (r.rows && r.rows[0] && r.rows[0].plant_code) return r.rows[0].plant_code;
  const r2 = await client.query(
    `SELECT plant_code FROM arr.provincia_plants WHERE UPPER(TRIM(plant_code)) = UPPER(TRIM($1)) LIMIT 1`,
    [raw]
  );
  return (r2.rows && r2.rows[0] && r2.rows[0].plant_code) ? r2.rows[0].plant_code : raw;
}

/** Periodos (YYYY-MM) disponibles para Delta Ingreso en una planta (mismos que Delta Venta). Usa mismo alias que getPlantCodeArrFromPlantaNombre para que todas las plantas del dropdown tengan fechas. */
app.get("/api/dashboard/delta-ingreso-periodos", dashboardAuthMiddleware, async (req, res) => {
  const roleNorm = (req.dashboardAuth && req.dashboardAuth.role) ? String(req.dashboardAuth.role).toUpperCase() : "";
  if (roleNorm === "GA") return res.status(403).json({ error: "Sin permiso para Delta (GA restringido)." });
  const planta = (req.query.planta || "").toString().trim();
  if (!planta) {
    return res.status(400).json({ error: "Falta planta" });
  }
  const plantaResuelta = ALIAS_PLANTA_NOMBRE[planta.toLowerCase()] || planta;
  const client = await pool.connect();
  try {
    if (isDashboardGV(req)) {
      const chk = await assertGVPlantaNombreAccess(client, req.dashboardAuth, planta);
      if (!chk.ok) return res.status(chk.status).json({ error: chk.error });
    }
    const periodos = await getPeriodosDeltaVenta(client, plantaResuelta);
    res.json({ periodos: periodos || [] });
  } catch (e) {
    console.error("[Dashboard delta-ingreso-periodos]", e);
    res.status(500).json({ error: e.message });
  } finally {
    client.release();
  }
});

/** Delta Ingreso Forecast: A = mes anterior real, B = forecast a cierre. Devuelve dejaron, nuevos, aumentaron, disminuyeron y byCategoria. */
app.post("/api/dashboard/delta-ingreso-forecast-datos", dashboardAuthMiddleware, async (req, res) => {
  if (dashboardBlockGAFinancialKpis(req, res)) return;
  const { planta, periodoA, periodoB } = req.body || {};
  const pa = (typeof periodoA === "string" && /^\d{4}-\d{2}$/.test(periodoA)) ? periodoA : null;
  const pb = (typeof periodoB === "string" && /^\d{4}-\d{2}$/.test(periodoB)) ? periodoB : null;
  if (!planta || typeof planta !== "string" || !planta.trim()) {
    return res.status(400).json({ error: "Falta planta" });
  }
  if (!pa || !pb) {
    return res.status(400).json({ error: "Faltan periodoA y periodoB (formato YYYY-MM)" });
  }
  if (pa === pb) {
    return res.status(400).json({ error: "Los dos periodos deben ser distintos" });
  }
  const [yA, mA] = pa.split("-").map((s) => parseInt(s, 10));
  const [yB, mB] = pb.split("-").map((s) => parseInt(s, 10));
  if (!Number.isFinite(yA) || !Number.isFinite(mA) || !Number.isFinite(yB) || !Number.isFinite(mB)) {
    return res.status(400).json({ error: "Periodos inválidos" });
  }
  const client = await pool.connect();
  try {
    const gvChk = await assertGVPlantaNombreAccess(client, req.dashboardAuth, planta.trim());
    if (!gvChk.ok) return res.status(gvChk.status).json({ error: gvChk.error });
    const plantCode = await getPlantCodeArrFromPlantaNombre(client, planta.trim());
    const data = await deltaIngresoForecast.computeDeltaIngresoForecast(
      client,
      plantCode,
      yA,
      mA,
      yB,
      mB,
      getMargenKgPorPeriodo,
      planta.trim()
    );
    res.json(data);
  } catch (e) {
    console.error("[Dashboard delta-ingreso-forecast-datos]", e);
    res.status(500).json({ error: e.message });
  } finally {
    client.release();
  }
});

/** Delta Ingreso Cliente Forecast (DICF): solo planta, 60 días historial, proyección a cierre del mes. Sin periodo A/B. */
app.post("/api/dashboard/dicf-datos", dashboardAuthMiddleware, async (req, res) => {
  if (dashboardBlockGAFinancialKpis(req, res)) return;
  const { planta } = req.body || {};
  if (!planta || typeof planta !== "string" || !planta.trim()) {
    return res.status(400).json({ error: "Falta planta" });
  }
  const client = await pool.connect();
  try {
    const gvChk = await assertGVPlantaNombreAccess(client, req.dashboardAuth, planta.trim());
    if (!gvChk.ok) return res.status(gvChk.status).json({ error: gvChk.error });
    const plantCode = await getPlantCodeArrFromPlantaNombre(client, planta.trim());
    const data = await dicf.computeDicf(client, plantCode, planta.trim(), getMargenKgPorPeriodo);
    const { dicfRowsByCliente: _dicfRows, ...rest } = data || {};

    // Indicador de acciones DICF abiertas (sin cerrar): incluye sin_compromiso, pendiente, vencido, etc.
    // Resolución de planta: MISMA que createAccion / Delta (alias "GTM San Luis" → San Luis). La consulta directa
    // a public.plantas sin alias devolvía null y no cargaba ninguna acción.
    const plantaIdRaw = await dicfAccionesLib.resolvePlantaId(client, planta.trim());
    const canonPlantaId = Number.isFinite(plantaIdRaw) ? dicfAccionesLib.getCanonicalPlantaId(plantaIdRaw) : null;
    const plantaIdsEquiv =
      Number.isFinite(canonPlantaId) && canonPlantaId != null
        ? dicfAccionesLib.getPlantaIdsEquivalentes(canonPlantaId)
        : [];
    const accionesAbiertasByKey = new Map();
    const accionesAbiertasByNombre = new Map();
    if (plantaIdsEquiv.length) {
      const arKey = await client.query(
        `SELECT cliente_key, COUNT(*)::int AS c
           FROM arr.dicf_acciones
          WHERE planta_id = ANY($1::int[])
            AND (cerrado_at IS NULL)
            AND (estado IS NULL OR estado <> 'hecho')
          GROUP BY cliente_key`,
        [plantaIdsEquiv]
      );
      for (const row of arKey.rows || []) {
        if (row.cliente_key) accionesAbiertasByKey.set(String(row.cliente_key), Number(row.c) || 0);
      }
      const arNom = await client.query(
        `SELECT cliente_nombre, COUNT(*)::int AS c
           FROM arr.dicf_acciones
          WHERE planta_id = ANY($1::int[])
            AND (cerrado_at IS NULL)
            AND (estado IS NULL OR estado <> 'hecho')
          GROUP BY cliente_nombre`,
        [plantaIdsEquiv]
      );
      for (const row of arNom.rows || []) {
        const k = dicfAccionesLib.normalizeKeyPart(row.cliente_nombre);
        accionesAbiertasByNombre.set(k, (accionesAbiertasByNombre.get(k) || 0) + (Number(row.c) || 0));
      }
    }
    const inject = (grp, grupoLista) => {
      if (!grp || !Array.isArray(grp.clientes)) return grp;
      return {
        ...grp,
        clientes: grp.clientes.map((c) => {
          const canal = (c.canal != null && String(c.canal).trim()) || "";
          const subcanal = (c.subcanal != null && String(c.subcanal).trim()) || "";
          const cli = (c.cliente != null && String(c.cliente).trim()) || "";
          const gruposTry = new Set(
            [String(c.estado || "").trim(), typeof grupoLista === "string" ? grupoLista.trim() : ""].filter(
              (x) => x && x.length
            )
          );
          let n = 0;
          if (canonPlantaId != null && Number.isFinite(canonPlantaId)) {
            for (const g of gruposTry) {
              const ck = dicfAccionesLib.buildClienteKey(canonPlantaId, g, canal, subcanal, cli);
              n = Math.max(n, accionesAbiertasByKey.get(ck) || 0);
            }
          }
          if (!n) {
            const nk = dicfAccionesLib.normalizeKeyPart(c && c.cliente != null ? c.cliente : "");
            n = accionesAbiertasByNombre.get(nk) || 0;
          }
          return { ...c, acciones_abiertas: n };
        }),
      };
    };
    const out = {
      ...rest,
      dejaron: inject(rest.dejaron, "Dejaron de comprar"),
      disminuyeron: inject(rest.disminuyeron, "Disminuyeron"),
      aumentaron: inject(rest.aumentaron, "Aumentaron"),
      nuevos: inject(rest.nuevos, "Nuevo"),
    };
    res.json(out);
  } catch (e) {
    console.error("[Dashboard dicf-datos]", e);
    res.status(500).json({ error: e.message });
  } finally {
    client.release();
  }
});

/** Excel Delta Ingreso Cliente Forecast: hojas venta Ton, desc $/kg, margen, ingreso — A=Cliente, B=Estatus, C=Categoría (canal), D=Subcategoría, luego meses y últimos N días. */
app.get("/api/dashboard/dicf-excel", dashboardAuthMiddleware, async (req, res) => {
  if (dashboardBlockGAFinancialKpis(req, res)) return;
  if (dashboardBlockGVForbidden(req, res)) return;
  const planta = (req.query.planta || "").toString().trim();
  if (!planta) return res.status(400).json({ error: "Falta planta" });
  const client = await pool.connect();
  try {
    const plantCode = await getPlantCodeArrFromPlantaNombre(client, planta);
    const data = await dicf.computeDicfExcel(client, plantCode, planta, getMargenKgPorPeriodo);
    const excelData = data.excelData;
    if (!excelData || !excelData.dates || !excelData.clientes) {
      return res.status(400).json({ error: "Sin datos para Excel (ejecuta primero Delta Ingreso Cliente Forecast)" });
    }
    const dates = excelData.dates;
    const margen = excelData.margen != null && Number.isFinite(excelData.margen) ? excelData.margen : 0;
    let clientes = excelData.clientes || [];
    const canal = (req.query.canal || "").toString().trim();
    const subcanal = (req.query.subcanal || "").toString().trim();
    const tipo = (req.query.tipo || "").toString().trim().toLowerCase();
    const ESTADO_BY_TIPO = { dejaron: "Dejaron de comprar", nuevos: "Nuevo", aumentaron: "Aumentaron", disminuyeron: "Disminuyeron" };
    if (canal !== "" && subcanal !== "" && tipo !== "" && ESTADO_BY_TIPO[tipo]) {
      const estadoFilter = ESTADO_BY_TIPO[tipo];
      clientes = clientes.filter(
        (c) => (c.canal || "") === canal && (c.subcanal || "") === subcanal && (c.estado || "") === estadoFilter
      );
    }
    const meses = excelData.meses || [];
    const margenPorMes = excelData.margenPorMes || [];

    const wb = XLSX.utils.book_new();

    const monthHeaders = [];
    for (const m of meses) {
      monthHeaders.push(`Venta ${m.label}`, `Descuento ${m.label}`, `Margen ${m.label}`);
    }
    const headerRow = ["Cliente", "Estatus", "Categoría", "Subcategoría", ...monthHeaders, ...dates];
    const numCols = dates.length;
    const pad = (arr, len, fill) => {
      const a = (arr || []).slice(0, len);
      while (a.length < len) a.push(fill);
      return a;
    };
    const numMeses = meses.length;
    const monthValsForClient = (c) => {
      const ventaPorMes = (c.ventaPorMes || []).slice(0, numMeses);
      const descuentoPorMes = (c.descuentoPorMes || []).slice(0, numMeses);
      const out = [];
      for (let i = 0; i < numMeses; i++) {
        const v = ventaPorMes[i];
        const d = descuentoPorMes[i];
        const mg = margenPorMes[i];
        out.push(v != null && Number.isFinite(v) ? v : "");
        out.push(d != null && Number.isFinite(d) ? d : "");
        out.push(mg != null && Number.isFinite(mg) ? mg : "");
      }
      return out;
    };

    const sheet1Rows = [headerRow];
    for (const c of clientes) {
      const raw = (c.kgLast30 || []).map((v) => (v != null && Number.isFinite(v) ? v : ""));
      const tonValues = pad(raw, numCols, "");
      sheet1Rows.push([c.cliente || "", c.estado || "", c.canal || "", c.subcanal || "", ...monthValsForClient(c), ...tonValues]);
    }
    const ws1 = XLSX.utils.aoa_to_sheet(sheet1Rows);
    XLSX.utils.book_append_sheet(wb, ws1, "Venta (Ton)");

    const sheet2Rows = [headerRow];
    for (const c of clientes) {
      const raw = (c.descKgLast30 || []).map((v) => (v != null && Number.isFinite(v) ? Number(v.toFixed(4)) : ""));
      const descValues = pad(raw, numCols, "");
      sheet2Rows.push([c.cliente || "", c.estado || "", c.canal || "", c.subcanal || "", ...monthValsForClient(c), ...descValues]);
    }
    const ws2 = XLSX.utils.aoa_to_sheet(sheet2Rows);
    XLSX.utils.book_append_sheet(wb, ws2, "Descuento ($ por kg)");

    const sheet3Rows = [headerRow];
    for (const c of clientes) {
      const margenValues = dates.map(() => margen);
      sheet3Rows.push([c.cliente || "", c.estado || "", c.canal || "", c.subcanal || "", ...monthValsForClient(c), ...margenValues]);
    }
    const ws3 = XLSX.utils.aoa_to_sheet(sheet3Rows);
    XLSX.utils.book_append_sheet(wb, ws3, "Margen ($ por kg)");

    const ingresoHeaders = ["Cliente", "Estatus", "Categoría", "Subcategoría", ...meses.map((m) => `Ingreso ${m.label}`)];
    const ingresoRows = [ingresoHeaders];
    for (const c of clientes) {
      const ventaPorMes = (c.ventaPorMes || []).slice(0, numMeses);
      const descuentoPorMes = (c.descuentoPorMes || []).slice(0, numMeses);
      const ingresoVals = [];
      for (let i = 0; i < numMeses; i++) {
        const v = ventaPorMes[i] != null && Number.isFinite(ventaPorMes[i]) ? ventaPorMes[i] : 0;
        const d = descuentoPorMes[i] != null && Number.isFinite(descuentoPorMes[i]) ? descuentoPorMes[i] : 0;
        const mg = margenPorMes[i] != null && Number.isFinite(margenPorMes[i]) ? margenPorMes[i] : 0;
        const ingreso = v * 1000 * mg - Math.abs(Number(d));
        ingresoVals.push(Number.isFinite(ingreso) ? Math.round(ingreso * 100) / 100 : "");
      }
      ingresoRows.push([c.cliente || "", c.estado || "", c.canal || "", c.subcanal || "", ...ingresoVals]);
    }
    const wsIngreso = XLSX.utils.aoa_to_sheet(ingresoRows);
    XLSX.utils.book_append_sheet(wb, wsIngreso, "Ingreso por cliente");

    const buf = XLSX.write(wb, { type: "buffer", bookType: "xlsx" });
    let filename = `Delta_Ingreso_Cliente_Forecast_${planta.replace(/\s+/g, "_")}_${data.periodoMes || "mes"}.xlsx`;
    if (canal !== "" && subcanal !== "" && tipo !== "") {
      const safe = (s) => (s || "").replace(/[\s/\\?*:[\]]+/g, "_");
      filename = `Delta_Ingreso_Cliente_Forecast_${planta.replace(/\s+/g, "_")}_${safe(canal)}_${safe(subcanal)}_${tipo}.xlsx`;
    }
    res.setHeader("Content-Type", "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet");
    res.setHeader("Content-Disposition", `attachment; filename="${filename}"`);
    res.send(buf);
  } catch (e) {
    console.error("[Dashboard dicf-excel]", e);
    res.status(500).json({ error: e.message });
  } finally {
    client.release();
  }
});

/** Obtener parámetros DICF editables para una planta y mes (year, month). */
app.get("/api/dashboard/dicf-config", dashboardAuthMiddleware, async (req, res) => {
  if (dashboardBlockGAFinancialKpis(req, res)) return;
  const planta = (req.query.planta || "").toString().trim();
  const year = parseInt(req.query.year, 10);
  const month = parseInt(req.query.month, 10);
  if (!planta || !Number.isFinite(year) || !Number.isFinite(month) || month < 1 || month > 12) {
    return res.status(400).json({ error: "Faltan planta, year o month válidos" });
  }
  const client = await pool.connect();
  try {
    const gvChk = await assertGVPlantaNombreAccess(client, req.dashboardAuth, planta);
    if (!gvChk.ok) return res.status(gvChk.status).json({ error: gvChk.error });
    const plantCode = await getPlantCodeArrFromPlantaNombre(client, planta);
    const r = await client.query(
      `SELECT window_days, tolerancia_dias, umbral_mxn, umbral_pct_neg, umbral_pct_pos, min_kg_hist
       FROM arr.dicf_config WHERE UPPER(TRIM(plant_code)) = UPPER(TRIM($1)) AND year = $2 AND month = $3`,
      [plantCode, year, month]
    );
    const row = r.rows?.[0];
    res.json({
      planta,
      year,
      month,
      window_days: row?.window_days != null ? Number(row.window_days) : 60,
      tolerancia_dias: row?.tolerancia_dias != null ? Number(row.tolerancia_dias) : 2,
      umbral_mxn: row?.umbral_mxn != null ? Number(row.umbral_mxn) : 50000,
      umbral_pct_neg: row?.umbral_pct_neg != null ? Number(row.umbral_pct_neg) : 0.15,
      umbral_pct_pos: row?.umbral_pct_pos != null ? Number(row.umbral_pct_pos) : 0.15,
      min_kg_hist: row?.min_kg_hist != null ? Number(row.min_kg_hist) : 0,
    });
  } catch (e) {
    console.error("[Dashboard dicf-config GET]", e);
    res.status(500).json({ error: e.message });
  } finally {
    client.release();
  }
});

/** Guardar parámetros DICF editables (upsert por planta, year, month). */
app.post("/api/dashboard/dicf-config", dashboardAuthMiddleware, async (req, res) => {
  if (dashboardBlockGAFinancialKpis(req, res)) return;
  if (dashboardBlockGVForbidden(req, res)) return;
  const { planta, year, month, window_days, tolerancia_dias, umbral_mxn, umbral_pct_neg, umbral_pct_pos, min_kg_hist } = req.body || {};
  const y = parseInt(year, 10);
  const m = parseInt(month, 10);
  if (!planta || typeof planta !== "string" || !planta.trim() || !Number.isFinite(y) || !Number.isFinite(m) || m < 1 || m > 12) {
    return res.status(400).json({ error: "Faltan planta, year o month válidos" });
  }
  const client = await pool.connect();
  try {
    const plantCode = await getPlantCodeArrFromPlantaNombre(client, planta.trim());
    const wd = window_days != null && Number(window_days) > 0 ? Math.max(1, Math.min(365, Number(window_days))) : 60;
    const td = tolerancia_dias != null && Number(tolerancia_dias) >= 0 ? Number(tolerancia_dias) : 2;
    const umxn = umbral_mxn != null && !Number.isNaN(Number(umbral_mxn)) ? Number(umbral_mxn) : 50000;
    const upn = umbral_pct_neg != null && !Number.isNaN(Number(umbral_pct_neg)) ? Number(umbral_pct_neg) : 0.15;
    const upp = umbral_pct_pos != null && !Number.isNaN(Number(umbral_pct_pos)) ? Number(umbral_pct_pos) : 0.15;
    const mkg = min_kg_hist != null && !Number.isNaN(Number(min_kg_hist)) ? Number(min_kg_hist) : 0;
    await client.query(
      `INSERT INTO arr.dicf_config (plant_code, year, month, window_days, tolerancia_dias, umbral_mxn, umbral_pct_neg, umbral_pct_pos, min_kg_hist)
       VALUES ($1, $2, $3, $4, $5, $6, $7, $8, $9)
       ON CONFLICT (plant_code, year, month) DO UPDATE SET
         window_days = EXCLUDED.window_days,
         tolerancia_dias = EXCLUDED.tolerancia_dias,
         umbral_mxn = EXCLUDED.umbral_mxn,
         umbral_pct_neg = EXCLUDED.umbral_pct_neg,
         umbral_pct_pos = EXCLUDED.umbral_pct_pos,
         min_kg_hist = EXCLUDED.min_kg_hist`,
      [plantCode, y, m, wd, td, umxn, upn, upp, mkg]
    );
    res.json({ ok: true, planta: planta.trim(), year: y, month: m, window_days: wd });
  } catch (e) {
    console.error("[Dashboard dicf-config POST]", e);
    res.status(500).json({ error: e.message });
  } finally {
    client.release();
  }
});

/** Clave estable cliente DICF (planta + grupo + canal + subcanal + nombre). */
